window.RF_FULL=window.RF_FULL||{};window.RF_FULL["fz132tour"]=[
["0","Преамбула и список изменений","","2026-07-04","РОССИЙСКАЯ ФЕДЕРАЦИЯ ФЕДЕРАЛЬНЫЙ ЗАКОН Об основах туристской деятельности в Российской Федерации\nПринят Государственной Думой 4 октября 1996 года\nОдобрен Советом Федерации 14 ноября 1996 года\nСписок изменяющих документов(В редакции федеральных законов от 10.01.2003 № 15-ФЗ, от 22.08.2004 № 122-ФЗ, от 05.02.2007 № 12-ФЗ, от 30.12.2008 № 309-ФЗ, от 28.06.2009 № 123-ФЗ, от 27.12.2009 № 365-ФЗ, от 30.07.2010 № 242-ФЗ, от 01.07.2011 № 169-ФЗ, от 03.05.2012 № 47-ФЗ, от 29.06.2015 № 155-ФЗ, от 02.03.2016 № 49-ФЗ, от 05.04.2016 № 104-ФЗ, от 28.12.2016 № 465-ФЗ, от 05.02.2018 № 16-ФЗ, от 18.04.2018 № 71-ФЗ, от 04.06.2018 № 149-ФЗ, от 03.07.2019 № 170-ФЗ, от 16.10.2019 № 336-ФЗ, от 02.12.2019 № 419-ФЗ, от 01.04.2020 № 98-ФЗ, от 08.06.2020 № 166-ФЗ, от 09.03.2021 № 45-ФЗ, от 24.03.2021 № 48-ФЗ, от 20.04.2021 № 93-ФЗ, от 11.06.2021 № 170-ФЗ, от 02.07.2021 № 318-ФЗ, от 02.07.2021 № 343-ФЗ, от 02.07.2021 № 352-ФЗ, от 28.05.2022 № 148-ФЗ, от 13.06.2023 № 252-ФЗ, от 25.12.2023 № 639-ФЗ, от 23.03.2024 № 63-ФЗ, от 22.06.2024 № 143-ФЗ, от 08.08.2024 № 256-ФЗ, от 14.10.2024 № 346-ФЗ, от 30.11.2024 № 436-ФЗ, от 13.12.2024 № 475-ФЗ, от 28.02.2025 № 26-ФЗ, от 07.06.2025 № 143-ФЗ, от 24.06.2025 № 183-ФЗ, от 24.06.2025 № 184-ФЗ, от 23.07.2025 № 238-ФЗ, от 23.07.2025 № 260-ФЗ, от 31.07.2025 № 304-ФЗ, от 29.12.2025 № 552-ФЗ, от 29.12.2025 № 553-ФЗ, от 29.12.2025 № 579-ФЗ, от 04.07.2026 № 235-ФЗ)\n(С учетом Постановления Правительства Российской Федерации от 12.03.2022 № 353)\nНастоящий Федеральный закон определяет принципы государственной политики, направленной на установление правовых основ единого туристского рынка в Российской Федерации, и регулирует отношения, возникающие при реализации права граждан Российской Федерации, иностранных граждан и лиц без гражданства на отдых, свободу передвижения и иных прав при совершении путешествий, а также определяет порядок рационального использования туристских ресурсов Российской Федерации."],
["1","Основные понятия","Глава I. Общие положения","2026-07-04","Статья 1. Основные понятия\nИнституты, понятия и термины гражданского, семейного законодательства и других отраслей законодательства Российской Федерации, используемые в настоящем Федеральном законе, применяются в том значении, в котором они используются в этих отраслях законодательства, если иное не предусмотрено настоящим Федеральным законом. В целях настоящего Федерального закона используются следующие основные понятия: (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nтуризм - временные выезды (путешествия) граждан Российской Федерации, иностранных граждан и лиц без гражданства (далее - лица) с постоянного места жительства в лечебно-оздоровительных, рекреационных, познавательных, физкультурно-спортивных, профессионально-деловых и иных целях без занятия деятельностью, связанной с получением дохода от источников в стране (месте) временного пребывания; (В редакции Федерального закона от 03.07.2019 № 170-ФЗ)\nтуристская деятельность - туроператорская и турагентская деятельность, а также иная деятельность по организации путешествий;\nтуризм внутренний - туризм в пределах территории Российской Федерации лиц, постоянно проживающих в Российской Федерации;\nтуризм выездной - туризм лиц, постоянно проживающих в Российской Федерации, в другую страну;\nтуризм въездной - туризм в пределах территории Российской Федерации лиц, не проживающих постоянно в Российской Федерации;\nтуризм международный - туризм выездной или въездной;\nтуризм социальный - туризм, полностью или частично осуществляемый за счет бюджетных средств, средств государственных внебюджетных фондов (в том числе средств, выделяемых в рамках государственной социальной помощи), а также средств работодателей;\nтуризм самодеятельный - туризм, организуемый туристами самостоятельно;\nтурист - лицо, посещающее страну (место) временного пребывания в лечебно-оздоровительных, рекреационных, познавательных, физкультурно-спортивных, профессионально-деловых и иных целях без занятия деятельностью, связанной с получением дохода от источников в стране (месте) временного пребывания, на период от 24 часов до 6 месяцев подряд или осуществляющее не менее одной ночевки в стране (месте) временного пребывания; (В редакции Федерального закона от 03.07.2019 № 170-ФЗ)\nтуристские ресурсы - природные, исторические, социально-культурные объекты, включающие объекты туристского показа, а также иные объекты, способные удовлетворить духовные и иные потребности туристов, содействовать поддержанию их жизнедеятельности, восстановлению и развитию их физических сил;\nтуристская индустрия - комплексная сфера экономической деятельности, связанная с использованием туристских ресурсов и объектов туристской индустрии в целях предоставления туристских услуг, в том числе в составе туристских продуктов, и иных услуг, обеспечивающих потребности туристов, включая услуги по питанию, перевозке, санаторно-курортному лечению, информационному обеспечению, игорно-развлекательные и конгрессно-выставочные услуги; (В редакции Федерального закона от 23.07.2025 № 260-ФЗ)\nтуристский продукт - комплекс услуг, предоставляемых за общую цену по договору о реализации туристского продукта, формируемого с учетом особенностей, установленных настоящим Федеральным законом; (В редакции Федерального закона от 29.12.2025 № 553-ФЗ)\nтуроператорская деятельность - деятельность по формированию, продвижению и реализации туристского продукта, осуществляемая юридическим лицом (далее - туроператор);\nтурагентская деятельность - деятельность по продвижению и реализации туристского продукта, осуществляемая юридическим лицом или индивидуальным предпринимателем, сведения о которых внесены в единый федеральный реестр турагентов, субагентов в порядке, предусмотренном настоящим Федеральным законом (далее - турагент); (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nсубагент - юридическое лицо или индивидуальный предприниматель, которым турагентом передано исполнение поручения туроператора на продвижение и реализацию туристского продукта в порядке, предусмотренном настоящим Федеральным законом, и сведения о которых внесены в единый федеральный реестр турагентов, субагентов в порядке, предусмотренном настоящим Федеральным законом; (Дополнение абзацем - Федеральный закон от 24.03.2021 № 48-ФЗ)\nзаказчик туристского продукта - турист или иное лицо, заказывающее туристский продукт от имени туриста, в том числе законный представитель несовершеннолетнего туриста;\nформирование туристского продукта - деятельность туроператора по заключению и исполнению договоров с третьими лицами, оказывающими отдельные услуги, входящие в туристский продукт (средства размещения, перевозчики, экскурсоводы (гиды) и другие); (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nпродвижение туристского продукта - комплекс мер, направленных на реализацию туристского продукта (реклама, участие в специализированных выставках, ярмарках, организация туристских информационных центров, издание каталогов, буклетов и другое);\nреализация туристского продукта - деятельность туроператора или турагента по заключению договора о реализации туристского продукта с туристом или иным заказчиком туристского продукта, а также деятельность туроператора и (или) третьих лиц по оказанию туристу услуг в соответствии с данным договором;\nобщая цена туристского продукта в сфере выездного туризма - величина, полученная путем суммирования общих цен туристского продукта, указанных в договорах о реализации туристского продукта в сфере выездного туризма, заключенных туроператором и турагентами по поручению туроператора; (Дополнение абзацем - Федеральный закон от 23.07.2025 № 238-ФЗ)\nэкскурсант - лицо, посещающее страну (место) временного пребывания в познавательных целях на период менее 24 часов без ночевки в стране (месте) временного пребывания и использующее услуги экскурсовода (гида), гида-переводчика, инструктора-проводника; (В редакции Федерального закона от 20.04.2021 № 93-ФЗ)\nэкскурсовод (гид) - лицо, являющееся гражданином Российской Федерации, если иное не предусмотрено международными договорами Российской Федерации, прошедшее аттестацию, оказывающее в очной форме услуги по ознакомлению туристов (экскурсантов) с объектами показа, сопровождению туристов (экскурсантов) и информированию туристов (экскурсантов) по пути следования по туристскому маршруту на основании договора, заключенного в соответствии с законодательством Российской Федерации; (В редакции Федерального закона от 22.06.2024 № 143-ФЗ)\nгид-переводчик - лицо, являющееся гражданином Российской Федерации, если иное не предусмотрено международными договорами Российской Федерации, прошедшее аттестацию, свободно владеющее иностранным языком, знание которого необходимо для оказания в очной форме туристам (экскурсантам) услуг гида-переводчика по ознакомлению туристов (экскурсантов) с объектами показа, сопровождению туристов (экскурсантов) и информированию туристов (экскурсантов) по пути следования по туристскому маршруту. Оказание услуг гида-переводчика осуществляется на основании договора, заключенного в соответствии с законодательством Российской Федерации; (В редакции Федерального закона от 22.06.2024 № 143-ФЗ)\n(Абзац с 01.03.2027 в редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nинструктор-проводник - лицо, прошедшее аттестацию, сопровождающее туристов (экскурсантов) и обеспечивающее их безопасность при прохождении туристского маршрута (части туристского маршрута) определенных Правительством Российской Федерации вида и категории сложности, при прохождении которого туристами (экскурсантами) требуется специальное сопровождение (далее - туристский маршрут, требующий специального сопровождения); (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 03.05.2012 № 47-ФЗ)\nэкстренная помощь - действия по организации перевозки туриста из страны временного пребывания (оплата услуг по перевозке) и (или) иные действия (в том числе оплата услуг по размещению), осуществляемые объединением туроператоров в сфере выездного туризма в соответствии с настоящим Федеральным законом в случае неисполнения туроператором своих обязательств по договору о реализации туристского продукта в сфере выездного туризма в части неоказания полностью или частично туристу входящих в него услуг по перевозке и (или) размещению в связи с прекращением туроператорской деятельности по причине невозможности исполнения всех обязательств по договорам о реализации туристского продукта; (Дополнение абзацем - Федеральный закон от 03.05.2012 № 47-ФЗ) (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nэлектронная путевка - документ, сформированный в электронной форме в единой информационной системе электронных путевок на основе сведений, содержащихся в договоре о реализации туристского продукта и представленных туроператором в порядке, установленном настоящим Федеральным законом; (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 28.05.2022 № 148-ФЗ)\nсельский туризм - туризм, предусматривающий посещение винодельческих хозяйств, сельской местности, малых городов с численностью населения до тридцати тысяч человек в целях отдыха, приобщения к традиционному укладу жизни и обычаям народов Российской Федерации, ознакомления с объектами культурного наследия (памятниками истории и культуры) народов Российской Федерации, связанными с сельским хозяйством, а также ознакомления с сельскохозяйственным производством и (или) участия в сельскохозяйственных работах без извлечения материальной выгоды с возможностью использования услуг по временному размещению, организации досуга, экскурсионных и иных услуг; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 318-ФЗ) (В редакции федеральных законов от 14.10.2024 № 346-ФЗ, от 29.12.2025 № 579-ФЗ)\n(Абзац с 01.03.2027 в редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nтуризм детский - туризм организованной группы несовершеннолетних туристов в сопровождении руководителя, который несет обязанности их законного представителя; (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ)\nсистема навигации и ориентирования в сфере туризма - совокупность необходимой для ориентирования туристов информации о туристских ресурсах и об объектах туристской индустрии и о способах размещения такой информации (информационных знаков, конструкций, сооружений, технических приспособлений и других носителей, предназначенных для распространения информации, за исключением рекламных конструкций); (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nтуристский информационный центр - организация, осуществляющая деятельность по информированию физических и юридических лиц о туристских ресурсах и об объектах туристской индустрии, а также продвижению туристских продуктов на внутреннем и мировом туристских рынках; (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 18.04.2018 № 71-ФЗ)\nтуристский маршрут - путь следования туристов (экскурсантов), включающий в себя посещение и (или) использование туристских ресурсов; (Дополнение абзацем - Федеральный закон от 28.12.2016 № 465-ФЗ)\nсредство размещения - имущественный комплекс, включающий в себя здание (часть здания) или строение, сооружение, помещение, участок земли, оборудование и иное имущество и используемый для временного размещения и обеспечения временного проживания физических лиц. К средствам размещения не относятся жилые помещения, за исключением случаев, предусмотренных другими федеральными законами; (Дополнение абзацем - Федеральный закон от 05.02.2018 № 16-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nгостиница - тип средства размещения, в котором предоставляются гостиничные услуги и которое соответствует требованиям, установленным положением о классификации средств размещения, утвержденным Правительством Российской Федерации; (Дополнение абзацем - Федеральный закон от 05.02.2018 № 16-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nгостиничные услуги - комплекс услуг по предоставлению физическим лицам мест для временного проживания в гостинице и иных услуг, предусмотренных Правилами предоставления гостиничных услуг в Российской Федерации, утвержденными Правительством Российской Федерации, которые предоставляются индивидуальными предпринимателями и юридическими лицами; (Дополнение абзацем- Федеральный закон от 05.02.2018 № 16-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nклассификация средства размещения - присвоение средству размещения определенного типа, установленного положением о классификации средств размещения, утвержденным Правительством Российской Федерации, и при наличии условий, установленных правилами классификации средств размещения, утвержденными Правительством Российской Федерации, определенной категории на основании оценки соответствия средств размещения и предоставляемых в них услуг требованиям, установленным указанным положением; (Дополнение абзацем - Федеральный закон от 05.02.2018 № 16-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nклассификация горнолыжных трасс, классификация пляжей - присвоение горнолыжной трассе, пляжу определенной категории, установленной правилами классификации горнолыжных трасс, классификации пляжей, утвержденными уполномоченным федеральным органом исполнительной власти, на основании оценки соответствия горнолыжных трасс, пляжей требованиям, установленным этими правилами; (Дополнение абзацем - Федеральный закон от 05.02.2018 № 16-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nнациональный туристский маршрут - туристский маршрут, имеющий особое значение для развития внутреннего туризма и въездного туризма и определяемый уполномоченным федеральным органом исполнительной власти в соответствии с порядком, установленным Правительством Российской Федерации; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ)\nединая информационная система электронных путевок - государственная информационная система, функционирующая на основе программных, технических средств и информационных технологий и обеспечивающая сбор, обработку, хранение, предоставление, размещение и использование сведений, содержащихся в договорах о реализации туристского продукта, и иных сведений, подлежащих представлению туроператором в единую информационную систему электронных путевок, в порядке, установленном настоящим Федеральным законом; (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)\nуслуги средства размещения - гостиничные услуги, услуги иных средств размещения, включающие в себя комплекс услуг по предоставлению физическим лицам мест для временного проживания в средстве размещения, а также иные услуги по обслуживанию проживающих в средстве размещения физических лиц; (Дополнение абзацем - Федеральный закон от 30.11.2024 № 436-ФЗ)\nобъекты туристской индустрии - вид туристских ресурсов, включающих в себя помещения, здания, строения, сооружения, транспортные средства и иные объекты, принадлежащие субъектам туристской индустрии на праве собственности, аренды или на ином законном основании и используемые для оказания туристских услуг; (Дополнение абзацем - Федеральный закон от 23.07.2025 № 260-ФЗ)\nсубъекты туристской индустрии - юридические лица, индивидуальные предприниматели и физические лица, осуществляющие в соответствии с настоящим Федеральным законом деятельность, направленную на оказание туристских услуг туристам; (Дополнение абзацем - Федеральный закон от 23.07.2025 № 260-ФЗ)\nтуристские услуги - услуги, оказываемые субъектами туристской индустрии в соответствии с настоящим Федеральным законом, в том числе услуги туроператоров и турагентов, средств размещения, услуги экскурсовода (гида), гида-переводчика, инструктора-проводника, услуги, связанные с использованием горнолыжной трассы, пляжа. (Дополнение абзацем - Федеральный закон от 23.07.2025 № 260-ФЗ)\n(Статья в редакции Федерального закона от 05.02.2007 № 12-ФЗ)"],
["2","Законодательство Российской Федерации о туристской деятельности","Глава I. Общие положения","2019-07-03","Статья 2. Законодательство Российской Федерации о туристской деятельности\nЗаконодательство Российской Федерации о туристской деятельности состоит из настоящего Федерального закона, принимаемых в соответствии с ним федеральных законов и иных нормативных правовых актов Российской Федерации, а также законов и иных нормативных правовых актов субъектов Российской Федерации.\nЗаконы и иные нормативные правовые акты субъектов Российской Федерации, регулирующие туристскую деятельность, не могут противоречить настоящему Федеральному закону и принимаемым в соответствии с ним федеральным законам.\nСодержащиеся в других законах и нормативных правовых актах нормы, регулирующие туристскую деятельность, не должны противоречить настоящему Федеральному закону.\nОсобенности осуществления туристской деятельности, связанные с организацией и проведением XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, устанавливаются Федеральным законом от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\". (Дополнение частью - Федеральный закон от 30.07.2010 № 242-ФЗ)\nДействие настоящего Федерального закона не распространяется на паломническую деятельность, осуществляемую религиозными организациями, и на совершение и организацию паломниками собственных паломнических поездок в соответствии с Федеральным законом от 26 сентября 1997 года № 125-ФЗ \"О свободе совести и о религиозных объединениях\". (Дополнение частью - Федеральный закон от 03.07.2019 № 170-ФЗ)"],
["3","Принципы государственного регулирования туристской деятельности","Глава II. Государственное регулирование туристской деятельности","","Статья 3. Принципы государственного регулирования туристской деятельности\nГосударство, признавая туристскую деятельность одной из приоритетных отраслей экономики Российской Федерации, содействует туристской деятельности и создает благоприятные условия для ее развития;\nопределяет и поддерживает приоритетные направления туристской деятельности;\nформирует представление о Российской Федерации как стране, благоприятной для туризма;\nосуществляет поддержку и защиту российских туристов, туроператоров, турагентов и их объединений."],
["3.1","Полномочия органов государственной власти Российской Федерации в сфере туризма","Глава II. Государственное регулирование туристской деятельности","2026-07-04","Статья 3.1. Полномочия органов государственной власти Российской Федерации в сфере туризма\nК полномочиям органов государственной власти Российской Федерации в сфере туризма относятся:\nвыработка и реализация государственной политики в сфере туризма, в том числе формирование правовых основ единого туристского рынка в Российской Федерации, определение приоритетных направлений развития туризма в Российской Федерации;\nразработка, утверждение (одобрение) и реализация документов стратегического планирования в сфере туризма по вопросам, отнесенным к ведению Российской Федерации;\nсоздание и обеспечение благоприятных условий для развития туристской индустрии в Российской Федерации;\nустановление порядка оказания услуг по реализации туристского продукта;\nустановление порядка и условий оказания экстренной помощи туристам;\nустановление порядка и условий финансирования расходов на оказание экстренной помощи туристам из резервного фонда объединения туроператоров в сфере выездного туризма (далее также - резервный фонд);\nустановление требований к критериям отбора кредитных организаций, в которых допускается размещение средств резервного фонда, фондов персональной ответственности туроператоров в сфере выездного туризма (далее также - фонд персональной ответственности туроператора);\nформирование и ведение единого федерального реестра туроператоров;\nутверждение положения о классификации средств размещения; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nустановление порядка аккредитации и подтверждения компетентности организаций, осуществляющих классификацию средств размещения, классификацию горнолыжных трасс, классификацию пляжей (далее соответственно - организации, осуществляющие классификацию в сфере туристской индустрии, объекты классификации в сфере туристской индустрии), включающего в себя порядок аттестации экспертов по классификации; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nаккредитация организаций, осуществляющих классификацию в сфере туристской индустрии, а также подтверждение компетентности организаций, осуществляющих классификацию в сфере туристской индустрии; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nутверждение порядка уведомления организацией, осуществляющей классификацию в сфере туристской индустрии, уполномоченных органов государственной власти субъектов Российской Федерации о планируемом осуществлении классификации объектов классификации в сфере туристской индустрии на территории соответствующих субъектов Российской Федерации, включая перечень и описание сведений, содержащихся в таком уведомлении; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nутверждение правил классификации горнолыжных трасс, классификации пляжей;\nустановление порядка формирования и ведения реестра организаций, осуществляющих классификацию в сфере туристской индустрии; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nустановление порядка формирования и ведения единого реестра объектов классификации в сфере туристской индустрии; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nорганизация формирования и ведения реестра организаций, осуществляющих классификацию в сфере туристской индустрии, и единого реестра объектов классификации в сфере туристской индустрии; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nутверждение правил предоставления гостиничных услуг, устанавливающих в том числе виды и условия бронирования, а также при необходимости правил предоставления услуг иных средств размещения, устанавливающих в том числе виды и условия бронирования; (В редакции Федерального закона от 07.06.2025 № 143-ФЗ)\nутверждение правил профессиональной деятельности, регулирующих порядок осуществления объединением туроператоров в сфере выездного туризма и его членами функций, связанных с формированием и использованием резервного фонда;\nразработка национальных стандартов Российской Федерации в сфере туризма, профессиональных стандартов;\nобеспечение безопасности туризма, защита прав и законных интересов туристов на территории Российской Федерации и за пределами ее территории;\nинформирование туроператоров, турагентов и туристов (экскурсантов) об угрозе безопасности туристов (экскурсантов) в стране (месте) временного пребывания;\nинформационное обеспечение туризма, включая содействие в создании и функционировании туристских информационных центров, систем навигации и ориентирования в сфере туризма;\nсодействие в создании и обеспечении благоприятных условий для беспрепятственного доступа туристов (экскурсантов) к туристским ресурсам, находящимся на территориях субъектов Российской Федерации, и средствам связи, а также получения медицинской, правовой и иных видов неотложной помощи;\nорганизация и проведение мероприятий по продвижению туристских продуктов в сфере внутреннего туризма и въездного туризма на внутреннем и мировом туристских рынках;\nорганизация проведения научных исследований в сфере туризма;\nсодействие в организации профессионального образования, дополнительного образования и профессионального обучения в сфере туризма; (В редакции Федерального закона от 20.04.2021 № 93-ФЗ)\nучреждение государственных наград Российской Федерации, премий и других форм поощрения Российской Федерации в сфере туризма;\nутверждение методических рекомендаций по разработке и реализации государственных программ субъекта Российской Федерации и муниципальных программ развития туризма; (Дополнение абзацем - Федеральный закон от 09.03.2021 № 45-ФЗ)\nразработка и утверждение форм статистической отчетности, применяемых в сфере туризма;\nорганизация и проведение всероссийских и межрегиональных мероприятий, направленных на поддержку приоритетных направлений развития туризма, в том числе на развитие внутреннего туризма, въездного туризма, социального туризма, сельского туризма, детского туризма и самодеятельного туризма (далее - мероприятия в сфере туризма), утверждение и реализация календарного плана мероприятий в сфере туризма; (В редакции Федерального закона от 02.07.2021 № 318-ФЗ)\nосуществление взаимодействия с некоммерческими организациями, осуществляющими деятельность в сфере туризма, включая объединение туроператоров в сфере выездного туризма, в том числе по приоритетным направлениям развития туризма, вопросам обеспечения безопасности туризма, защиты прав и законных интересов туристов;\nосуществление взаимодействия с иностранными государствами, международными организациями в сфере туризма, в том числе через представительства уполномоченного Правительством Российской Федерации федерального органа исполнительной власти за пределами Российской Федерации;\nорганизация международных мероприятий в сфере туризма, в том числе направленных на формирование представления о Российской Федерации как стране, благоприятной для туризма, раскрытие туристского потенциала Российской Федерации и субъектов Российской Федерации;\nкоординация деятельности по реализации межправительственных соглашений в сфере туризма;\nустановление порядка ведения единого федерального реестра турагентов, субагентов (далее - реестр турагентов); (Дополнение абзацем - Федеральный закон от 24.03.2021 № 48-ФЗ)\nведение реестра турагентов; (Дополнение абзацем - Федеральный закон от 24.03.2021 № 48-ФЗ)\nразработка и организация реализации комплекса мер по организации экскурсий и путешествий с культурно-познавательными целями для лиц в возрасте до 23 лет, обучающихся в общеобразовательных организациях и профессиональных образовательных организациях; (В редакции Федерального закона от 24.06.2025 № 183-ФЗ)\nустановление порядка размещения сведений о национальных туристских маршрутах и об экскурсоводах (о гидах) или о гидах-переводчиках, прошедших аттестацию для национальных туристских маршрутов, на официальном сайте уполномоченного федерального органа исполнительной власти в информационно-телекоммуникационной сети \"Интернет\" и размещение таких сведений; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ)\nутверждение перечня организаций, уполномоченных на проведение аттестации инструкторов-проводников; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nустановление порядка определения национальных туристских маршрутов; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ)\nведение единого федерального реестра экскурсоводов (гидов) и гидов-переводчиков, формирование и ведение единого федерального реестра инструкторов-проводников; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции Федерального закона от 22.06.2024 № 143-ФЗ)\nустановление порядка отнесения туристского маршрута (части туристского маршрута) к туристским маршрутам, требующим специального сопровождения, включая порядок размещения сведений о туристских маршрутах, требующих специального сопровождения; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nустановление правил оказания услуг экскурсовода (гида), гида-переводчика, правил оказания услуг инструктора-проводника; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции Федерального закона от 22.06.2024 № 143-ФЗ)\nустановление видов туристских маршрутов, требующих специального сопровождения, категорий их сложности, а также критериев отнесения туристского маршрута к соответствующей категории сложности, в том числе с учетом обеспечения безопасности туристов (экскурсантов); (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nутверждение формы нагрудной идентификационной карточки инструктора-проводника; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 28.02.2025 № 26-ФЗ)\nабзац; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 318-ФЗ) (Утратил силу - Федеральный закон от 14.10.2024 № 346-ФЗ)\nустановление требований к средствам размещения, используемым для осуществления деятельности по оказанию услуг в сфере сельского туризма в сельской местности; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 318-ФЗ)\nустановление правил, порядка и условий осуществления отдельных видов туризма; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 318-ФЗ)\nутверждение методических рекомендаций по формированию туристских маршрутов. (Дополнение абзацем - Федеральный закон от 28.02.2025 № 26-ФЗ)\n(Абзац. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\nОрганы государственной власти Российской Федерации осуществляют иные полномочия в сфере туризма, установленные настоящим Федеральным законом, другими федеральными законами, нормативными правовыми актами Президента Российской Федерации и нормативными правовыми актами Правительства Российской Федерации. (Дополнение частью - Федеральный закон от 28.02.2025 № 26-ФЗ)\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 05.02.2018 № 16-ФЗ)"],
["3.2","Полномочия органов государственной власти субъектов Российской Федерации по созданию благоприятных условий для развития туризма в субъектах Российской Федерации","Глава II. Государственное регулирование туристской деятельности","2026-07-04","Статья 3.2. Полномочия органов государственной власти субъектов Российской Федерации по созданию благоприятных условий для развития туризма в субъектах Российской Федерации\nК полномочиям органов государственной власти субъектов Российской Федерации по созданию благоприятных условий для развития туризма в субъектах Российской Федерации относятся:\nопределение основных задач в сфере туризма и приоритетных направлений развития туризма в субъектах Российской Федерации;\nразработка, утверждение (одобрение) и реализация документов стратегического планирования в сфере туризма по вопросам, отнесенным к полномочиям субъектов Российской Федерации;\nсоздание благоприятных условий для развития туристской индустрии в субъектах Российской Федерации;\nсоздание и обеспечение благоприятных условий для беспрепятственного доступа туристов (экскурсантов) к туристским ресурсам, находящимся на территориях субъектов Российской Федерации, и средствам связи, а также получения медицинской, правовой и иных видов неотложной помощи;\nреализация мер по созданию системы навигации и ориентирования в сфере туризма на территориях субъектов Российской Федерации;\nабзац; (Утратил силу - Федеральный закон от 05.02.2018 № 16-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 05.02.2018 № 16-ФЗ)\nсодействие в продвижении туристских продуктов соответствующего субъекта Российской Федерации на внутреннем и мировом туристских рынках;\nреализация мер по поддержке приоритетных направлений развития туризма в субъектах Российской Федерации, в том числе социального туризма, сельского туризма, детского туризма и самодеятельного туризма; (В редакции Федерального закона от 02.07.2021 № 318-ФЗ)\nреализация комплекса мер по организации экскурсий и путешествий с культурно-познавательными целями для лиц в возрасте до 23 лет, обучающихся в общеобразовательных организациях и профессиональных образовательных организациях; (В редакции Федерального закона от 24.06.2025 № 183-ФЗ)\nорганизация и проведение мероприятий в сфере туризма на региональном и межмуниципальном уровне;\nучастие в реализации межправительственных соглашений в сфере туризма;\nучастие в информационном обеспечении туризма, создание в субъектах Российской Федерации туристских информационных центров и обеспечение их функционирования;\nсоздание аттестационной комиссии для аттестации экскурсоводов (гидов) и гидов-переводчиков, внесение сведений об экскурсоводах (о гидах) и о гидах-переводчиках в единый федеральный реестр экскурсоводов (гидов) и гидов-переводчиков; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ)\nутверждение формы нагрудной идентификационной карточки экскурсовода (гида) или гида-переводчика; (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ)\n(Абзац с 01.03.2027 в редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nорганизация и осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, а также утверждение положения о данном виде контроля (надзора); (Дополнение абзацем - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции федеральных законов от 23.03.2024 № 63-ФЗ, от 30.11.2024 № 436-ФЗ)\nутверждение положения об аттестационной комиссии, осуществляющей аттестацию экскурсоводов (гидов) или гидов-переводчиков, в том числе состава указанной аттестационной комиссии; (Дополнение абзацем - Федеральный закон от 22.06.2024 № 143-ФЗ)\nиные установленные настоящим Федеральным законом, другими федеральными законами полномочия.\nОрганы государственной власти субъектов Российской Федерации в сфере туризма вправе:\nучаствовать в реализации государственной политики в сфере туризма;\nучаствовать в реализации стратегий развития туризма, государственных программ Российской Федерации, федеральных целевых и иных программ развития туризма;\nучаствовать в организации и проведении международных мероприятий в сфере туризма, мероприятий в сфере туризма на всероссийском и межрегиональном уровне;\nучаствовать в организации профессионального образования, дополнительного образования и профессионального обучения в сфере туризма; (В редакции Федерального закона от 20.04.2021 № 93-ФЗ)\nучаствовать в организации проведения научных исследований в сфере туризма;\nосуществлять взаимодействие с некоммерческими организациями, осуществляющими деятельность в сфере туризма, включая объединение туроператоров в сфере выездного туризма, в том числе по приоритетным направлениям развития туризма, вопросам обеспечения безопасности туризма, защиты прав и законных интересов туристов;\nоказывать содействие в определении приоритетных направлений развития туризма, в том числе путем поддержки развития объектов туристской индустрии на территориях муниципальных образований;\nосуществлять отнесение туристских маршрутов (частей туристских маршрутов), проходящих по территории субъекта Российской Федерации, к туристским маршрутам, требующим специального сопровождения, и размещать сведения о туристских маршрутах, требующих специального сопровождения, на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\". (Дополнение абзацем - Федеральный закон от 23.03.2024 № 63-ФЗ)\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["3.3","Права органов местного самоуправления по созданию благоприятных условий для развития туризма","Глава II. Государственное регулирование туристской деятельности","2021-07-02","Статья 3.3. Права органов местного самоуправления по созданию благоприятных условий для развития туризма\nК правам органов местного самоуправления по созданию благоприятных условий для развития туризма относятся:\nреализация мер по развитию приоритетных направлений развития туризма на территориях муниципальных образований, в том числе социального туризма, сельского туризма, детского туризма и самодеятельного туризма; (В редакции Федерального закона от 02.07.2021 № 318-ФЗ)\nсодействие созданию благоприятных условий для беспрепятственного доступа туристов (экскурсантов) к туристским ресурсам, находящимся на территориях муниципальных образований, и средствам связи, а также получения медицинской, правовой и иных видов неотложной помощи;\nорганизация и проведение мероприятий в сфере туризма на муниципальном уровне;\nучастие в организации и проведении международных мероприятий в сфере туризма, мероприятий в сфере туризма на всероссийском, межрегиональном, региональном и межмуниципальном уровне;\nсодействие в создании и функционировании туристских информационных центров на территориях муниципальных образований;\nразработка, утверждение (одобрение) и реализация муниципальных программ развития туризма. (Дополнение абзацем - Федеральный закон от 09.03.2021 № 45-ФЗ)\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["4","Цели, приоритетные направления и способы государственного регулирования туристской деятельности","Глава II. Государственное регулирование туристской деятельности","2025-12-29","Статья 4. Цели, приоритетные направления и способы государственного регулирования туристской деятельности\nОсновными целями государственного регулирования туристской деятельности являются:\nобеспечение права граждан на отдых, свободу передвижения и иных прав при совершении путешествий;\nохрана окружающей среды; (В редакции Федерального закона от 30.12.2008 № 309-ФЗ)\nсоздание условий для деятельности, направленной на воспитание, образование и оздоровление туристов;\nразвитие туристской индустрии, обеспечивающей потребности граждан при совершении путешествий, создание новых рабочих мест, увеличение доходов государства и граждан Российской Федерации, развитие международных контактов, сохранение объектов туристского показа, рациональное использование природного и культурного наследия.\nПриоритетными направлениями государственного регулирования туристской деятельности являются поддержка и развитие внутреннего туризма, въездного туризма, социального туризма, сельского туризма, детского туризма и самодеятельного туризма. (В редакции федеральных законов от 02.03.2016 № 49-ФЗ, от 02.07.2021 № 318-ФЗ)\nГосударственное регулирование туристской деятельности в Российской Федерации осуществляется путем:\nопределения приоритетных направлений развития туризма в Российской Федерации;\nнормативного правового регулирования в сфере туризма;\nразработки и реализации федеральных, отраслевых целевых и региональных программ развития туризма;\nсодействия в продвижении туристского продукта на внутреннем и мировом туристских рынках;\nзащиты прав и интересов туристов, в том числе оказания им экстренной помощи, обеспечения их безопасности, а также обеспечения беспрепятственного доступа туристов из числа инвалидов к объектам туристской индустрии в соответствии с законодательством Российской Федерации о социальной защите инвалидов; (В редакции Федерального закона от 29.12.2025 № 552-ФЗ)\nсодействия кадровому обеспечению в сфере туризма;\nразвития научных исследований в сфере туризма;\nклассификации объектов туристской индустрии; (В редакции Федерального закона от 05.04.2016 № 104-ФЗ)\nформирования и ведения единого федерального реестра туроператоров (далее также - реестр туроператоров), ведения реестра турагентов; (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nинформационного обеспечения туризма;\nсоздания благоприятных условий для развития туристской индустрии;\nоказания государственных услуг в сфере туризма;\nвзаимодействия с иностранными государствами и международными организациями в сфере туризма, в том числе через представительства уполномоченного Правительством Российской Федерации федерального органа исполнительной власти за пределами Российской Федерации. (В редакции Федерального закона от 03.05.2012 № 47-ФЗ)\n(Часть в редакции Федерального закона от 05.02.2007 № 12-ФЗ)\nГосударственное регулирование туристской деятельности в Российской Федерации осуществляется уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти (далее - уполномоченный федеральный орган исполнительной власти). (В редакции Федерального закона от 03.05.2012 № 47-ФЗ)\nПорядок оказания услуг по реализации туристского продукта, порядок и условия оказания экстренной помощи туристам определяются Правительством Российской Федерации. (Дополнение частью - Федеральный закон от 05.02.2007 № 12-ФЗ) (В редакции Федерального закона от 03.05.2012 № 47-ФЗ)\nПорядок обеспечения условий доступности для инвалидов объектов туристской индустрии, подлежащих классификации в соответствии с законодательством Российской Федерации о туристской деятельности (за исключением объектов, относящихся к средствам размещения в соответствии с Федеральным законом от 7 июня 2025 года № 127-ФЗ \"О проведении эксперимента по предоставлению услуг гостевых домов\", и предоставляемых в них услуг), объем и содержание мер по обеспечению условий доступности для инвалидов указанных объектов и предоставляемых в них услуг устанавливаются в соответствии с законодательством Российской Федерации о социальной защите инвалидов уполномоченным федеральным органом исполнительной власти по согласованию с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере социальной защиты населения. (Дополнение частью - Федеральный закон от 29.12.2025 № 552-ФЗ)"],
["4.1","Условия осуществления туроператорской деятельности","Глава II. Государственное регулирование туристской деятельности","2025-07-31","Статья 4.1. Условия осуществления туроператорской деятельности\nВ целях защиты прав и законных интересов граждан и юридических лиц осуществление туроператорской деятельности на территории Российской Федерации допускается юридическим лицом при наличии у него договора или договоров страхования гражданской ответственности за неисполнение обязательств по договору о реализации туристского продукта и (или) банковской гарантии или банковских гарантий исполнения обязательств по договору о реализации туристского продукта (далее также - финансовое обеспечение ответственности туроператора), если иное не установлено настоящей статьей, и при условии соответствия лиц, занимающих должности руководителя туроператора, его заместителя, главного бухгалтера, иного должностного лица, на которое возлагается ведение бухгалтерского учета туроператора (далее - должностное лицо туроператора), требованиям, установленным частью третьей настоящей статьи.\nТуроператоры, осуществляющие деятельность в сфере выездного туризма, должны быть также членами объединения туроператоров в сфере выездного туризма, действующего в соответствии с настоящим Федеральным законом, и иметь фонд персональной ответственности туроператора в соответствии с настоящим Федеральным законом.\nДолжностное лицо туроператора должно соответствовать следующим требованиям:\nотсутствие неснятой или непогашенной судимости за какое-либо умышленное преступление;\nотсутствие факта совершения им более трех раз в течение одного года, предшествовавшего дню подачи в уполномоченный федеральный орган исполнительной власти документов для внесения сведений о туроператоре в реестр туроператоров, правонарушений в сфере туристской деятельности, ответственность за которые предусмотрена Кодексом Российской Федерации об административных правонарушениях; (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nотсутствие дисквалификации должностного лица туроператора на день, предшествовавший дню подачи в уполномоченный федеральный орган исполнительной власти документов для внесения сведений о туроператоре в реестр туроператоров; (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nотсутствие факта замещения должности руководителя туроператора, его заместителя, главного бухгалтера или иного должностного лица, на которое возлагается ведение бухгалтерского учета туроператора, в течение 12 месяцев, предшествовавших дню исключения сведений о туроператоре из реестра туроператоров по основаниям, предусмотренным абзацами шестым - восьмым, двенадцатым и тринадцатым части пятнадцатой статьи 4.2 настоящего Федерального закона и абзацами третьим и пятым части пятой статьи 11.1 настоящего Федерального закона. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 08.06.2020 № 166-ФЗ, от 24.03.2021 № 48-ФЗ)\nПорядок представления сведений и документов, подтверждающих соответствие должностного лица туроператора требованиям, установленным частью третьей настоящей статьи, в уполномоченный федеральный орган исполнительной власти для внесения в реестр туроператоров утверждается Правительством Российской Федерации. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nФинансовое обеспечение ответственности туроператора не требуется для:\nорганизации, осуществляющей экскурсионное обслуживание на территории Российской Федерации в течение не более 24 часов подряд;\nгосударственного и муниципального унитарных предприятий, а также государственного и муниципального учреждений, осуществляющих деятельность по организации путешествий в пределах территории Российской Федерации в целях решения социальных задач;\nтуроператора, осуществляющего деятельность только в сфере выездного туризма и имеющего сформированный в соответствии со статьей 11.6 настоящего Федерального закона фонд персональной ответственности туроператора в размере не менее семи процентов от общей цены туристского продукта в сфере выездного туризма за предыдущий год, рассчитанной без учета общей цены туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона. Для туроператора, осуществляющего деятельность одновременно в сфере выездного туризма и в сфере въездного туризма и (или) в сфере внутреннего туризма и сформировавшего фонд персональной ответственности туроператора в указанном максимальном размере, не требуется финансовое обеспечение ответственности туроператора, предусмотренное абзацами третьим и четвертым части первой статьи 17.2 настоящего Федерального закона (далее - финансовое обеспечение ответственности туроператора в сфере выездного туризма). (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nНа территории Российской Федерации реализацию туристского продукта, сформированного иностранным юридическим лицом, индивидуальным предпринимателем либо организацией, не являющейся юридическим лицом в соответствии с законодательством иностранного государства (далее - иностранный туроператор), вправе осуществлять юридические лица, имеющие финансовое обеспечение ответственности туроператора, полученное в порядке и на условиях, которые предусмотрены настоящим Федеральным законом.\nПраво на осуществление туроператорской деятельности юридическим лицом подтверждается записью в едином федеральном реестре туроператоров. Требования, предъявляемые в соответствии с настоящим Федеральным законом к осуществлению туроператорской деятельности, также применяются в отношении юридических лиц, реализующих на территории Российской Федерации туристский продукт, сформированный иностранным туроператором. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nЗапрещается осуществление туроператорской деятельности юридическим лицом, сведения о котором отсутствуют в едином федеральном реестре туроператоров, а также осуществление туроператором туроператорской деятельности в определенной сфере туризма (въездной туризм, выездной туризм, внутренний туризм), сведения о которой в отношении такого туроператора отсутствуют в едином федеральном реестре туроператоров.\nВ случае невозможности исполнения туроператором всех обязательств по заключенным договорам о реализации туристского продукта туроператор обязан прекратить заключение новых договоров о реализации туристского продукта, в том числе обеспечить прекращение их заключения турагентами, реализующими туристский продукт, сформированный таким туроператором, направить информацию о прекращении туроператорской деятельности по причине невозможности исполнения обязательств по договорам о реализации туристского продукта в уполномоченный федеральный орган исполнительной власти, в объединение туроператоров в сфере выездного туризма (в случае осуществления туроператорской деятельности в сфере выездного туризма), в организацию, предоставившую туроператору финансовое обеспечение ответственности туроператора, а также разместить эту информацию на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\".\nПрекращение туроператором туроператорской деятельности по причине невозможности исполнения всех обязательств по договорам о реализации туристского продукта не освобождает туроператора от обязанности обеспечить туристам оказание входящих в туристский продукт услуг по заключенным договорам о реализации туристского продукта.\n(Дополнение статьей - Федеральный закон от 05.02.2007 № 12-ФЗ) (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["4.2","Единый федеральный реестр туроператоров","Глава II. Государственное регулирование туристской деятельности","2025-07-31","Статья 4.2. Единый федеральный реестр туроператоров\nВ единый федеральный реестр туроператоров вносятся следующие сведения о туроператоре:\nполное и сокращенное наименования туроператора на русском языке; если в учредительном документе туроператора его наименование указано на одном из языков народов Российской Федерации и (или) на иностранном языке, также наименование туроператора на этом языке;\nадрес, место нахождения туроператора;\nсведения об учредителях туроператора;\nосновной государственный регистрационный номер туроператора;\nидентификационный номер налогоплательщика;\nфамилия, имя и отчество (в случае, если имеется) руководителя туроператора;\nразмер финансового обеспечения ответственности туроператора, номер, дата и срок действия каждого договора страхования гражданской ответственности за неисполнение туроператором обязательств по договору о реализации туристского продукта (далее - договор страхования ответственности туроператора) и (или) номер, дата и срок действия каждой банковской гарантии исполнения обязательств по договору о реализации туристского продукта (далее - банковская гарантия), наименования, адреса, места нахождения организаций, предоставивших финансовое обеспечение ответственности туроператора (за исключением туроператоров, указанных в части пятой статьи 4.1 настоящего Федерального закона);\nсфера туризма, в которой осуществляется туроператорская деятельность (въездной туризм, выездной туризм, внутренний туризм);\nадреса, места нахождения обособленных подразделений туроператора, осуществляющих туроператорскую деятельность; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nадрес официального сайта туроператора в информационно-телекоммуникационной сети \"Интернет\".\nВ отношении туроператоров, осуществляющих деятельность в сфере выездного туризма, в реестр туроператоров также вносятся сведения: (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nоб общей цене туристского продукта в сфере выездного туризма за предыдущий год, об общей цене туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год; (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nо членстве туроператора, осуществляющего деятельность в сфере выездного туризма, в объединении туроператоров в сфере выездного туризма;\nо размере уплаченного взноса в резервный фонд;\nо количестве туристов в сфере выездного туризма за предыдущий год, определяемом как итоговое количество туристов, которым в течение предыдущего календарного года туроператором оказаны услуги в сфере выездного туризма по каждому договору о реализации туристского продукта, заключенному туроператором или турагентом с туристом и (или) иным заказчиком туристского продукта; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nо количестве туристов, которым туроператором оказаны услуги по договорам о реализации туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год; (Дополнение абзацем - Федеральный закон от 23.07.2025 № 238-ФЗ)\nо фактическом размере фонда персональной ответственности туроператора, под которым понимается объем денежных средств, накопленных в фонде персональной ответственности туроператора по состоянию на 31 декабря отчетного года;\nо размере ежегодного взноса, перечисленного туроператором в фонд персональной ответственности туроператора в отчетном году.\nРеестр туроператоров является федеральной информационной системой, содержащей зафиксированные на материальном носителе сведения в соответствии с законодательством Российской Федерации об информации, информационных технологиях и о защите информации. Ведение реестра туроператоров осуществляется уполномоченным федеральным органом исполнительной власти на электронном носителе в соответствии с едиными организационными, методологическими и программно-техническими принципами, обеспечивающими совместимость и взаимодействие этого реестра туроператоров с иными федеральными информационными системами и информационно-телекоммуникационными сетями. (В редакции федеральных законов от 24.03.2021 № 48-ФЗ, от 31.07.2025 № 304-ФЗ)\nСведения о туроператоре вносятся в реестр туроператоров на основании представляемого в уполномоченный федеральный орган исполнительной власти и содержащего сведения, подлежащие внесению в реестр туроператоров, заявления юридического лица, намеревающегося осуществлять туроператорскую деятельность. Указанное заявление составляется в электронной форме и удостоверяется подписью руководителя юридического лица, намеревающегося осуществлять туроператорскую деятельность, или иного лица, уполномоченного представлять такое юридическое лицо. При этом руководитель юридического лица, намеревающегося осуществлять туроператорскую деятельность, или иное лицо, уполномоченное представлять такое юридическое лицо, указывает данные своего паспорта, а при его отсутствии иного документа, удостоверяющего личность в соответствии с законодательством Российской Федерации. Сведения о туроператоре, указанные в заявлении юридического лица, намеревающегося осуществлять туроператорскую деятельность, и подлежащие внесению в реестр туроператоров в соответствии с абзацами вторым - седьмым части первой настоящей статьи, проверяются уполномоченным федеральным органом исполнительной власти посредством направления соответствующего межведомственного запроса в федеральный орган исполнительной власти, осуществляющий государственную регистрацию юридических лиц, физических лиц в качестве индивидуальных предпринимателей и крестьянских (фермерских) хозяйств, и федеральный орган исполнительной власти, осуществляющий функции по контролю и надзору за соблюдением законодательства о налогах и сборах. Для подтверждения сведений, указанных в заявлении юридического лица, намеревающегося осуществлять туроператорскую деятельность, и подлежащих внесению в реестр туроператоров в соответствии с абзацем восьмым части первой настоящей статьи, предоставляются договор или договоры страхования ответственности туроператора и (или) банковская гарантия либо нотариально засвидетельствованная копия каждого из указанных документов с приложением копий документов, подтверждающих факт оплаты стоимости финансового обеспечения ответственности туроператора. Сведения о туроператоре, вносимые в реестр туроператоров в соответствии с абзацами вторым, пятым и шестым части второй настоящей статьи, проверяются уполномоченным федеральным органом исполнительной власти, в том числе посредством направления страховщикам запросов о количестве заключенных клиентами туроператора договоров добровольного страхования, указанных в статье 17 настоящего Федерального закона. Заявление юридического лица, намеревающегося осуществлять туроператорскую деятельность, и иные указанные в настоящей статье документы представляются в форме электронных документов с использованием федеральной государственной информационной системы \"Единый портал государственных и муниципальных услуг (функций)\" (далее - единый портал государственных и муниципальных услуг). Порядок представления электронных документов устанавливается уполномоченным федеральным органом исполнительной власти. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 24.03.2021 № 48-ФЗ, от 23.07.2025 № 238-ФЗ, от 31.07.2025 № 304-ФЗ)\nУполномоченный федеральный орган исполнительной власти не позднее восьми рабочих дней со дня поступления заявления юридического лица, намеревающегося осуществлять туроператорскую деятельность, с приложением всех необходимых документов принимает решение о внесении сведений о туроператоре в реестр туроператоров либо об отказе во внесении в реестр туроператоров этих сведений. Указанные решения оформляются соответствующим актом уполномоченного федерального органа исполнительной власти. За рассмотрение заявления юридического лица, намеревающегося осуществлять туроператорскую деятельность, о внесении сведений о нем в реестр туроператоров и за внесение этих сведений в реестр туроператоров плата не взимается. (В редакции федеральных законов от 24.03.2021 № 48-ФЗ, от 31.07.2025 № 304-ФЗ)\nУведомление о решении, принятом уполномоченным федеральным органом исполнительной власти и содержащем основания для отказа во внесении сведений о туроператоре в реестр туроператоров, в день принятия такого решения направляется юридическому лицу, намеревающемуся осуществлять туроператорскую деятельность, с использованием единого портала государственных и муниципальных услуг. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nОснованием для отказа во внесении сведений о туроператоре в реестр туроператоров является: (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nпредставление недостоверных и (или) неполных сведений о туроператоре; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nнесоответствие имеющегося у туроператора финансового обеспечения ответственности туроператора требованиям, предусмотренным настоящим Федеральным законом;\nотсутствие фонда персональной ответственности туроператора или несоответствие размера ежегодного взноса туроператора в фонд персональной ответственности туроператора требованиям, предусмотренным настоящим Федеральным законом (для туроператоров, осуществляющих деятельность в сфере выездного туризма);\nнепредставление сведений о членстве туроператора, осуществляющего деятельность в сфере выездного туризма, в объединении туроператоров в сфере выездного туризма (для туроператоров, осуществляющих деятельность в сфере выездного туризма);\nнесоответствие должностного лица туроператора требованиям, определенным частью третьей статьи 4.1 настоящего Федерального закона;\nисключение сведений о туроператоре из реестра туроператоров по основаниям, предусмотренным абзацами пятым и шестнадцатым части пятнадцатой настоящей статьи. (Дополнение абзацем - Федеральный закон от 04.06.2018 № 149-ФЗ) (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nУполномоченный федеральный орган исполнительной власти размещает на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" содержащиеся в реестре туроператоров следующие сведения о туроператоре: (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nполное и сокращенное наименования туроператора;\nадрес, место нахождения туроператора;\nидентификационный номер налогоплательщика;\nразмер финансового обеспечения ответственности туроператора, номер, дата и срок действия каждого договора страхования ответственности туроператора и (или) номер, дата и срок действия каждой банковской гарантии, наименование, адрес, место нахождения каждой организации, предоставившей финансовое обеспечение ответственности туроператора (за исключением туроператоров, указанных в части пятой статьи 4.1 настоящего Федерального закона);\nсфера туризма, в которой осуществляется туроператорская деятельность (въездной туризм, выездной туризм, внутренний туризм);\nадреса, места нахождения обособленных подразделений туроператора, осуществляющих туроператорскую деятельность; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nадрес официального сайта в информационно-телекоммуникационной сети \"Интернет\".\nВ отношении туроператора, осуществляющего деятельность в сфере выездного туризма, уполномоченный федеральный орган исполнительной власти также размещает на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" содержащиеся в реестре туроператоров сведения: (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nоб общей цене туристского продукта в сфере выездного туризма за предыдущий год; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nоб общей цене туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год; (Дополнение абзацем - Федеральный закон от 23.07.2025 № 238-ФЗ)\nо членстве туроператора, осуществляющего деятельность в сфере выездного туризма, в объединении туроператоров в сфере выездного туризма;\nо количестве туристов в сфере выездного туризма за предыдущий год;\nо количестве туристов, которым туроператором оказаны услуги по договору о реализации туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год; (Дополнение абзацем - Федеральный закон от 23.07.2025 № 238-ФЗ)\nо размере уплаченного взноса в резервный фонд;\nо фактическом размере фонда персональной ответственности туроператора;\nо размере ежегодного взноса, перечисленного туроператором в фонд персональной ответственности туроператора в отчетном году.\nУполномоченный федеральный орган исполнительной власти также размещает на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" сведения об объединении туроператоров в сфере выездного туризма (адрес, место нахождения данного объединения, адрес официального сайта в информационно-телекоммуникационной сети \"Интернет\", способы связи с данным объединением (номера телефонов, факсов, адрес электронной почты) и другие сведения.\nПри изменении сведений о туроператоре, внесенных в реестр туроператоров, туроператор не позднее десяти дней со дня изменения сведений обязан уведомить об этом уполномоченный федеральный орган исполнительной власти. Подтверждение достоверности таких изменений осуществляется в порядке, установленном частью четвертой настоящей статьи. Уполномоченный федеральный орган исполнительной власти не позднее трех рабочих дней со дня поступления уведомления туроператора об изменении сведений об общей цене туристского продукта в сфере выездного туризма за предыдущий год, об общей цене туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год, о количестве туристов в сфере выездного туризма за предыдущий год, о количестве туристов, которым туроператором оказаны услуги по договору о реализации туристского продукта, предусматривающему выезд туристов в сопредельные государства с благоприятными условиями для пребывания российских туристов (далее - сопредельные государства), которые включены в перечень, предусмотренный частью двенадцатой статьи 17.2-1 настоящего Федерального закона, за предыдущий год, о членстве туроператора в объединении туроператоров в сфере выездного туризма или об изменении сферы туризма, в которой туроператор осуществляет деятельность, с приложением всех необходимых документов вносит в реестр туроператоров такие изменения и размещает их на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" либо принимает решение об отказе во внесении в реестр туроператоров таких изменений по основанию, указанному в абзаце втором части седьмой настоящей статьи. (В редакции федеральных законов от 23.07.2025 № 238-ФЗ, от 31.07.2025 № 304-ФЗ)\nПри поступлении уведомления туроператора об изменении иных сведений о туроператоре, внесенных в реестр туроператоров, с приложением всех необходимых документов уполномоченный федеральный орган исполнительной власти не позднее трех рабочих дней вносит в реестр туроператоров такие изменения и размещает их на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" либо принимает решение об отказе во внесении в реестр туроператоров таких изменений по основаниям, указанным в абзацах втором - четвертом и шестом части седьмой настоящей статьи. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 24.03.2021 № 48-ФЗ)\nСведения о туроператоре, содержащиеся в реестре туроператоров, но не размещенные на официальном сайте уполномоченного федерального органа исполнительной власти в информационно-телекоммуникационной сети \"Интернет\", представляются по письменным запросам государственных органов и органов местного самоуправления. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 24.03.2021 № 48-ФЗ)\nУполномоченный федеральный орган исполнительной власти в день внесения сведений о туроператоре в реестр туроператоров направляет туроператору выписку из реестра туроператоров в форме электронного документа посредством единого портала государственных и муниципальных услуг. Форма выписки о внесении сведений о туроператоре в реестр туроператоров устанавливается уполномоченным федеральным органом исполнительной власти. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nУполномоченный федеральный орган исполнительной власти исключает сведения о туроператоре из реестра туроператоров в случае: (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nликвидации туроператора - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно о внесении в единый государственный реестр юридических лиц записи о нахождении туроператора в процессе ликвидации, либо со дня, следующего за днем опубликования решения о предстоящем исключении туроператора из единого государственного реестра юридических лиц;\nпрекращения деятельности туроператора в результате его реорганизации (за исключением реорганизации в форме преобразования) - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно о завершении реорганизации туроператора;\nнепредставления туроператором сведений о наличии у него финансового обеспечения ответственности туроператора на новый срок (за исключением туроператоров, указанных в части пятой статьи 4.1 настоящего Федерального закона) - со дня, следующего за днем истечения установленного статьей 11.7 или 17.3 настоящего Федерального закона срока представления сведений о наличии финансового обеспечения ответственности туроператора на новый срок; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nполучения от туроператора, объединения туроператоров в сфере выездного туризма или организации, предоставившей туроператору финансовое обеспечение ответственности туроператора, информации о прекращении туроператорской деятельности по причине невозможности исполнения туроператором всех обязательств по договорам о реализации туристского продукта - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно от туроператора, объединения туроператоров в сфере выездного туризма или организации, предоставившей туроператору финансовое обеспечение ответственности туроператора, о прекращении туроператорской деятельности;\nнарушения туроператором требований к размеру финансового обеспечения ответственности туроператора (за исключением туроператоров, указанных в части пятой статьи 4.1 настоящего Федерального закона) - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно о таком нарушении;\nвыявления недостоверных сведений о соответствии должностных лиц туроператора требованиям, определенным частью третьей статьи 4.1 настоящего Федерального закона, - со дня, следующего за днем, когда уполномоченным федеральным органом исполнительной власти были выявлены такие недостоверные сведения;\nнарушения существенных условий договора перевозки, включая договор фрахтования, заключенного между туроператором и перевозчиком, - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно о таком нарушении;\nнепредставления туроператором в случае отзыва у организации, ранее предоставившей туроператору финансовое обеспечение ответственности туроператора, лицензии на осуществление добровольного имущественного страхования или лицензии на осуществление банковских операций либо признания такой организации несостоятельной (банкротом) в соответствии с законодательством Российской Федерации, а также в случае досрочного расторжения договора страхования ответственности туроператора либо отзыва банковской гарантии документа, подтверждающего наличие у него финансового обеспечения ответственности туроператора (за исключением туроператоров, указанных в части пятой статьи 4.1 настоящего Федерального закона), - не позднее десяти календарных дней со дня, следующего за днем, когда истек срок представления туроператором такого документа; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nпредставления туроператором заявления о прекращении туроператорской деятельности во всех сферах туризма либо в определенной сфере туризма - со дня, следующего за днем представления соответствующего заявления;\nисключения туроператора, осуществляющего деятельность в сфере выездного туризма, из членов объединения туроператоров в сфере выездного туризма - со дня, следующего за днем представления объединением туроператоров в сфере выездного туризма в соответствии со статьей 11.1 настоящего Федерального закона соответствующей информации;\nнепредставления туроператором, осуществляющим деятельность в сфере выездного туризма, годовой бухгалтерской (финансовой) отчетности - со дня, следующего за днем истечения установленного уполномоченным федеральным органом исполнительной власти срока представления указанной отчетности;\nнепредставления туроператором, осуществляющим деятельность в сфере выездного туризма, отчетности, указанной в статье 17.7 настоящего Федерального закона (за исключением годовой бухгалтерской (финансовой) отчетности), - со дня, следующего за днем истечения установленного уполномоченным федеральным органом исполнительной власти срока представления указанной отчетности;\nнепредставления туроператором, осуществляющим деятельность в сфере выездного туризма, сведений о количестве туристов в сфере выездного туризма за предыдущий год, о количестве туристов, которым туроператором оказаны услуги по договору о реализации туристского продукта, предусматривающему выезд туристов в сопредельные государства, которые включены в перечень, предусмотренный частью двенадцатой статьи 17.2-1 настоящего Федерального закона, за предыдущий год, об общей цене туристского продукта в сфере выездного туризма за предыдущий год, об общей цене туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год либо сведений о размере уплаченного взноса в резервный фонд и (или) о фактическом размере фонда персональной ответственности туроператора - со дня, следующего за днем истечения срока представления соответствующих сведений; (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nвыявления факта представления туроператором, осуществляющим деятельность в сфере выездного туризма, заведомо недостоверных сведений о туроператоре (внесенных в них изменений), содержащихся в реестре туроператоров и касающихся количества туристов в сфере выездного туризма за предыдущий год, количества туристов, которым туроператором оказаны услуги по договору о реализации туристского продукта, предусматривающему выезд туристов в сопредельные государства, которые включены в перечень, предусмотренный частью двенадцатой статьи 17.2-1 настоящего Федерального закона, за предыдущий год, общей цены туристского продукта в сфере выездного туризма за предыдущий год, общей цены туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год, размера уплаченного взноса в резервный фонд, фактического размера фонда персональной ответственности туроператора, - со дня, следующего за днем выявления уполномоченным федеральным органом исполнительной власти таких недостоверных сведений; (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nпрекращения туроператорской деятельности по причине невозможности исполнения туроператором всех обязательств по договорам о реализации туристского продукта без направления туроператором соответствующей информации в уполномоченный федеральный орган исполнительной власти, объединение туроператоров в сфере выездного туризма (в случае осуществления туроператорской деятельности в сфере выездного туризма), в организацию, предоставившую туроператору финансовое обеспечение ответственности туроператора, а также без размещения туроператором этой информации на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\" - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно об этом; (Дополнение абзацем - Федеральный закон от 04.06.2018 № 149-ФЗ)\nнарушения не менее трех раз в течение трех последовательных месяцев туроператором запрета на реализацию туристского продукта без передачи сведений, содержащихся в договоре о реализации туристского продукта, в единую информационную систему электронных путевок на день, следующий за днем истечения срока передачи им таких сведений в единую информационную систему электронных путевок, определяемым настоящим Федеральным законом, - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно от федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного контроля (надзора) в области защиты прав потребителей, о данном нарушении; (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)\nнарушения не менее трех раз в течение трех последовательных месяцев туроператором порядка и (или) срока передачи сведений, содержащихся в договоре о реализации туристского продукта, в единую информационную систему электронных путевок на день, следующий за днем истечения срока передачи им таких сведений в единую информационную систему электронных путевок, определяемым настоящим Федеральным законом, - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно от федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного контроля (надзора) в области защиты прав потребителей, о данном нарушении; (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)\nпередачи не менее трех раз в течение трех последовательных месяцев туроператором недостоверных или не в полном объеме сведений, содержащихся в договоре о реализации туристского продукта, в единую информационную систему электронных путевок на день, следующий за днем истечения срока передачи им таких сведений в единую информационную систему электронных путевок, определяемым настоящим Федеральным законом, - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно от федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного контроля (надзора) в области защиты прав потребителей, о данном нарушении. (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)\nВ случаях, указанных в абзацах втором - девятом, шестнадцатом - девятнадцатом части пятнадцатой настоящей статьи, из реестра туроператоров исключаются все сведения о туроператоре. В случаях, указанных в абзацах одиннадцатом - пятнадцатом части пятнадцатой настоящей статьи, в отношении туроператора, осуществляющего деятельность только в сфере выездного туризма, из реестра туроператоров исключаются все сведения о туроператоре, а в отношении туроператора, осуществляющего туроператорскую деятельность в нескольких сферах туризма (выездной и внутренний туризм, выездной и въездной туризм, выездной, въездной и внутренний туризм), из реестра туроператоров исключаются сведения о сфере выездного туризма и остальные сведения о туроператоре, связанные с осуществлением им деятельности в сфере выездного туризма. В случае представления туроператором заявления о прекращении туроператорской деятельности во всех сферах туризма из реестра туроператоров исключаются все сведения о туроператоре, а в случае представления туроператором заявления о прекращении туроператорской деятельности в определенной сфере туризма из реестра туроператоров в отношении такого туроператора исключаются сведения об указанной в заявлении сфере туризма и остальные сведения о туроператоре, связанные с осуществлением им деятельности в указанной в заявлении сфере туризма. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 24.03.2021 № 48-ФЗ, от 28.05.2022 № 148-ФЗ)\nРешение об исключении соответствующих сведений о туроператоре из реестра туроператоров оформляется актом уполномоченного федерального органа исполнительной власти. Указанное решение должно быть мотивировано. Уведомление о принятии уполномоченным федеральным органом исполнительной власти решения, содержащего основания для исключения соответствующих сведений о туроператоре из реестра туроператоров, в день принятия такого решения направляется туроператору в форме электронного документа с использованием единого портала государственных и муниципальных услуг. Решение об исключении соответствующих сведений о туроператоре из реестра туроператоров вступает в силу со дня его принятия. Уполномоченный федеральный орган исполнительной власти не позднее трех дней со дня принятия указанного решения размещает его на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\". (В редакции федеральных законов от 24.03.2021 № 48-ФЗ, от 31.07.2025 № 304-ФЗ)\nРешение об исключении соответствующих сведений о туроператоре из реестра туроператоров может быть обжаловано в суд. (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["4.3","Реестр турагентов","Глава II. Государственное регулирование туристской деятельности","2025-07-31","Статья 4.3. Реестр турагентов\nРеестр турагентов является федеральным информационным ресурсом, содержащим сведения о турагентах и субагентах.\nВедение реестра турагентов осуществляется уполномоченным федеральным органом исполнительной власти в электронной форме в соответствии с едиными организационными, методологическими и программно-техническими принципами, обеспечивающими совместимость и взаимодействие реестра турагентов с иными федеральными информационными системами и информационно-телекоммуникационными сетями, а также информационными системами туроператоров и турагентов.\nПорядок ведения реестра турагентов, в том числе порядок предоставления выписки из реестра турагентов и форма такой выписки, и порядок внесения в реестр турагентов сведений о турагентах, субагентах устанавливаются уполномоченным федеральным органом исполнительной власти. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nРеестр турагентов содержит следующие сведения:\nполное и (в случае, если имеется) сокращенное наименования, фамилия, имя, отчество (в случае, если имеется) руководителя, адрес места нахождения, основной государственный регистрационный номер юридического лица - в отношении турагента, субагента - юридического лица;\nфамилия, имя, отчество (в случае, если имеется), адрес места жительства индивидуального предпринимателя, основной государственный регистрационный номер индивидуального предпринимателя - в отношении турагента, субагента - индивидуального предпринимателя;\nсведения о наличии договора на продвижение и реализацию туристского продукта между туроператором и турагентом, по которому туроператор поручает продвижение и реализацию туристского продукта, в том числе указание сферы туризма, в которой поручаются продвижение и реализация туристского продукта (въездной туризм, выездной туризм, внутренний туризм), даты заключения и срока действия такого договора, а также указание на возможность (невозможность) передачи турагентом исполнения поручения туроператора на продвижение и реализацию туристского продукта субагенту;\nсведения о наличии договора на продвижение и реализацию туристского продукта между турагентом и субагентом, по которому турагент передает исполнение поручения на продвижение и реализацию туристского продукта, в том числе указание сферы туризма, в которой поручаются продвижение и реализация туристского продукта (въездной туризм, выездной туризм, внутренний туризм), даты заключения и срока действия такого договора;\nреестровый номер турагента в реестре турагентов;\nдата размещения туроператором в реестре турагентов сведений, указанных в абзаце четвертом настоящей части;\nдата размещения турагентом в реестре турагентов сведений, указанных в абзаце пятом настоящей части, в случае наличия договора субагентирования или субкомиссии либо иного договора, предусматривающего передачу исполнения поручения на продвижение и реализацию туристского продукта;\nдата внесения уполномоченным федеральным органом исполнительной власти изменений в реестр турагентов;\nдата принятия решения об исключении из реестра турагентов сведений о турагенте и номер указанного решения.\nСведения о турагенте, субагенте, указанные в абзацах втором и третьем части четвертой настоящей статьи, формируются в реестре турагентов автоматически на основании сведений из единого государственного реестра юридических лиц и единого государственного реестра индивидуальных предпринимателей после указания туроператором (турагентом) основного государственного регистрационного номера юридического лица или основного государственного регистрационного номера индивидуального предпринимателя при формировании сведений о турагенте, субагенте для размещения в реестре турагентов. Соответствие данных сведений сведениям, содержащимся в едином государственном реестре юридических лиц и едином государственном реестре индивидуальных предпринимателей, обеспечивается посредством использования и дальнейшего обновления предоставляемых единой системой межведомственного электронного взаимодействия в реестр турагентов сведений, размещенных в государственных информационных системах и иных информационных системах, не позднее чем через три рабочих дня со дня такого предоставления.\nСведения о наличии договора на продвижение и реализацию туристского продукта между туроператором и турагентом, по которому туроператор поручает продвижение и реализацию туристского продукта, в том числе указание сферы туризма, в которой поручаются продвижение и реализация туристского продукта (въездной туризм, выездной туризм, внутренний туризм), даты заключения и срока действия такого договора, а также указание на возможность (невозможность) заключения турагентом такого договора с субагентом, формируются туроператором в реестре турагентов самостоятельно не позднее чем через три рабочих дня со дня заключения такого договора.\nВнесение сведений о турагенте в реестр турагентов осуществляется туроператором в электронной форме с использованием личного кабинета туроператора на официальном сайте уполномоченного федерального органа исполнительной власти в информационно-телекоммуникационной сети \"Интернет\".\nСведения о наличии договора на продвижение и реализацию туристского продукта между турагентом и субагентом, по которому турагент передает поручение на продвижение и реализацию туристского продукта, в том числе указание сферы туризма, в которой поручаются продвижение и реализация туристского продукта (въездной туризм, выездной туризм, внутренний туризм), даты заключения и срока действия такого договора, формируются турагентом в реестре турагентов самостоятельно не позднее чем через три рабочих дня со дня заключения такого договора.\nВнесение сведений о субагенте в реестр турагентов осуществляется турагентом в электронной форме с использованием личного кабинета турагента на официальном сайте уполномоченного федерального органа исполнительной власти в информационно-телекоммуникационной сети \"Интернет\". При этом туроператор должен подтвердить в реестре турагентов право субагента на продвижение и реализацию туристского продукта, сформированного туроператором.\nПри изменении сведений, указанных в абзаце четвертом части четвертой настоящей статьи (в том числе в случае прекращения (расторжения) договора с турагентом, прекращения полномочий турагента по передаче исполнения поручения субагенту), туроператор не позднее трех рабочих дней со дня изменения сведений обязан внести соответствующую запись в реестр турагентов с использованием личного кабинета туроператора на официальном сайте уполномоченного федерального органа исполнительной власти в информационно-телекоммуникационной сети \"Интернет\".\nПри изменении сведений, указанных в абзаце пятом части четвертой настоящей статьи (в том числе в случае прекращения (расторжения) договора с субагентом), турагент не позднее трех рабочих дней со дня изменения сведений обязан внести соответствующую запись в реестр турагентов с использованием личного кабинета турагента на официальном сайте уполномоченного федерального органа исполнительной власти в информационно-телекоммуникационной сети \"Интернет\".\nНевнесение туроператором сведений о турагенте, осуществляющем продвижение и реализацию туристского продукта, сформированного туроператором, в реестр турагентов, внесение сведений о турагенте в реестр турагентов с нарушением порядка, предусмотренного законодательством Российской Федерации, либо внесение в реестр турагентов недостоверных сведений влечет за собой административную ответственность в соответствии с законодательством Российской Федерации.\nНевнесение турагентом сведений о субагенте, осуществляющем продвижение и реализацию туристского продукта, сформированного туроператором, в реестр турагентов, внесение сведений о субагенте в реестр турагентов с нарушением порядка, предусмотренного законодательством Российской Федерации, либо внесение в реестр турагентов недостоверных сведений влечет за собой административную ответственность в соответствии с законодательством Российской Федерации.\nОснованием для отказа во внесении в реестр турагентов сведений о турагенте является отсутствие таких сведений или несоответствие сведений в отношении турагента сведениям, содержащимся в едином государственном реестре юридических лиц или в едином государственном реестре индивидуальных предпринимателей, либо наличие в указанных реестрах записи о прекращении деятельности турагентом.\nУполномоченный федеральный орган исполнительной власти исключает сведения о турагенте из реестра турагентов в случае:\nисключения сведений об осуществляющем турагентскую деятельность юридическом лице из единого государственного реестра юридических лиц или сведений об осуществляющем турагентскую деятельность индивидуальном предпринимателе из единого государственного реестра индивидуальных предпринимателей в соответствии с законодательством Российской Федерации о государственной регистрации юридических лиц и индивидуальных предпринимателей;\nпрекращения действия всех договоров на продвижение и реализацию туристского продукта, заключенных между туроператором и турагентом, в связи с расторжением или окончанием сроков действия таких договоров, а также по иным основаниям, предусмотренным законодательством Российской Федерации;\nнарушения турагентом не менее трех раз в течение трех последовательных месяцев порядка и (или) срока направления туроператору уведомления о заключении договора о реализации туристского продукта на день, следующий за днем истечения срока, определяемым правилами функционирования единой электронной системы электронных путевок, установленными Правительством Российской Федерации, - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно от федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного контроля (надзора) в области защиты прав потребителей, о данном нарушении; (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)\nнарушения турагентом не менее трех раз в течение трех последовательных месяцев запрета на реализацию туристского продукта без направления туроператору уведомления о заключении договора о реализации туристского продукта на день, следующий за днем истечения срока, определяемым правилами функционирования единой электронной системы электронных путевок, установленными Правительством Российской Федерации, направления им уведомления туроператору о заключении договора о реализации туристского продукта - со дня, следующего за днем, когда уполномоченному федеральному органу исполнительной власти стало известно от федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного контроля (надзора) в области защиты прав потребителей, о данном нарушении. (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)\nРешение об исключении сведений о турагенте из реестра турагентов оформляется соответствующим актом уполномоченного федерального органа исполнительной власти. Уведомление о принятии уполномоченным федеральным органом исполнительной власти решения об исключении сведений о турагенте из реестра турагентов, содержащего основания для исключения сведений о турагенте из реестра турагентов, не позднее дня, следующего за днем принятия указанного решения, направляется турагенту в электронной форме с использованием личного кабинета. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nУполномоченный федеральный орган исполнительной власти не позднее чем через один рабочий день со дня принятия решения об исключении сведений о турагенте из реестра турагентов размещает указанное решение на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\".\nИсключение сведений о турагенте, субагенте из реестра турагентов либо прекращение полномочий турагента, субагента по продвижению и реализации туристского продукта не прекращает действие ранее заключенных договоров о реализации туристского продукта, заключенных такими турагентом, субагентом с туристами и (или) заказчиками туристского продукта до дня исключения данных сведений, и не освобождает туроператора от обязанности обеспечить оказание туристам услуг, входящих в туристский продукт.\nРешение об исключении сведений о турагенте, субагенте из реестра турагентов может быть обжаловано в судебном порядке.\nПрекращение полномочий турагента влечет за собой прекращение полномочий субагентов, с которыми были заключены договоры на продвижение и реализацию туристского продукта между турагентом и субагентом в целях передачи исполнения поручения туроператора.\n(Дополнение статьей - Федеральный закон от 24.03.2021 № 48-ФЗ)"],
["4.4","Условия оказания услуг экскурсовода (гида) и гида-переводчика. Аттестация экскурсовода (гида) и гида-переводчика","Глава II. Государственное регулирование туристской деятельности","2026-07-04","Статья 4.4. Условия оказания услуг экскурсовода (гида) и гида-переводчика. Аттестация экскурсовода (гида) и гида-переводчика\nЭкскурсовод (гид) и гид-переводчик вправе оказывать услуги только при условии прохождения ими аттестации в порядке, предусмотренном законодательством Российской Федерации о туристской деятельности, если иное не предусмотрено международными договорами Российской Федерации.\nПравила оказания услуг экскурсовода (гида) и гида-переводчика устанавливаются Правительством Российской Федерации.\nАттестация экскурсоводов (гидов) или гидов-переводчиков проводится аттестационной комиссией, создаваемой органом государственной власти субъекта Российской Федерации в сфере туризма.\nНе менее двух третей состава аттестационной комиссии должны составлять представители организаций, представляющих профессиональные сообщества туроператоров, турагентов, экскурсоводов (гидов) и (или) гидов-переводчиков, образовательных организаций, которые осуществляют подготовку экскурсоводов (гидов) и (или) гидов-переводчиков, организаций, осуществляющих туристскую деятельность, музеев и иных объектов показа, научных и некоммерческих организаций в сфере культуры, истории, краеведения, искусствоведения, централизованных религиозных организаций и (или) религиозных организаций, входящих в их структуру.\nКворум для проведения заседания аттестационной комиссии должен составлять не менее половины от общего числа ее членов.\nАттестационная комиссия осуществляет свою деятельность в соответствии с положением, утверждаемым органом государственной власти субъекта Российской Федерации в сфере туризма.\nРешение об аттестации экскурсовода (гида) или гида-переводчика принимается аттестационной комиссией большинством голосов от числа членов комиссии, присутствующих на ее заседании. При равенстве числа голосов членов комиссии голос председателя комиссии является решающим.\nЭкскурсовод (гид) или гид-переводчик может пройти аттестацию для оказания услуг на территории одного субъекта Российской Федерации или территориях нескольких субъектов Российской Федерации, на территории одного муниципального образования или территориях нескольких муниципальных образований в границах субъекта Российской Федерации (за исключением территорий муниципальных образований в границах городов федерального значения Москвы, Санкт-Петербурга и Севастополя), на национальных туристских маршрутах. (В редакции Федерального закона от 24.06.2025 № 184-ФЗ)\nДля прохождения аттестации экскурсовод (гид) или гид-переводчик обращается в орган государственной власти субъекта Российской Федерации в сфере туризма, в котором предполагает оказывать услуги, с заявлением об аттестации. В заявлении об аттестации экскурсовод (гид) или гид-переводчик указывает субъекты Российской Федерации либо муниципальные образования в границах субъекта Российской Федерации, на территориях которых предполагает оказывать услуги, национальные туристские маршруты. В случае, если экскурсовод (гид) или гид-переводчик предполагает оказывать услуги на территориях нескольких субъектов Российской Федерации, на национальных туристских маршрутах, экскурсовод (гид) или гид-переводчик обращается в орган государственной власти одного из таких субъектов Российской Федерации по своему выбору.\nДля проведения аттестации экскурсовода (гида) или гида-переводчика, предполагающих оказывать услуги на территориях нескольких субъектов Российской Федерации и (или) на национальных туристских маршрутах, аттестационная комиссия субъекта Российской Федерации, созданная органом государственной власти субъекта Российской Федерации, в который обратился экскурсовод (гид) или гид-переводчик с заявлением об аттестации, направляет в аттестационные комиссии субъектов Российской Федерации, указанных в заявлении об аттестации, приглашения принять участие в заседании, в том числе посредством видео-конференц-связи. Аттестационная комиссия субъекта Российской Федерации, получившая такое приглашение, обязана направить для участия в заседании одного или нескольких членов аттестационной комиссии субъекта Российской Федерации. Члены аттестационной комиссии, приглашенные из субъектов Российской Федерации, принимают участие в принятии решения об аттестации экскурсовода (гида) или гида-переводчика.\nВ случае, если экскурсовод (гид) или гид-переводчик аттестуется для оказания услуг на территориях нескольких субъектов Российской Федерации, аттестационная комиссия принимает решение об аттестации экскурсовода (гида) или гида-переводчика для оказания услуг отдельно на территории каждого из субъектов Российской Федерации.\nУполномоченный федеральный орган исполнительной власти в порядке, установленном Правительством Российской Федерации, определяет национальные туристские маршруты и размещает сведения о них на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\".\nПорядок аттестации экскурсоводов (гидов), гидов-переводчиков, порядок аттестации экскурсоводов (гидов), гидов-переводчиков, оказывающих услуги на территориях нескольких субъектов Российской Федерации или на национальных туристских маршрутах, специальные требования к экскурсоводам (гидам), гидам-переводчикам, перечень документов и сведений, необходимых для их аттестации, порядок взаимодействия аттестационных комиссий субъектов Российской Федерации при проведении аттестации экскурсоводов (гидов), гидов-переводчиков, оказывающих услуги на территориях нескольких субъектов Российской Федерации, на национальных туристских маршрутах, порядок принятия решений об отказе в аттестации и о прекращении действия аттестации экскурсовода (гида) или гида-переводчика, порядок обжалования указанных решений, порядок проведения планового подтверждения соответствия экскурсоводов (гидов), гидов-переводчиков требованиям, предусмотренным настоящим Федеральным законом, и специальным требованиям к экскурсоводам (гидам), гидам-переводчикам, порядок ведения единого федерального реестра экскурсоводов (гидов) и гидов-переводчиков, включая перечень содержащихся в этом реестре документов и сведений, порядок изменения сведений, содержащихся в едином федеральном реестре экскурсоводов (гидов) и гидов-переводчиков, и исключения сведений об экскурсоводах (гидах) и о гидах-переводчиках из единого федерального реестра экскурсоводов (гидов) и гидов-переводчиков, порядок и случаи выдачи дубликата нагрудной идентификационной карточки экскурсовода (гида) или гида-переводчика устанавливаются Правительством Российской Федерации.\nДля прохождения аттестации экскурсовод (гид) или гид-переводчик должен соответствовать следующим требованиям:\nиметь среднее профессиональное образование или высшее образование либо осваивать основные профессиональные образовательные программы при условии достижения восемнадцати лет и успешного прохождения промежуточной аттестации по дисциплине (модулю) по видам профессиональной деятельности по оказанию услуг экскурсовода (гида) или гида-переводчика в соответствии с федеральными государственными образовательными стандартами; (В редакции Федерального закона от 24.06.2025 № 184-ФЗ)\nиметь дополнительное профессиональное образование в области, соответствующей профилю работы экскурсовода (гида) или гида-переводчика, за исключением экскурсоводов (гидов), гидов-переводчиков, получивших среднее профессиональное образование или высшее образование по образовательным программам, включающим в себя дисциплину (модуль) по видам профессиональной деятельности по оказанию услуг экскурсовода (гида) или гида-переводчика, либо осваивающих основные профессиональные образовательные программы при условии достижения восемнадцати лет и успешного прохождения промежуточной аттестации по дисциплине (модулю) по видам профессиональной деятельности по оказанию услуг экскурсовода (гида) или гида-переводчика в соответствии с федеральными государственными образовательными стандартами, а также случаев, предусмотренных порядком аттестации экскурсоводов (гидов), гидов-переводчиков, установленным Правительством Российской Федерации; (В редакции Федерального закона от 24.06.2025 № 184-ФЗ)\nсоответствовать специальным требованиям к экскурсоводам (гидам) и гидам-переводчикам, установленным Правительством Российской Федерации;\nсвободно владеть иностранным языком, на котором предполагается оказывать услуги гида-переводчика по ознакомлению туристов (экскурсантов) с объектами показа, сопровождению туристов (экскурсантов) и информированию туристов (экскурсантов) по пути следования по туристскому маршруту.\nОснованиями для отказа в аттестации являются:\nнепредставление экскурсоводом (гидом), гидом-переводчиком документов и сведений, необходимых для аттестации;\nналичие недостоверных сведений в документах, представленных экскурсоводом (гидом), гидом-переводчиком для аттестации;\nнесоответствие экскурсовода (гида), гида-переводчика требованиям, предусмотренным настоящим Федеральным законом, и специальным требованиям к экскурсоводам (гидам) и гидам-переводчикам, установленным Правительством Российской Федерации;\nпоступление заявления об аттестации от экскурсовода (гида) или гида-переводчика до истечения шести месяцев со дня принятия решения о прекращении действия аттестации экскурсовода (гида) или гида-переводчика по основаниям, предусмотренным абзацами третьим - пятым части двадцать пятой настоящей статьи;\nпоступление заявления об аттестации от экскурсовода (гида) или гида-переводчика до истечения 30 дней со дня принятия аттестационной комиссией решения об отказе в аттестации.\nВ случае необходимости оказания услуг экскурсовода (гида) на иностранном языке или услуг гида-переводчика на иностранном языке, которым не владеет гид-переводчик, к оказанию услуг привлекается лицо, владеющее соответствующим иностранным языком, для оказания услуг по переводу. При этом указанное лицо не вправе оказывать туристам (экскурсантам) услуги гида-переводчика.\nВ случае отсутствия оснований, предусмотренных частью пятнадцатой настоящей статьи, орган государственной власти субъекта Российской Федерации в сфере туризма включает сведения об экскурсоводе (гиде) или о гиде-переводчике, прошедших аттестацию, в единый федеральный реестр экскурсоводов (гидов) и гидов-переводчиков, выдает нагрудную идентификационную карточку экскурсовода (гида) или гида-переводчика, форма которой утверждается органом государственной власти субъекта Российской Федерации. Оказание услуг экскурсовода (гида) и гида-переводчика допускается со дня включения сведений об экскурсоводе (гиде) и о гиде-переводчике в единый федеральный реестр экскурсоводов (гидов) и гидов-переводчиков. Наличие сведений об аттестации экскурсовода (гида) и гида-переводчика в едином федеральном реестре экскурсоводов (гидов) и гидов-переводчиков позволяет экскурсоводу (гиду) и гиду-переводчику оказывать услуги на территории (территориях) субъекта (субъектов) Российской Федерации, на территориях муниципальных образований в границах субъекта Российской Федерации, на национальных туристских маршрутах, указанных в едином федеральном реестре экскурсоводов (гидов) и гидов-переводчиков.\nЭкскурсовод (гид) и гид-переводчик обязаны проходить плановое подтверждение соответствия требованиям, предусмотренным настоящим Федеральным законом, и специальным требованиям к экскурсоводам (гидам), гидам-переводчикам один раз в пять лет.\nУполномоченный федеральный орган исполнительной власти ведет единый федеральный реестр экскурсоводов (гидов) и гидов-переводчиков в соответствии с порядком, установленным Правительством Российской Федерации.\nВнесение сведений об экскурсоводах (гидах) и о гидах-переводчиках в единый федеральный реестр экскурсоводов (гидов) и гидов-переводчиков осуществляется органом государственной власти субъекта Российской Федерации в сфере туризма.\nЭкскурсоводы (гиды) и гиды-переводчики при оказании услуг должны соблюдать правила оказания услуг экскурсовода (гида) и гида-переводчика, в том числе иметь нагрудную идентификационную карточку экскурсовода (гида) или гида-переводчика, доступную для всеобщего обозрения.\nНа нагрудной идентификационной карточке экскурсовода (гида) или гида-переводчика должны размещаться цветная фотография экскурсовода (гида) или гида-переводчика и следующие сведения:\nфамилия, имя и отчество (при наличии) экскурсовода (гида) или гида-переводчика (на русском и английском языках);\nдвухмерный штриховой код (QR-код), посредством которого обеспечивается переход на страницу единого федерального реестра экскурсоводов (гидов) и гидов-переводчиков, содержащую сведения об аттестованных экскурсоводе (гиде) или гиде-переводчике.\nПередача нагрудной идентификационной карточки экскурсовода (гида) или гида-переводчика иному лицу не допускается.\nОснованием для прекращения действия аттестации экскурсовода (гида) или гида-переводчика является решение органа государственной власти субъекта Российской Федерации в сфере туризма, внесшего сведения об экскурсоводе (гиде) или о гиде-переводчике в единый федеральный реестр экскурсоводов (гидов) и гидов-переводчиков, о прекращении действия аттестации.\nОснованием для принятия решения о прекращении действия аттестации экскурсовода (гида) или гида-переводчика является:\nвыявление после аттестации экскурсовода (гида) или гида-переводчика недостоверных сведений в документах, представленных для аттестации;\nвыявление после аттестации экскурсовода (гида) или гида-переводчика несоответствия экскурсовода (гида) или гида-переводчика требованиям к экскурсоводам (гидам) и гидам-переводчикам, предусмотренным настоящим Федеральным законом, и специальным требованиям к экскурсоводам (гидам), гидам-переводчикам;\nотказ экскурсовода (гида) или гида-переводчика от прохождения планового подтверждения соответствия экскурсовода (гида) или гида-переводчика требованиям, предусмотренным настоящим Федеральным законом, и специальным требованиям к экскурсоводам (гидам), гидам-переводчикам;\nнеоднократное (более двух раз в течение одного года) привлечение экскурсовода (гида) или гида-переводчика к административной ответственности за нарушение предусмотренных законодательством Российской Федерации о туристской деятельности условий оказания услуг экскурсовода (гида) или гида-переводчика;\nпризнание экскурсовода (гида) или гида-переводчика не соответствующими требованиям, предусмотренным настоящим Федеральным законом, и специальным требованиям к экскурсоводам (гидам), гидам-переводчикам по результатам планового подтверждения соответствия экскурсоводов (гидов), гидов-переводчиков требованиям, предусмотренным настоящим Федеральным законом, и специальным требованиям к экскурсоводам (гидам), гидам-переводчикам.\nРешение о прекращении действия аттестации экскурсовода (гида) или гида-переводчика принимается органом государственной власти субъекта Российской Федерации в сфере туризма, внесшим сведения об экскурсоводе (гиде) или о гиде-переводчике в единый федеральный реестр экскурсоводов (гидов) и гидов-переводчиков. Принятие указанного решения является основанием для исключения сведений об экскурсоводе (гиде) или о гиде-переводчике из единого федерального реестра экскурсоводов (гидов) и гидов-переводчиков. Лицо, в отношении которого на основании абзацев третьего - пятого части двадцать пятой настоящей статьи принято решение о прекращении действия аттестации экскурсовода (гида) или гида-переводчика, вправе обратиться с заявлением об аттестации не ранее чем через шесть месяцев со дня принятия указанного решения. До истечения этого срока данное лицо не может быть аттестовано в качестве экскурсовода (гида) или гида-переводчика ни в одном субъекте Российской Федерации.\nДействие настоящей статьи не распространяется на экскурсоводов (гидов) и гидов-переводчиков, осуществляющих деятельность на основании трудовых договоров или гражданско-правовых договоров с централизованными религиозными организациями, религиозными организациями, входящими в их структуру, и (или) созданными ими организациями, основной целью деятельности которых является осуществление паломнической деятельности, на экскурсоводов (гидов) и гидов-переводчиков, осуществляющих деятельность на объектах показа и состоящих в отношениях с владельцами указанных объектов на основании трудовых договоров или гражданско-правовых договоров, а также на лиц, осуществляющих ознакомление туристов (экскурсантов) с объектами показа в рамках осуществления образовательной деятельности.\n(Дополнение статьей - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции Федерального закона от 22.06.2024 № 143-ФЗ)\n(Статья 4.4 с 01.03.2027 в редакции Федерального закона от 04.07.2026 № 235-ФЗ)"],
["4.5","Условия оказания услуг инструктора-проводника. Аттестация инструктора-проводника","Глава II. Государственное регулирование туристской деятельности","2026-07-04","Статья 4.5. Условия оказания услуг инструктора-проводника. Аттестация инструктора-проводника\n(Наименование в редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nАттестация является обязательной для осуществления лицом деятельности в качестве инструктора-проводника, оказывающего услуги на туристских маршрутах, требующих специального сопровождения. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nПравила оказания услуг инструктора-проводника устанавливаются Правительством Российской Федерации. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nАттестация инструкторов-проводников проводится организациями, перечень которых утверждается Правительством Российской Федерации, по видам туристских маршрутов, требующих специального сопровождения, и категориям их сложности (далее - организация, уполномоченная на проведение аттестации инструкторов-проводников). (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nВиды туристских маршрутов, требующих специального сопровождения, категории их сложности, а также критерии отнесения туристского маршрута к соответствующей категории сложности, в том числе с учетом обеспечения безопасности туристов, устанавливаются Правительством Российской Федерации. Порядок отнесения туристских маршрутов (части туристских маршрутов) к туристским маршрутам, требующим специального сопровождения, включая порядок размещения сведений о туристских маршрутах, требующих специального сопровождения, устанавливается уполномоченным федеральным органом исполнительной власти. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nПорядок и критерии аттестации инструкторов-проводников, перечень документов и сведений, необходимых для аттестации, порядок принятия организацией, уполномоченной на проведение аттестации инструкторов-проводников, решений об аттестации и отказе в аттестации, о прекращении действия аттестации инструктора-проводника, порядок обжалования указанных решений, порядок проведения планового подтверждения соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, порядок и основания проведения внепланового подтверждения соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, порядок формирования и ведения единого федерального реестра инструкторов-проводников, включая перечень содержащихся в этом реестре сведений, порядок внесения изменений в сведения, содержащиеся в едином федеральном реестре инструкторов-проводников, и исключения сведений об инструкторах-проводниках из единого федерального реестра инструкторов-проводников, методика определения размера платы за проведение аттестации инструкторов-проводников, плановое подтверждение соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, а также предельные размеры платы за проведение аттестации инструкторов-проводников, планового подтверждения соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации устанавливаются Правительством Российской Федерации. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nДля прохождения аттестации в качестве инструктора-проводника соискатель должен соответствовать следующим требованиям:\nпройти профессиональное обучение, необходимое для работы в качестве инструктора-проводника и сопровождения туристов (экскурсантов), а также для обеспечения их безопасности при прохождении туристского маршрута, требующего специального сопровождения, соответствующих вида и категории сложности, за исключением случаев, предусмотренных порядком и критериями аттестации инструкторов-проводников, установленными Правительством Российской Федерации; (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nиметь документ, подтверждающий подготовку по оказанию первой помощи;\nиметь медицинское заключение об отсутствии медицинских противопоказаний к работе в качестве инструктора-проводника.\nПеречень заболеваний, препятствующих работе в качестве инструктора-проводника, порядок проведения медицинского осмотра для установления наличия или отсутствия медицинских противопоказаний к работе в качестве инструктора-проводника, включающего в себя химико-токсикологические исследования наличия в организме человека наркотических средств, психотропных веществ и их метаболитов, форма медицинского заключения об отсутствии медицинских противопоказаний к работе в качестве инструктора-проводника устанавливаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения.\nОснованиями для отказа в аттестации в качестве инструктора-проводника являются:\nнепредставление соискателем документов и сведений, необходимых для аттестации; (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nналичие недостоверной информации в документах и сведениях, представленных соискателем для аттестации; (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nнесоответствие соискателя требованиям, предусмотренным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации;\nпоступление заявления об аттестации от соискателя, указанного в части двадцатой настоящей статьи, до истечения одного года со дня принятия в отношении его решения о прекращении действия аттестации инструктора-проводника. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nВ качестве инструктора-проводника не может быть аттестовано лицо, имеющее судимость за совершение преступлений против половой неприкосновенности и половой свободы личности, против семьи и несовершеннолетних, иных тяжких и особо тяжких преступлений против личности, умышленных преступлений против здоровья населения и общественной нравственности.\nВ случае отсутствия оснований, предусмотренных частью восьмой настоящей статьи, организации, уполномоченные на проведение аттестации инструкторов-проводников, включают сведения о соискателе, прошедшем аттестацию, в единый федеральный реестр инструкторов-проводников, выдают нагрудную идентификационную карточку инструктора-проводника, форма которой утверждается уполномоченным федеральным органом исполнительной власти. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nОказание инструктором-проводником услуг по сопровождению туристов (экскурсантов) на туристских маршрутах, требующих специального сопровождения, допускается со дня включения сведений об инструкторе-проводнике в единый федеральный реестр инструкторов-проводников. Наличие сведений о действующей аттестации инструктора-проводника в едином федеральном реестре инструкторов-проводников позволяет инструктору-проводнику оказывать услуги на туристских маршрутах, требующих специального сопровождения, соответствующих вида и категории сложности, указанных в едином федеральном реестре инструкторов-проводников. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nОрганизации, уполномоченные на проведение аттестации инструкторов-проводников, в порядке, указанном в части пятой настоящей статьи, проводят плановое подтверждение соответствия инструктора-проводника и внеплановое подтверждение соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nПлановое подтверждение соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации, осуществляется каждые пять лет со дня включения сведений об инструкторе-проводнике в единый федеральный реестр инструкторов-проводников. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nИнструкторы-проводники при оказании услуг должны обеспечивать безопасность туристов (экскурсантов) при посещении (прохождении) туристских маршрутов, требующих специального сопровождения, соблюдать правила оказания услуг инструктора-проводника, иметь при себе нагрудную идентификационную карточку инструктора-проводника, доступную для всеобщего обозрения, оказывать первую помощь сопровождаемым туристам. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nНа нагрудной идентификационной карточке инструктора-проводника должны размещаться цветная фотография инструктора-проводника и следующие сведения (на русском и английском языках):\nфамилия, имя и отчество (при наличии) инструктора-проводника;\nуникальный номер записи об инструкторе-проводнике в едином федеральном реестре инструкторов-проводников; (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nвид и категория сложности туристского маршрута, по которому аттестован инструктор-проводник;\nконтактный телефон организации, аттестовавшей инструктора-проводника;\n(Абзац с 01.03.2027 в редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nдвухмерный штриховой код (QR-код), посредством которого обеспечивается переход на страницу единого федерального реестра инструкторов-проводников, содержащую сведения об аттестованном инструкторе-проводнике. (Дополнение абзацем - Федеральный закон от 23.03.2024 № 63-ФЗ)\n(Абзац. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\nОснованиями для прекращения действия аттестации инструктора-проводника являются: (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nотказ (уклонение) инструктора-проводника от прохождения планового подтверждения соответствия инструктора-проводника или внепланового подтверждения соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации; (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nрешение организации, уполномоченной на проведение аттестации инструкторов-проводников, о прекращении действия аттестации. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nОснованиями для принятия решения о прекращении действия аттестации инструктора-проводника являются: (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nвыявление после включения сведений об инструкторе-проводнике в единый федеральный реестр инструкторов-проводников недостоверной информации в документах и сведениях, представленных для аттестации; (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nвыявление после включения сведений об инструкторе-проводнике в единый федеральный реестр инструкторов-проводников несоответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации; (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nнеоднократное (более двух раз в течение одного года) привлечение инструктора-проводника к административной ответственности за нарушение предусмотренных законодательством Российской Федерации о туристской деятельности условий оказания услуг инструктором-проводником;\nпризнание инструктора-проводника не соответствующим требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации, организацией, уполномоченной на проведение аттестации инструкторов-проводников, по результатам планового подтверждения соответствия инструктора-проводника или внепланового подтверждения соответствия инструктора-проводника указанным требованиям и критериям. (Дополнение абзацем - Федеральный закон от 23.03.2024 № 63-ФЗ)\nРешение о прекращении действия аттестации инструктора-проводника принимается организацией, которая проводила аттестацию инструктора-проводника. Сведения о прекращении действия аттестации инструктора-проводника вносятся организацией, принявшей указанное решение, в единый федеральный реестр инструкторов-проводников. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nВ случае исключения Правительством Российской Федерации из перечня, указанного в части третьей настоящей статьи, организации, которая проводила аттестацию инструктора-проводника, принятие решения об исключении сведений об инструкторе-проводнике из единого федерального реестра инструкторов-проводников, проведение планового подтверждения соответствия инструктора-проводника и внепланового подтверждения соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации, осуществляются иной организацией, уполномоченной на проведение аттестации инструкторов-проводников, по видам туристских маршрутов, требующих специального сопровождения, и категориям сложности, на которые аттестован инструктор-проводник. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nИнструктор-проводник, в отношении которого на основании абзаца четвертого части семнадцатой настоящей статьи принято решение о прекращении действия аттестации, вправе обратиться с заявлением об аттестации в организацию, уполномоченную на проведение аттестации инструкторов-проводников, не ранее чем через один год со дня принятия такого решения. (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)\nАттестованный инструктор-проводник обязан направлять уведомления о сопровождении туристов (экскурсантов) на туристском маршруте, требующем специального сопровождения, до начала прохождения туристского маршрута, требующего специального сопровождения, и после завершения прохождения туристского маршрута, требующего специального сопровождения, в территориальный орган федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики в области защиты населения и территорий от чрезвычайных ситуаций природного и техногенного характера, по субъекту Российской Федерации, на территории которого проходит туристский маршрут, требующий специального сопровождения, в орган исполнительной власти субъекта Российской Федерации, уполномоченный на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, в субъекте Российской Федерации, на территории которого проходит туристский маршрут, требующий специального сопровождения, и в организацию, уполномоченную на проведение аттестации инструкторов-проводников, проводившую аттестацию инструктора-проводника. (Дополнение частью - Федеральный закон от 23.03.2024 № 63-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nФормы указанных уведомлений, порядок и сроки их направления утверждаются Правительством Российской Федерации. (Дополнение частью - Федеральный закон от 23.03.2024 № 63-ФЗ)\n(Часть. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\n(Часть. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\n(Часть. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\n(Часть. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\n(Дополнение статьей - Федеральный закон от 20.04.2021 № 93-ФЗ)"],
["4.6","Организации, уполномоченные на проведение аттестации инструкторов-проводников","Глава II. Государственное регулирование туристской деятельности","2024-03-23","Статья 4.6. Организации, уполномоченные на проведение аттестации инструкторов-проводников\nОрганизации вправе проводить аттестацию инструкторов-проводников со дня их включения в перечень, указанный в части третьей статьи 4.5 настоящего Федерального закона. Организации утрачивают такое право со дня исключения их из указанного перечня.\nОрганизации, уполномоченные на проведение аттестации инструкторов-проводников, могут проводить аттестацию инструкторов-проводников на всей территории Российской Федерации. Организации, уполномоченные на проведение аттестации инструкторов-проводников, проводят аттестацию инструкторов-проводников по определенным Правительством Российской Федерации видам и категориям сложности туристских маршрутов, требующих специального сопровождения, а также плановое подтверждение соответствия аттестованных ими инструкторов-проводников и внеплановое подтверждение соответствия аттестованных ими инструкторов-проводников требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации.\nВ перечень, указанный в части третьей статьи 4.5 настоящего Федерального закона, Правительством Российской Федерации по представлению уполномоченного федерального органа исполнительной власти могут быть включены следующие организации:\nобщероссийские спортивные федерации, аккредитованные в соответствии с законодательством Российской Федерации о физической культуре и спорте, по виду спорта, занятие которым позволяет осуществлять безопасное прохождение маршрутов, соответствующих видам и категориям сложности туристских маршрутов, требующих специального сопровождения (по согласованию с такими общероссийскими спортивными федерациями);\nиные организации, осуществляющие деятельность по подготовке специалистов в сфере туризма для осуществления ими трудовой деятельности по сопровождению туристов и обеспечению их безопасности при прохождении туристских маршрутов соответствующих видов и категорий сложности (по согласованию с данными организациями), в том числе в случае отсутствия общероссийской спортивной федерации или исключения общероссийской спортивной федерации из перечня организаций, указанного в части третьей статьи 4.5 настоящего Федерального закона.\nПравительство Российской Федерации определяет не менее одной организации, уполномоченной на проведение аттестации инструкторов-проводников, по каждому виду туристских маршрутов, требующих специального сопровождения.\nОрганизации, уполномоченные на проведение аттестации инструкторов-проводников, в целях осуществления деятельности, предусмотренной статьей 4.5 настоящего Федерального закона и настоящей статьей:\nформируют аттестационные комиссии, в состав которых в том числе включаются представители федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики в области защиты населения и территорий от чрезвычайных ситуаций природного и техногенного характера, или территориальных органов указанного федерального органа исполнительной власти;\nутверждают по согласованию с уполномоченным федеральным органом исполнительной власти правила подготовки инструкторов-проводников, правила расчета необходимого количества инструкторов-проводников с учетом количества туристов (экскурсантов) в группе, вида и категории сложности туристского маршрута, требующего специального сопровождения, а также методику проведения экзамена и перечень вопросов для проведения экзамена, применяемые в ходе аттестации инструкторов-проводников;\nвзимают плату за проведение аттестации инструктора-проводника, плановое подтверждение соответствия инструктора-проводника требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации, в размерах, определяемых в соответствии с методикой и предельными размерами платы, предусмотренными частью пятой статьи 4.5 настоящего Федерального закона;\nосуществляют мониторинг деятельности инструкторов-проводников в части их соответствия требованиям, установленным настоящим Федеральным законом, и критериям аттестации, установленным Правительством Российской Федерации, в порядке, установленном уполномоченным федеральным органом исполнительной власти;\nнаправляют ежеквартально в уполномоченный федеральный орган исполнительной власти отчет о результатах деятельности по аттестации инструкторов-проводников. Форма отчета, включая перечень документов и сведений, которые прилагаются к отчету, утверждается уполномоченным федеральным органом исполнительной власти;\nвправе привлекать для проведения аттестации региональные спортивные федерации, аккредитованные в соответствии с законодательством Российской Федерации о физической культуре и спорте, по виду спорта, занятие которым позволяет осуществлять безопасное прохождение маршрутов, соответствующих видам и категориям сложности туристских маршрутов, требующих специального сопровождения, и иные организации, осуществляющие деятельность по подготовке специалистов в сфере туризма для осуществления ими трудовой деятельности по сопровождению туристов и обеспечению их безопасности при прохождении туристских маршрутов соответствующих видов и категорий сложности на территориях субъектов Российской Федерации.\nУполномоченный федеральный орган исполнительной власти осуществляет рассмотрение отчетов о результатах деятельности по аттестации инструкторов-проводников, жалоб на действия или бездействие организаций, уполномоченных на аттестацию инструкторов-проводников.\nВ целях оказания содействия в рассмотрении отчетов о результатах деятельности по аттестации инструкторов-проводников, жалоб на действия или бездействие организаций, уполномоченных на аттестацию инструкторов-проводников, уполномоченный федеральный орган исполнительной власти формирует совет по вопросам аттестации инструкторов-проводников.\nВ состав совета по вопросам аттестации инструкторов-проводников, утверждаемый уполномоченным федеральным органом исполнительной власти, включаются представители федеральных органов исполнительной власти, организаций, представляющих профессиональные сообщества туроператоров, турагентов, инструкторов-проводников, организаций, которые осуществляют подготовку инструкторов-проводников.\nВ случае выявления уполномоченным федеральным органом исполнительной власти по итогам рассмотрения отчетов о результатах деятельности по аттестации инструкторов-проводников, жалоб на действия или бездействие организаций, уполномоченных на аттестацию инструкторов-проводников, нарушений организацией, уполномоченной на проведение аттестации инструкторов-проводников, порядка аттестации инструкторов-проводников и (или) порядка мониторинга деятельности инструкторов-проводников уполномоченный федеральный орган исполнительной власти направляет в организацию, уполномоченную на проведение аттестации инструкторов-проводников, предписание о необходимости устранения выявленных нарушений, являющееся обязательным для исполнения организацией, уполномоченной на проведение аттестации инструкторов-проводников, с указанием срока устранения выявленных нарушений.\nОрганизация, уполномоченная на проведение аттестации инструкторов-проводников, направляет в уполномоченный федеральный орган исполнительной власти отчет об устранении нарушений, указанных в предписании, который рассматривается уполномоченным федеральным органом исполнительной власти с привлечением при необходимости совета по вопросам аттестации инструкторов-проводников.\nВ случае выявления по итогам рассмотрения уполномоченным федеральным органом исполнительной власти отчетов, указанных в части десятой настоящей статьи, неоднократного (более трех раз в течение одного года) неустранения организацией, уполномоченной на проведение аттестации инструкторов-проводников, нарушений, указанных в предписании, указанном в части девятой настоящей статьи, уполномоченный федеральный орган исполнительной власти направляет в Правительство Российской Федерации представление об исключении организации, уполномоченной на проведение аттестации инструкторов-проводников, из перечня, указанного в части третьей статьи 4.5 настоящего Федерального закона.\nИсключение организаций, уполномоченных на проведение аттестации инструкторов-проводников, из перечня, указанного в части третьей статьи 4.5 настоящего Федерального закона, осуществляется по решению Правительства Российской Федерации в том числе по следующим основаниям:\nпринятие решения о ликвидации организации, уполномоченной на проведение аттестации инструкторов-проводников, или ее реорганизации (за исключением реорганизации в форме преобразования);\nпрекращение действия государственной аккредитации общероссийской спортивной федерации в соответствии с законодательством Российской Федерации о физической культуре и спорте (в отношении организаций, уполномоченных на проведение аттестации инструкторов-проводников и указанных в абзаце втором части третьей настоящей статьи);\nнеоднократное (более трех раз в течение одного года) нарушение организацией, уполномоченной на проведение аттестации инструкторов-проводников, порядка аттестации инструкторов-проводников и (или) порядка мониторинга деятельности инструкторов-проводников, не устраненное в порядке, установленном настоящей статьей.\nВ случае, если исключение организации, уполномоченной на проведение аттестации инструкторов-проводников, приведет к отсутствию в перечне, указанном в части третьей статьи 4.5 настоящего Федерального закона, организаций, уполномоченных на проведение аттестации инструкторов-проводников, по определенным виду и категории сложности туристских маршрутов, требующих специального сопровождения, решение об исключении организации, уполномоченной на проведение аттестации инструкторов-проводников, принимается одновременно с включением в такой перечень иной организации из числа организаций, предусмотренных частью третьей настоящей статьи.\nВ случае прекращения действия государственной аккредитации общероссийской спортивной федерации в соответствии с законодательством Российской Федерации о физической культуре и спорте (в отношении организаций, уполномоченных на проведение аттестации инструкторов-проводников, указанных в абзаце втором части третьей настоящей статьи) Правительство Российской Федерации вправе принять решение о продолжении осуществления ею деятельности, предусмотренной статьей 4.5 настоящего Федерального закона и настоящей статьей, в качестве организации, указанной в абзаце третьем части третьей настоящей статьи.\n(Дополнение статьей - Федеральный закон от 20.04.2021 № 93-ФЗ) (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)"],
["5","Классификация горнолыжных трасс, классификация пляжей","Глава II. Государственное регулирование туристской деятельности","2026-07-04","Статья 5. Классификация горнолыжных трасс, классификация пляжей\n(Наименование в редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nКлассификация горнолыжных трасс, классификация пляжей проводятся организациями, осуществляющими классификацию в сфере туристской индустрии, аккредитованными в соответствии со статьей 5.3 настоящего Федерального закона. (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nПравила классификации горнолыжных трасс, классификации пляжей, утвержденные уполномоченным федеральным органом исполнительной власти, устанавливают порядок классификации горнолыжных трасс, классификации пляжей (в том числе порядок принятия решения об отказе в осуществлении классификации горнолыжной трассы, классификации пляжа, порядок приостановления или прекращения действия классификации горнолыжной трассы или классификации пляжа, категории горнолыжных трасс, категории пляжей, требования к категориям горнолыжных трасс, требования к категориям пляжей, включая требование о соответствии водного объекта санитарным правилам и условиям безопасного для здоровья населения использования водного объекта для купания), а также требования о доведении до потребителей информации о категории горнолыжных трасс, категории пляжей, включая требования к размещению указанной информации. (В редакции федеральных законов от 30.11.2024 № 436-ФЗ, от 04.07.2026 № 235-ФЗ)\nОснованием для отказа в осуществлении классификации горнолыжной трассы или классификации пляжа является: (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nнепредставление лицом, обратившимся с заявлением об осуществлении классификации горнолыжной трассы или классификации пляжа, документов и (или) сведений, необходимых для осуществления соответствующей классификации; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nналичие в документах и (или) сведениях, представленных лицом, обратившимся с заявлением об осуществлении классификации горнолыжной трассы или классификации пляжа, для осуществления соответствующей классификации, недостоверной информации; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nнесоответствие горнолыжной трассы или пляжа ни одной из категорий, установленных правилами классификации горнолыжных трасс, классификации пляжей. (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nПо результатам классификации горнолыжных трасс, классификации пляжей сведения о горнолыжной трассе или пляже, о присвоенной категории, а также документы и (или) сведения, подтверждающие соответствие горнолыжной трассы, пляжа присвоенной категории, вносятся организацией, осуществляющей классификацию в сфере туристской индустрии, в реестр классифицированных горнолыжных трасс или реестр классифицированных пляжей, формирование и ведение которых осуществляются в рамках единого реестра объектов классификации в сфере туристской индустрии, предусмотренного статьей 5.2 настоящего Федерального закона. Классификация горнолыжной трассы или классификация пляжа действует три года с даты включения сведений о присвоении горнолыжной трассе или пляжу определенной категории в реестр классифицированных горнолыжных трасс или реестр классифицированных пляжей. (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nОснованием для приостановления действия классификации горнолыжной трассы или классификации пляжа является: (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nвыявление организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей категорию горнолыжной трассе или пляжу, в документах и (или) сведениях, представленных лицом, предоставляющим услуги, связанные с использованием горнолыжных трасс или пляжей, для осуществления классификации горнолыжной трассы или классификации пляжа, недостоверной информации; (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nабзац; (Утратил силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nвыявление организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей категорию горнолыжной трассе или пляжу, несоответствия горнолыжной трассы или пляжа установленным правилами классификации горнолыжных трасс, классификации пляжей требованиям к категории горнолыжной трассы или пляжа, указанной в реестре классифицированных горнолыжных трасс или реестре классифицированных пляжей, на основании жалобы потребителя услуг, связанных с использованием горнолыжной трассы или пляжа, либо мотивированного представления должностного лица федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного контроля (надзора) в области защиты прав потребителей, о нарушении прав потребителя при предоставлении услуг, связанных с использованием горнолыжной трассы или пляжа, либо мотивированного представления должностного лица федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного санитарно-эпидемиологического контроля (надзора), о несоответствии водного объекта санитарным правилам и условиям безопасного для здоровья населения использования водного объекта для купания, влекущем невозможность использования пляжа в соответствии с присвоенной ему категорией; (В редакции федеральных законов от 30.11.2024 № 436-ФЗ, от 04.07.2026 № 235-ФЗ)\nполучение организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей категорию горнолыжной трассе или пляжу, заявления лица, предоставляющего услуги, связанные с использованием горнолыжной трассы или пляжа, об изменениях, влияющих на соответствие горнолыжной трассы или пляжа установленным правилами классификации горнолыжных трасс, классификации пляжей требованиям к категории горнолыжной трассы или пляжа, указанной в реестре классифицированных горнолыжных трасс или реестре классифицированных пляжей. (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nДействие классификации горнолыжной трассы или действие классификации пляжа приостанавливается организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей категорию горнолыжной трассе или пляжу, на срок не более чем 90 дней. Лицо, предоставляющее услуги, связанные с использованием горнолыжной трассы или пляжа, в течение срока приостановления действия классификации горнолыжной трассы или действия классификации пляжа вправе продолжить использование в рекламе, названии горнолыжной трассы или пляжа и деятельности, связанной с использованием горнолыжной трассы или пляжа, категории, указанной в реестре классифицированных горнолыжных трасс или реестре классифицированных пляжей (за исключением случаев приостановления действия классификации пляжа в соответствии с абзацем пятым части семнадцатой настоящей статьи), с обязательным информированием потребителей о приостановлении действия классификации горнолыжной трассы, действия классификации пляжа. При этом лицо, предоставляющее услуги, связанные с использованием горнолыжной трассы или пляжа, в указанный срок обязано устранить обстоятельства, послужившие основанием для приостановления действия классификации горнолыжной трассы или действия классификации пляжа. (В редакции федеральных законов от 30.11.2024 № 436-ФЗ, от 04.07.2026 № 235-ФЗ)\nОснованием для прекращения действия классификации горнолыжной трассы или действия классификации пляжа определенной категории является:\nнеустранение в течение срока приостановления действия классификации горнолыжной трассы или действия классификации пляжа обстоятельств, послуживших основанием для приостановления действия классификации горнолыжной трассы или действия классификации пляжа;\nокончание срока действия классификации горнолыжной трассы или действия классификации пляжа;\nполучение организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей категорию горнолыжной трассе или пляжу, заявления лица, предоставляющего услуги, связанные с использованием горнолыжной трассы или пляжа, о прекращении деятельности по предоставлению услуг, связанных с использованием горнолыжной трассы или пляжа;\nпрекращение индивидуальным предпринимателем или юридическим лицом, предоставляющими услуги, связанные с использованием горнолыжной трассы или пляжа, деятельности в соответствии с законодательством Российской Федерации о государственной регистрации юридических лиц и индивидуальных предпринимателей.\n(Часть в редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nКатегория горнолыжной трассы или пляжа, используемая в рекламе, названии горнолыжной трассы или пляжа, а также в деятельности, связанной с использованием горнолыжной трассы или пляжа, должна соответствовать категории, указанной в реестре классифицированных горнолыжных трасс или реестре классифицированных пляжей. (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nИспользование в рекламе, названии горнолыжной трассы или пляжа и деятельности, связанной с использованием горнолыжной трассы или пляжа, категории в отсутствие сведений о присвоенной категории горнолыжной трассе или пляжу в реестре классифицированных горнолыжных трасс или реестре классифицированных пляжей, а также категории, не соответствующей категории, указанной в реестре классифицированных горнолыжных трасс или реестре классифицированных пляжей, запрещается. (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\n(Статья в редакции Федерального закона от 05.02.2018 № 16-ФЗ)"],
["5.1","Классификация средств размещения","Глава II. Государственное регулирование туристской деятельности","2026-07-04","Статья 5.1. Классификация средств размещения\nКлассификация средств размещения осуществляется в соответствии с положением о классификации средств размещения, утверждаемым Правительством Российской Федерации, а также в соответствии с правилами классификации средств размещения, утверждаемыми Правительством Российской Федерации.\nПоложение о классификации средств размещения устанавливает в том числе:\nтипы средств размещения, подлежащих классификации;\nтребования к типам средств размещения;\nкатегории отдельных типов средств размещения;\nтребования к категориям отдельных типов средств размещения.\nПравила классификации средств размещения устанавливают в том числе:\nпорядок определения типа средства размещения, оценки соответствия средства размещения требованиям к соответствующему типу средств размещения и присвоения типа средства размещения;\nусловия и порядок присвоения определенной категории средству размещения, включая случаи проведения такого присвоения организациями, осуществляющими классификацию в сфере туристской индустрии, а также порядок принятия решений об отказе в присвоении средству размещения определенной категории средства размещения;\nпорядок приостановления, возобновления или прекращения действия классификации средства размещения, включая порядок изменения, приостановления, возобновления и прекращения действия присвоенной категории средства размещения;\nпорядок и сроки проведения планового подтверждения соответствия средства размещения требованиям к типу средства размещения, а также требованиям к присвоенной категории, включая особенности проведения планового подтверждения соответствия средства размещения требованиям к типу средства размещения и требованиям к присвоенной категории в отношении отдельных типов средств размещения;\nпорядок проведения внепланового подтверждения соответствия средства размещения требованиям к присвоенной категории средства размещения;\nтребования о доведении до потребителей информации о типе средства размещения и присвоенной категории средства размещения, включая требования к размещению, содержанию и форме информационного знака, содержащего указанную информацию.\nСредства размещения в целях их классификации относятся к типам, установленным положением о классификации средств размещения. В рамках отдельных типов средств размещения положением о классификации средств размещения устанавливаются категории средств размещения.\nКлассификация средств размещения включает в себя следующие процедуры:\nопределение типа средства размещения и оценка соответствия средства размещения требованиям к соответствующему типу средств размещения, установленным положением о классификации средств размещения, которые осуществляются юридическим лицом, индивидуальным предпринимателем или физическим лицом (в случаях, установленных федеральными законами), осуществляющими деятельность, связанную с использованием средств размещения (далее - владелец средства размещения);\nвключение сведений о средстве размещения, а также документов и (или) сведений, подтверждающих соответствие средства размещения требованиям к определенному типу средств размещения, в реестр классифицированных средств размещения, формирование и ведение которого осуществляются в рамках единого реестра объектов классификации в сфере туристской индустрии на основании указанной оценки соответствия;\nоценка соответствия средства размещения, отнесенного к определенному типу средств размещения, требованиям к определенной категории средств размещения, установленным положением о классификации средств размещения, и присвоение средству размещения определенной категории (при наличии условий, предусмотренных правилами классификации средств размещения);\nвключение сведений о присвоенной средству размещения категории, а также документов и (или) сведений, подтверждающих соответствие средства размещения требованиям к присвоенной категории средств размещения, в реестр классифицированных средств размещения.\nВключение сведений о санаторно-курортных организациях (за исключением санаторно-курортных организаций, подведомственных федеральным органам исполнительной власти, в которых федеральными законами предусмотрена военная служба или приравненная к ней служба, санаторно-курортных организаций, подведомственных федеральным органам исполнительной власти, руководство деятельностью которых осуществляет Президент Российской Федерации), предоставляющих услуги по временному проживанию физических лиц в составе услуг по санаторно-курортному лечению, в реестр классифицированных средств размещения в рамках классификации средств размещения, а также исключение сведений о таких санаторно-курортных организациях из реестра классифицированных средств размещения осуществляется федеральным органом исполнительной власти, уполномоченным Правительством Российской Федерации на организацию формирования и ведения единого реестра объектов классификации в сфере туристской индустрии (далее - оператор единого реестра объектов классификации), на основе сведений, содержащихся в государственном реестре курортного фонда Российской Федерации, формируемом в соответствии с Федеральным законом от 23 февраля 1995 года № 26-ФЗ \"О природных лечебных ресурсах, лечебно-оздоровительных местностях и курортах\".\nСанаторно-курортные организации, указанные в части шестой настоящей статьи, вправе по своему усмотрению пройти процедуры, предусмотренные абзацами вторым, четвертым, пятым части пятой настоящей статьи, в соответствии с положением о классификации средств размещения и правилами классификации средств размещения.\nСредство размещения является классифицированным со дня включения сведений о средстве размещения в реестр классифицированных средств размещения.\nПриостановление, возобновление или прекращение действия классификации средства размещения осуществляется органом государственной власти субъекта Российской Федерации, уполномоченным на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, в порядке, установленном правилами классификации средств размещения. В случае прекращения действия классификации сведения о средстве размещения исключаются из реестра классифицированных средств размещения в порядке, установленном правилами классификации средств размещения.\nПриостановление действия классификации средств размещения осуществляется на срок не более чем 30 дней.\nВладелец средства размещения в течение срока приостановления действия классификации средства размещения:\nвправе продолжить предоставление услуг средства размещения, гостиничных услуг в соответствии с обязательствами, оформленными до дня приостановления действия классификации средства размещения, с обязательным информированием потребителей о приостановлении действия классификации средства размещения;\nобязан приостановить заключение договоров о предоставлении услуг средства размещения, договоров о предоставлении гостиничных услуг, рекламу и размещение сведений о предоставлении услуг средства размещения, гостиничных услуг со дня приостановления действия классификации средства размещения;\nобязан устранить обстоятельства, послужившие основанием для приостановления действия классификации средства размещения.\nОснованием для приостановления действия классификации средства размещения является:\nвыявление органом государственной власти субъекта Российской Федерации, уполномоченным на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, в документах и (или) сведениях, представленных владельцем средства размещения при классификации средства размещения, недостоверной информации;\nпоступление информации федерального органа исполнительной власти, уполномоченного Правительством Российской Федерации на проведение аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии (далее - орган по аккредитации), о несоответствии требованиям законодательства Российской Федерации сведений о средстве размещения, а также документов и (или) сведений, подтверждающих соответствие средства размещения требованиям к типу средств размещения, содержащихся в реестре классифицированных средств размещения, либо о несоответствии документов и (или) сведений документам и (или) сведениям, содержащимся в иных государственных информационных системах; (В редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nвозникновение обстоятельств, которые приводят к несоответствию средства размещения требованиям к типу средства размещения, устранение которых возможно в период приостановления действия классификации средства размещения;\nвыявление обстоятельств, указанных в абзаце четвертом настоящей части, органом государственной власти субъекта Российской Федерации, уполномоченным на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, по итогам контрольных (надзорных) мероприятий в рамках регионального государственного контроля (надзора) в сфере туристской индустрии;\nнеосуществление владельцем средства размещения планового подтверждения соответствия средства размещения требованиям к типу средства размещения.\nОснованием для прекращения действия классификации средства размещения является:\nнесоответствие средства размещения требованиям к типу средства размещения, указанному в реестре классифицированных средств размещения;\nнеустранение владельцем средства размещения обстоятельств, послуживших основанием для приостановления действия классификации средства размещения, в сроки, предусмотренные частью десятой настоящей статьи;\nпрекращение владельцем средства размещения деятельности в соответствии с законодательством Российской Федерации о государственной регистрации юридических лиц и индивидуальных предпринимателей;\nпоступление в орган государственной власти субъекта Российской Федерации, уполномоченный на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, заявления владельца средства размещения о прекращении деятельности по предоставлению услуг средства размещения, гостиничных услуг;\nвыявление органом государственной власти субъекта Российской Федерации, уполномоченным на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, отсутствия средства размещения по адресу (месту нахождения) объекта недвижимости (здания, сооружения, помещения, земельного участка), в котором в соответствии со сведениями, содержащимися в реестре классифицированных средств размещения, осуществляется деятельность по предоставлению услуг средства размещения, гостиничных услуг, по результатам проведения контрольного (надзорного) мероприятия в рамках регионального государственного контроля (надзора) в сфере туристской индустрии. (Дополнение абзацем - Федеральный закон от 04.07.2026 № 235-ФЗ)\nВладелец средства размещения со дня прекращения действия классификации средства размещения не вправе предоставлять услуги средства размещения, гостиничные услуги, а также обязан прекратить рекламу и размещение сведений о предоставлении услуг средства размещения, гостиничных услуг.\nПриостановление, возобновление и прекращение действия присвоенной категории средства размещения осуществляются организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей средству размещения соответствующую категорию, или органом по аккредитации с учетом рекомендаций совета по классификации средств размещения в порядке, установленном правилами классификации средств размещения.\nДействие присвоенной категории средства размещения приостанавливается на срок не более чем 30 дней. Владелец средства размещения в течение срока приостановления действия присвоенной категории вправе предоставлять услуги средства размещения, гостиничные услуги с обязательным информированием потребителей о приостановлении действия присвоенной категории средства размещения. При этом владелец средства размещения в указанный срок обязан устранить обстоятельства, послужившие основанием для приостановления действия присвоенной категории средства размещения.\nОснованием для приостановления действия присвоенной категории средства размещения является:\nвыявление организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей средству размещения соответствующую категорию, или органом по аккредитации в документах и (или) сведениях, представленных владельцем средства размещения, недостоверной информации;\nприостановление действия классификации средства размещения;\nрешение органа по аккредитации о необходимости приостановления действия присвоенной категории средства размещения по итогам подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии, или контрольных (надзорных) мероприятий в рамках федерального государственного контроля (надзора) за деятельностью организаций, осуществляющих классификацию в сфере туристской индустрии, в соответствии со статьей 19.2 настоящего Федерального закона;\nвыявление организацией, осуществляющей классификацию в сфере туристской индустрии и присвоившей категорию средству размещения, несоответствия средства размещения требованиям к присвоенной категории, в том числе по результатам планового или внепланового подтверждения соответствия средства размещения требованиям к присвоенной категории средства размещения, а также по итогам рассмотрения информации, представленной органом государственной власти субъекта Российской Федерации, уполномоченным на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии;\nотказ или уклонение владельца средства размещения от проведения планового или внепланового подтверждения соответствия средства размещения требованиям к присвоенной категории средства размещения;\nнесоответствие требованиям законодательства Российской Федерации сведений о средстве размещения, а также сведений и (или) документов, подтверждающих соответствие средства размещения требованиям к присвоенной категории средства размещения, содержащихся в реестре классифицированных средств размещения.\nОснованием для возобновления действия присвоенной категории средства размещения является устранение владельцем средства размещения обстоятельств, послуживших основанием для приостановления действия присвоенной категории средства размещения, в сроки, предусмотренные частью шестнадцатой настоящей статьи.\nОснованием для прекращения действия присвоенной категории средства размещения является:\nпрекращение действия классификации средства размещения;\nнеустранение владельцем средства размещения обстоятельств, послуживших основанием для приостановления действия присвоенной категории средства размещения, в сроки, предусмотренные частью шестнадцатой настоящей статьи.\nТип и категория средства размещения, используемые в рекламе, названии средства размещения, а также в деятельности, связанной с использованием средства размещения, должны соответствовать типу и категории средства размещения, указанным в реестре классифицированных средств размещения.\nПредоставление средствами размещения, сведения о которых не включены в реестр классифицированных средств размещения, услуг средства размещения, гостиничных услуг, а также использование в рекламе, названии средства размещения и деятельности, связанной с использованием средства размещения, типа и (или) категории, не соответствующих типу и (или) категории средства размещения, указанным в реестре классифицированных средств размещения, запрещается.\nРазмещение информации о предоставлении услуг средства размещения, гостиничных услуг, в том числе в информационно-телекоммуникационной сети \"Интернет\", включая агрегаторы информации об услугах, сервисы размещения объявлений, социальные сети, осуществляется с обязательным указанием идентификационного номера средства размещения, присвоенного в реестре классифицированных средств размещения, а также ссылки в информационно-телекоммуникационной сети \"Интернет\" на запись в реестре классифицированных средств размещения, содержащую сведения о средстве размещения.\nВладелец агрегатора информации об услугах, владелец сервиса размещения объявлений доводят до сведения потребителей информацию, предусмотренную частью двадцать второй настоящей статьи, путем обеспечения указания в информации о предоставлении услуг средства размещения, гостиничных услуг на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\" представленной владельцем средства размещения ссылки в информационно-телекоммуникационной сети \"Интернет\" на запись в реестре классифицированных средств размещения, содержащую сведения о средстве размещения.\nВладелец агрегатора информации об услугах, владелец сервиса размещения объявлений обязаны обеспечить проверку наличия ссылки в информационно-телекоммуникационной сети \"Интернет\" на запись в реестре классифицированных средств размещения, содержащую сведения о средстве размещения, а также соответствие сведений о средстве размещения, представленных в информации о предоставлении услуг средства размещения, гостиничных услуг на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\", аналогичным сведениям о средстве размещения, указанным в реестре классифицированных средств размещения.\nВладелец агрегатора информации об услугах, владелец сервиса размещения объявлений:\nне допускают указание в информации о предоставлении услуг средства размещения, гостиничных услуг на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\" сведений о средстве размещения, не соответствующих аналогичным сведениям, указанным в реестре классифицированных средств размещения;\nобязаны приостановить предоставление возможности приобретать услуги средства размещения, гостиничные услуги на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\" в случае приостановления действия классификации средства размещения со дня приостановления действия классификации средства размещения до дня возобновления действия классификации средства размещения;\nобязаны прекратить распространение информации о предоставлении услуг средства размещения, гостиничных услуг в случае несоответствия сведений о средстве размещения, представленных в информации о предоставлении услуг средства размещения, гостиничных услуг на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\", аналогичным сведениям, указанным в реестре классифицированных средств размещения, в том числе на основании поступления соответствующей информации от органа по аккредитации, а также в случае прекращения действия классификации средства размещения или на основании поступления предписания, указанного в статье 19.5 настоящего Федерального закона.\nУполномоченный федеральный орган исполнительной власти формирует совет по классификации средств размещения в целях рассмотрения вопросов и предложений по совершенствованию подходов к классификации средств размещения, рассмотрения жалоб на деятельность владельцев средств размещения, рассмотрения вопросов и формирования рекомендаций органу по аккредитации в части приостановления, возобновления или прекращения действия классификации средств размещения, приостановления, возобновления или прекращения действия присвоенной категории средства размещения.\nВ состав совета по классификации средств размещения, утверждаемый уполномоченным федеральным органом исполнительной власти, включаются в том числе представители Федерального Собрания Российской Федерации, федеральных органов исполнительной власти, союзов, ассоциаций в области туристской деятельности и иных заинтересованных организаций, осуществляющих деятельность в сфере туризма. (В редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nСовет по классификации средств размещения осуществляет свою деятельность в соответствии с положением, утверждаемым уполномоченным федеральным органом исполнительной власти.\nДействие настоящей статьи не распространяется на средства размещения, используемые для осуществления основной деятельности организаций отдыха и оздоровления детей, организаций социального обслуживания в соответствии с Федеральным законом от 28 декабря 2013 года № 442-ФЗ \"Об основах социального обслуживания граждан в Российской Федерации\", реабилитационных организаций, предоставляющих комплекс мероприятий и услуг по основным направлениям комплексной реабилитации и абилитации инвалидам, детям-инвалидам, детям от рождения до трех лет (независимо от наличия инвалидности), которые имеют ограничения жизнедеятельности либо риск развития ограничений жизнедеятельности, и их семьям в соответствии с Федеральным законом от 24 ноября 1995 года № 181-ФЗ \"О социальной защите инвалидов в Российской Федерации\", централизованных религиозных организаций и (или) религиозных организаций, входящих в их структуру, деятельности по оказанию услуг в сфере сельского туризма в соответствии с Федеральным законом от 11 июня 2003 года № 74-ФЗ \"О крестьянском (фермерском) хозяйстве\", медицинских организаций (за исключением санаторно-курортных организаций), санаторно-курортных организаций, подведомственных федеральным органам исполнительной власти, в которых федеральными законами предусмотрена военная служба или приравненная к ней служба, санаторно-курортных организаций, подведомственных федеральным органам исполнительной власти, руководство деятельностью которых осуществляет Президент Российской Федерации, а также на средства размещения, относящиеся к специализированному жилищному фонду в соответствии с разделом IV Жилищного кодекса Российской Федерации.\nВключение сведений о средствах размещения, указанных в части двадцать девятой настоящей статьи, в реестр классифицированных средств размещения не требуется.\nВладельцы средств размещения, указанных в части двадцать девятой настоящей статьи, вправе принять решение о проведении классификации средств размещения в соответствии с положениями настоящей статьи.\n(Дополнение статьей - Федеральный закон от 30.11.2024 № 436-ФЗ)"],
["5.2","Единый реестр объектов классификации в сфере туристской индустрии","Глава II. Государственное регулирование туристской деятельности","2024-11-30","Статья 5.2. Единый реестр объектов классификации в сфере туристской индустрии\nСведения о средствах размещения, горнолыжных трассах, пляжах, классифицированных в соответствии с настоящим Федеральным законом, включаются в реестр классифицированных средств размещения, реестр классифицированных горнолыжных трасс и реестр классифицированных пляжей соответственно, формирование и ведение которых осуществляются в рамках единого реестра объектов классификации в сфере туристской индустрии.\nОператор единого реестра объектов классификации обеспечивает организацию формирования и ведения единого реестра объектов классификации в сфере туристской индустрии в рамках федеральной государственной информационной системы в области аккредитации, предусмотренной статьей 25 Федерального закона от 28 декабря 2013 года № 412-ФЗ \"Об аккредитации в национальной системе аккредитации\".\nЕдиный реестр объектов классификации в сфере туристской индустрии включает в себя следующие реестры:\nреестр классифицированных средств размещения;\nреестр классифицированных горнолыжных трасс;\nреестр классифицированных пляжей;\nиные реестры, формирование и ведение которых в рамках единого реестра объектов классификации в сфере туристской индустрии предусмотрены настоящим Федеральным законом и принимаемыми в соответствии с ним нормативными правовыми актами.\nПорядок формирования и ведения единого реестра объектов классификации в сфере туристской индустрии устанавливается Правительством Российской Федерации и предусматривает в том числе:\nпорядок включения сведений об объектах классификации в сфере туристской индустрии, а также документов и (или) сведений, подтверждающих соответствие объектов классификации в сфере туристской индустрии требованиям, установленным положением о классификации средств размещения или правилами классификации горнолыжных трасс, классификации пляжей, в реестры, указанные в части третьей настоящей статьи;\nпорядок проверки достоверности сведений об объектах классификации в сфере туристской индустрии, а также документов и (или) сведений, подтверждающих соответствие объектов классификации в сфере туристской индустрии требованиям, установленным положением о классификации средств размещения или правилами классификации горнолыжных трасс, классификации пляжей, включаемых в реестры, указанные в части третьей настоящей статьи;\nперечень и описание документов и (или) сведений, содержащихся в реестрах, указанных в части третьей настоящей статьи, в том числе в части сведений о наличии в средствах размещения условий для семейного отдыха (семейные номера), а также для обслуживания инвалидов и людей с ограниченными возможностями здоровья;\nпорядок и основания внесения изменений в документы и (или) сведения, содержащиеся в реестрах, указанных в части третьей настоящей статьи;\nпорядок исключения сведений об объектах классификации в сфере туристской индустрии из реестров, указанных в части третьей настоящей статьи;\nпорядок взаимодействия оператора единого реестра объектов классификации в сфере туристской индустрии и федерального органа исполнительной власти, уполномоченного Правительством Российской Федерации на ведение государственного реестра курортного фонда Российской Федерации, в том числе в части включения сведений о санаторно-курортных организациях, указанных в части шестой статьи 5.1 настоящего Федерального закона, в реестр классифицированных средств размещения, исключения сведений о таких санаторно-курортных организациях из реестра классифицированных средств размещения, внесения изменений в сведения о таких санаторно-курортных организациях, содержащиеся в реестре классифицированных средств размещения;\nпорядок обеспечения доступа к информации, содержащейся в едином реестре объектов классификации в сфере туристской индустрии.\n(Дополнение статьей - Федеральный закон от 30.11.2024 № 436-ФЗ)"],
["5.3","Организации, осуществляющие классификацию в сфере туристской индустрии","Глава II. Государственное регулирование туристской деятельности","2024-11-30","Статья 5.3. Организации, осуществляющие классификацию в сфере туристской индустрии\nКлассификация горнолыжных трасс, классификация пляжей, присвоение категории средству размещения проводятся организациями, осуществляющими классификацию в сфере туристской индустрии.\nРаботы по оценке соответствия объектов классификации в сфере туристской индустрии требованиям, установленным положением о классификации средств размещения (в части требований к категориям отдельных средств размещения) или правилами классификации горнолыжных трасс, классификации пляжей, в организациях, осуществляющих классификацию в сфере туристской индустрии, проводят эксперты по классификации, аттестованные и включенные в единый реестр экспертов по классификации в порядке, утвержденном Правительством Российской Федерации (далее - эксперты по классификации).\nАккредитация организаций, осуществляющих классификацию в сфере туристской индустрии, и подтверждение компетентности организаций, осуществляющих классификацию в сфере туристской индустрии, проводятся органом по аккредитации.\nПравительством Российской Федерации устанавливается порядок аккредитации и подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии, включающий в себя порядок аттестации экспертов по классификации и предусматривающий:\nпорядок подачи организацией, осуществляющей классификацию в сфере туристской индустрии, и рассмотрения органом по аккредитации заявления об аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, и прилагаемых к нему документов и (или) сведений;\nперечень и описание сведений, содержащихся в заявлении об аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, а также перечень документов и (или) сведений, прилагаемых к заявлению об аккредитации организации, осуществляющей классификацию в сфере туристской индустрии;\nоснования для возврата заявления об аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, без рассмотрения;\nсроки подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии;\nпорядок и сроки подачи заявления о подтверждении компетентности организации, осуществляющей классификацию в сфере туристской индустрии, и прилагаемых к нему документов и (или) сведений;\nпорядок рассмотрения органом по аккредитации заявления о подтверждении компетентности организации, осуществляющей классификацию в сфере туристской индустрии;\nперечень и описание сведений, содержащихся в заявлении о подтверждении компетентности организации, осуществляющей классификацию в сфере туристской индустрии, а также перечень документов и (или) сведений, прилагаемых к заявлению о подтверждении компетентности организации, осуществляющей классификацию в сфере туристской индустрии;\nтребования к организациям, осуществляющим классификацию в сфере туристской индустрии;\nтребования к экспертам по классификации и порядок аттестации экспертов по классификации, в том числе порядок прекращения действия аттестации экспертов по классификации;\nпорядок расширения области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, включая перечень и описание сведений, содержащихся в заявлении о расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, а также перечень документов и (или) сведений, прилагаемых к заявлению о расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, порядок рассмотрения заявления о расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, основания для возврата заявления о расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, без рассмотрения;\nпорядок проведения оценки соответствия заявителя (организации, осуществляющей классификацию в сфере туристской индустрии) требованиям к организациям, осуществляющим классификацию в сфере туристской индустрии;\nпорядок принятия решения об отказе в аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, о расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии;\nпорядок приостановления, возобновления действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии;\nпорядок прекращения действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, включая перечень и описание сведений, содержащихся в заявлении о прекращении действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, а также перечень документов и (или) сведений, прилагаемых к заявлению о прекращении действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, порядок рассмотрения заявления о прекращении действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, основания для возврата заявления о прекращении действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, без рассмотрения;\nпорядок предоставления организацией, осуществляющей классификацию в сфере туристской индустрии, документов и (или) сведений о своей деятельности, в том числе об изменениях состава своих работников и их компетентности, о результатах работ по оценке соответствия объектов классификации в сфере туристской индустрии требованиям, установленным положением о классификации средств размещения (в части требований к категориям отдельных видов средств размещения) или правилами классификации горнолыжных трасс, классификации пляжей, включая сроки предоставления и состав таких документов и (или) сведений;\nпорядок и сроки уведомления организацией, осуществляющей классификацию в сфере туристской индустрии, уполномоченных органов государственной власти субъектов Российской Федерации о планируемом осуществлении классификации объектов классификации в сфере туристской индустрии на территории соответствующих субъектов Российской Федерации, включая перечень и описание сведений, содержащихся в таком уведомлении.\nОснованием для отказа в аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, является:\nнепредставление указанными организациями документов и (или) сведений, необходимых для аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, расширения области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, в соответствии с порядком аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии;\nналичие в документах и (или) сведениях, представленных указанными организациями для получения аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, расширения области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, недостоверной информации;\nнесоответствие организации, осуществляющей классификацию в сфере туристской индустрии, требованиям к организациям, осуществляющим классификацию в сфере туристской индустрии, установленным порядком аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии;\nпоступление заявления об аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, ранее чем по истечении двух лет со дня прекращения аккредитации по основанию, предусмотренному абзацем шестым части одиннадцатой настоящей статьи.\nВ случае отсутствия оснований, предусмотренных частью пятой настоящей статьи, орган по аккредитации по результатам проведения процедуры аккредитации, процедуры расширения области аккредитации включает сведения об аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, о расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, в реестр организаций, осуществляющих классификацию в сфере туристской индустрии.\nАккредитация организаций, осуществляющих классификацию в сфере туристской индустрии, позволяет им осуществлять классификацию объектов классификации в сфере туристской индустрии, включенных в область аккредитации, на всей территории Российской Федерации при условии уведомления уполномоченных органов государственной власти субъектов Российской Федерации, на территории которых планируется осуществлять соответствующую классификацию, в порядке и сроки, которые установлены Правительством Российской Федерации.\nВ область аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, включаются объекты классификации в сфере туристской индустрии (средства размещения, горнолыжные трассы, пляжи), подлежащие классификации в соответствии с настоящим Федеральным законом. В отношении средств размещения в области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, указывается тип средств размещения, а также категории средств размещения. В область аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, могут быть включены несколько объектов классификации в сфере туристской индустрии. Включение объектов классификации в область аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии, имеющих аккредитацию в соответствии с настоящей статьей, осуществляется в рамках расширения области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии.\nОрганизации, осуществляющие классификацию в сфере туристской индустрии, обязаны:\nсоблюдать требования, установленные порядком аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии, и подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии, а также требования, установленные соответственно правилами классификации горнолыжных трасс, классификации пляжей, положением о классификации средств размещения, правилами классификации средств размещения, при осуществлении своей деятельности;\nрассматривать жалобы и обращения, относящиеся к их деятельности (в том числе поступившие в орган по аккредитации и направленные в организации, осуществляющие классификацию в сфере туристской индустрии, для рассмотрения), и давать ответы на эти жалобы и обращения в течение 10 рабочих дней со дня их поступления;\nпредоставлять по запросам органа по аккредитации документы и (или) сведения в электронной форме, включая электронные документы и (или) электронные образы документов, которые свидетельствуют об их соответствии требованиям, установленным порядком аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии, и подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии (с учетом требований законодательства Российской Федерации к предоставлению сведений, составляющих государственную тайну или относимых к охраняемой в соответствии с законодательством Российской Федерации иной информации ограниченного доступа), в течение 15 рабочих дней с даты получения запроса;\nсвоевременно предоставлять на безвозмездной основе в орган по аккредитации документы и (или) сведения о своей деятельности в соответствии с порядком аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии, и подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии;\nобеспечивать рассмотрение поступающей информации органа государственной власти субъекта Российской Федерации, уполномоченного на осуществление регионального государственного контроля (надзора) в сфере туристской индустрии, о выявлении несоответствия средства размещения требованиям к категории средств размещения, указанной в реестре классифицированных средств размещения, с запросом, предусмотренным частью четырнадцатой статьи 19.5 настоящего Федерального закона, проводить внеплановое подтверждение соответствия средства размещения требованиям к присвоенной категории средства размещения в случае выявления признаков несоответствия средства размещения присвоенной категории, а также предоставлять отчет о результатах рассмотрения указанной информации с запросом в соответствующий орган государственной власти субъекта Российской Федерации;\nуведомлять о приостановлении, прекращении действия аккредитации или сокращении своей области аккредитации заказчиков, а также лиц, с которыми у организации, осуществляющей классификацию в сфере туристской индустрии, в течение трех лет, предшествующих приостановлению, прекращению действия аккредитации или сокращению области аккредитации, были заключены договоры на выполнение работ или оказание услуг в области аккредитации (проведена классификация горнолыжных трасс, классификация пляжей, присвоена категория средству размещения).\nОснованием для приостановления действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, является:\nвыявление в документах и (или) сведениях, содержащихся в реестре организаций, осуществляющих классификацию в сфере туристской индустрии, в том числе представленных указанной организацией для получения аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, расширения области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, и подтверждения компетентности организации, осуществляющей классификацию в сфере туристской индустрии, недостоверной информации;\nуклонение или отказ организации, осуществляющей классификацию в сфере туристской индустрии, от прохождения подтверждения компетентности организации, осуществляющей классификацию в сфере туристской индустрии;\nвыявление несоответствия организации, осуществляющей классификацию в сфере туристской индустрии, требованиям к организациям, осуществляющим классификацию в сфере туристской индустрии, установленным порядком аккредитации и подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии, по итогам подтверждения компетентности организации, осуществляющей классификацию в сфере туристской индустрии, или контрольных (надзорных) мероприятий, проводимых в рамках федерального государственного контроля (надзора) за деятельностью организаций, осуществляющих классификацию в сфере туристской индустрии, предусмотренного статьей 19.2 настоящего Федерального закона;\nприсвоение организацией, осуществляющей классификацию в сфере туристской индустрии, категории средству размещения, горнолыжной трассе, пляжу с нарушением требований соответственно положения о классификации средств размещения, правил классификации средств размещения, правил классификации горнолыжных трасс, классификации пляжей;\nвыявление органом по аккредитации несоблюдения организацией, осуществляющей классификацию в сфере туристской индустрии, обязанностей, установленных частью девятой настоящей статьи.\nОснованием для прекращения действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, является:\nнеустранение организацией, осуществляющей классификацию в сфере туристской индустрии, обстоятельств, послуживших основанием для приостановления действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии;\nполучение органом по аккредитации заявления организации, осуществляющей классификацию в сфере туристской индустрии, о прекращении деятельности по осуществлению классификации объектов классификации в сфере туристской индустрии;\nпрекращение организацией, осуществляющей классификацию в сфере туристской индустрии, деятельности в соответствии с законодательством Российской Федерации о государственной регистрации юридических лиц и индивидуальных предпринимателей;\nотсутствие в реестре организаций, осуществляющих классификацию в сфере туристской индустрии, и в реестрах, указанных в части третьей статьи 5.2 настоящего Федерального закона, сведений об осуществлении организацией, осуществляющей классификацию в сфере туристской индустрии, деятельности по осуществлению классификации объектов классификации в сфере туристской индустрии, включенных в область аккредитации, в течение одного года;\nпроведение организацией, осуществляющей классификацию в сфере туристской индустрии, классификации объектов классификации в сфере туристской индустрии с нарушением более четырех раз требований соответственно положения о классификации средств размещения, правил классификации средств размещения, правил классификации горнолыжных трасс, классификации пляжей.\nОрганизации, осуществляющие классификацию в сфере туристской индустрии, аккредитация которых прекращена в соответствии с абзацем шестым части одиннадцатой настоящей статьи, вправе обратиться за повторной аккредитацией для осуществления деятельности по классификации объектов классификации в сфере туристской индустрии не ранее чем по истечении двух лет со дня прекращения действия аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии.\nСокращение области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, осуществляется в случае:\nесли организация, осуществляющая классификацию в сфере туристской индустрии, действие аккредитации которой было приостановлено по основаниям, указанным в части десятой настоящей статьи, не устранила обстоятельства, послужившие основанием для приостановления действия аккредитации, в отношении части области аккредитации;\nвнесения организацией, осуществляющей классификацию в сфере туристской индустрии, в реестр организаций, осуществляющих классификацию в сфере туристской индустрии, сведений о сокращении области аккредитации.\nСокращение области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, в соответствии с абзацем третьим части тринадцатой настоящей статьи осуществляется организацией, осуществляющей классификацию в сфере туристской индустрии, путем внесения в реестр организаций, осуществляющих классификацию в сфере туристской индустрии, сведений о сокращении области аккредитации. В период прохождения организацией, осуществляющей классификацию в сфере туристской индустрии, процедуры подтверждения компетентности сокращение области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, не допускается.\nОрганизация, осуществляющая классификацию в сфере туристской индустрии, в отношении которой федеральным органом исполнительной власти, уполномоченным Правительством Российской Федерации на осуществление аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии (далее - орган по аккредитации), принято решение о сокращении области аккредитации, или организация, осуществляющая классификацию в сфере туристской индустрии, которая сократила область аккредитации (в случае, если действие аккредитации на дату внесения организацией, осуществляющей классификацию в сфере туристской индустрии, в реестр организаций, осуществляющих классификацию в сфере туристской индустрии, сведений о сокращении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, было приостановлено в отношении сокращенной части области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии), вправе обратиться в орган по аккредитации с заявлением о расширении области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, в целях получения аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, на область аккредитации, аналогичную сокращенной, не ранее чем по истечении двух лет со дня принятия такого решения или со дня внесения организацией, осуществляющей классификацию в сфере туристской индустрии, в реестр организаций, осуществляющих классификацию в сфере туристской индустрии, указанных сведений.\nОрганизация, осуществляющая классификацию в сфере туристской индустрии, которая присвоила категорию средству размещения, обязана проводить плановое или внеплановое подтверждение соответствия средства размещения требованиям к присвоенной категории средства размещения в соответствии с правилами классификации средств размещения.\nВ случае прекращения действия аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, присвоившей категорию средству размещения, либо сокращения области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, владелец средства размещения должен обратиться в иную организацию, осуществляющую классификацию в сфере туристской индустрии, с действующей областью аккредитации, включающей соответствующую категорию средства размещения, в целях проведения планового или внепланового подтверждения соответствия средства размещения присвоенной категории средства размещения.\nОрганизация, осуществляющая классификацию в сфере туристской индустрии, в которую обращается владелец средства размещения в соответствии с частью семнадцатой настоящей статьи, пользуется всеми правами и несет все обязанности и ответственность, которые предусмотрены законодательством Российской Федерации для организации, осуществляющей классификацию в сфере туристской индустрии, присвоившей категорию средству размещения.\nВозмещение убытков, связанных с невыполнением организацией, осуществляющей классификацию в сфере туристской индустрии, обязанностей, предусмотренных абзацем седьмым части девятой настоящей статьи, а также с прекращением действия аккредитации или сокращением области аккредитации организации, осуществляющей классификацию в сфере туристской индустрии, осуществляется в соответствии с гражданским законодательством Российской Федерации.\nПорядок формирования и ведения реестра организаций, осуществляющих классификацию в сфере туристской индустрии, устанавливается Правительством Российской Федерации и предусматривает в том числе:\nпорядок включения документов и (или) сведений в реестр организаций, осуществляющих классификацию в сфере туристской индустрии;\nперечень и описание документов и (или) сведений, содержащихся в реестре организаций, осуществляющих классификацию в сфере туристской индустрии;\nпорядок и основания внесения изменений в документы и (или) сведения, содержащиеся в реестре организаций, осуществляющих классификацию в сфере туристской индустрии, включая перечень и описание сведений, содержащихся в заявлении о внесении изменений в сведения реестра организаций, осуществляющих классификацию в сфере туристской индустрии, а также перечень документов и (или) сведений, прилагаемых к указанному заявлению, порядок рассмотрения указанного заявления, основания для возврата указанного заявления без рассмотрения, основания для отказа во внесении изменений в сведения реестра организаций, осуществляющих классификацию в сфере туристской индустрии;\nпорядок формирования и ведения реестра экспертов по классификации объектов классификации в сфере туристской индустрии, устанавливающий в том числе порядок включения экспертов по классификации в указанный реестр, внесения изменений в сведения об экспертах по классификации, содержащиеся в указанном реестре, и порядок исключения экспертов по классификации из реестра экспертов по классификации объектов классификации в сфере туристской индустрии.\n(Дополнение статьей - Федеральный закон от 30.11.2024 № 436-ФЗ)"],
["6","Права туриста","Глава III. Права и обязанности туриста","2022-05-28","Статья 6. Права туриста\nПри подготовке к путешествию, во время его совершения, включая транзит, турист имеет право на:\nнеобходимую и достоверную информацию о правилах въезда в страну (место) временного пребывания и пребывания там, об обычаях местного населения, о религиозных обрядах, святынях, памятниках природы, истории, культуры и других объектах туристского показа, находящихся под особой охраной, состоянии окружающей среды; (В редакции Федерального закона от 30.12.2008 № 309-ФЗ)\nсвободу передвижения, свободный доступ к туристским ресурсам с учетом принятых в стране (месте) временного пребывания ограничительных мер;\nобеспечение личной безопасности, своих потребительских прав и сохранности своего имущества, беспрепятственное получение неотложной медицинской помощи;\nобеспечение в соответствии с настоящим Федеральным законом экстренной помощи за счет средств резервного фонда объединения туроператоров в сфере выездного туризма; (Дополнение абзацем - Федеральный закон от 03.05.2012 № 47-ФЗ) (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nвозмещение убытков и компенсацию морального вреда в случае невыполнения условий договора о реализации туристского продукта туроператором или турагентом в порядке, установленном законодательством Российской Федерации; (В редакции Федерального закона от 05.02.2007 № 12-ФЗ)\nсодействие органов власти (органов местного самоуправления) страны (места) временного пребывания в получении правовой и иных видов неотложной помощи;\nбеспрепятственный доступ к средствам связи;\nполучение копии свидетельства о внесении сведений о туроператоре в реестр туроператоров; (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nинформацию о возможности добровольно застраховать риски, связанные с совершением путешествия и не покрываемые финансовым обеспечением ответственности туроператора, в том числе в связи с ненадлежащим исполнением туроператором обязательств по договору о реализации туристского продукта; (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ)\nполучение сведений, содержащихся в единой информационной системе электронных путевок, в порядке и срок, которые установлены правилами функционирования единой электронной системы электронных путевок, установленными Правительством Российской Федерации, в том числе в целях защиты своих прав. (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)"],
["7","Обязанности туриста","Глава III. Права и обязанности туриста","2008-12-30","Статья 7. Обязанности туриста\nВо время совершения путешествия, включая транзит, турист обязан:\nсоблюдать законодательство страны (места) временного пребывания, уважать ее социальное устройство, обычаи, традиции, религиозные верования;\nсохранять окружающую среду, бережно относиться к памятникам природы, истории и культуры в стране (месте) временного пребывания; (В редакции Федерального закона от 30.12.2008 № 309-ФЗ)\nсоблюдать правила въезда в страну (место) временного пребывания, выезда из страны (места) временного пребывания и пребывания там, а также в странах транзитного проезда;\nсоблюдать во время путешествия правила личной безопасности."],
["8","(Статья утратила силу - Федеральный закон от 22.08.2004 № 122-ФЗ)","Глава III. Права и обязанности туриста","2004-08-22","Статья 8. (Статья утратила силу - Федеральный закон от 22.08.2004 № 122-ФЗ)"],
["9","Общие условия формирования, продвижения и реализации туристского продукта","Глава IV. Особенности формирования, продвижения и реализации туристского продукта","2022-05-28","Статья 9. Общие условия формирования, продвижения и реализации туристского продукта\nТуристский продукт формируется туроператором по его усмотрению исходя из конъюнктуры туристского рынка или по заданию туриста или иного заказчика туристского продукта (далее - иной заказчик).\nТуроператор обеспечивает оказание туристу всех услуг, входящих в туристский продукт, самостоятельно или с привлечением третьих лиц, на которых туроператором возлагается исполнение части или всех его обязательств перед туристом и (или) иным заказчиком. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nТуроператор и турагент несут предусмотренную законодательством Российской Федерации ответственность за неисполнение или ненадлежащее исполнение обязательств как друг перед другом, так и перед туристом и (или) иным заказчиком. Туроператор и турагент самостоятельно отвечают перед туристом и (или) иным заказчиком. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nПо договору о реализации туристского продукта, заключенному турагентом, туроператор несет ответственность за неоказание или ненадлежащее оказание туристу и (или) иному заказчику услуг, входящих в туристский продукт, независимо от того, кем должны были оказываться или оказывались эти услуги. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nТуроператор отвечает перед туристом или иным заказчиком за действия (бездействие) третьих лиц, оказывающих услуги, входящие в туристский продукт, если федеральными законами и иными нормативными правовыми актами Российской Федерации не установлено, что ответственность перед туристом или иным заказчиком несет третье лицо. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nПродвижение и реализация туристского продукта турагентом, субагентом допускаются при условии наличия сведений о турагенте, субагенте в реестре турагентов. Турагент осуществляет продвижение и реализацию туристского продукта по поручению туроператора. Поручением туроператора в целях настоящего Федерального закона признается внесение туроператором сведений о наличии договора на продвижение и реализацию туристского продукта с турагентом в реестр турагентов или подтверждение туроператором в реестре турагентов права субагента на продвижение и реализацию туристского продукта, сформированного туроператором, в случае, если туроператор наделил турагента правом заключения с субагентами договоров на продвижение и реализацию туристского продукта, предусматривающих передачу исполнения поручения на продвижение и реализацию туристского продукта. (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nВ договоре, заключаемом между туроператором и турагентом, должны содержаться:\nусловия продвижения и реализации турагентом туристского продукта;\nполномочия турагента на совершение сделок с туристами и (или) иными заказчиками от имени туроператора;\nусловие, предусматривающее возможность (невозможность) заключения турагентом субагентских договоров;\nпорядок взаимодействия туроператора и турагента в случае предъявления им претензий туристов или иных заказчиков по договору о реализации туристского продукта, а также в случае необходимости оказания экстренной помощи туристу; (В редакции Федерального закона от 03.05.2012 № 47-ФЗ)\nусловие, предусматривающее возможность осуществления выплат туристам и (или) иным заказчикам страхового возмещения по договору страхования ответственности туроператора либо уплаты денежной суммы по банковской гарантии в случае заключения договора о реализации туристского продукта между туристом и (или) иным заказчиком и турагентом;\nвзаимная ответственность туроператора и турагента, а также ответственность каждой из сторон перед туристом и (или) иным заказчиком за непредставление или представление недостоверной информации о туристском продукте, за неисполнение или ненадлежащее исполнение обязательств по договору о реализации туристского продукта;\nобязательство турагента по направлению туроператору, сформировавшему туристский продукт, уведомления о заключении договора о реализации туристского продукта в порядке и срок, которые установлены правилами функционирования единой электронной системы электронных путевок, установленными Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 28.05.2022 № 148-ФЗ)\nТуроператор размещает сведения о турагентах, осуществляющих продвижение и реализацию туристского продукта, сформированного туроператором, посредством размещения информации о реестре турагентов на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\". (Дополнение частью - Федеральный закон от 03.05.2012 № 47-ФЗ) (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nПри реализации туристского продукта туроператор, турагент, действуя в качестве страхового агента от имени и за счет страховщика, вправе заключить с туристом или иным заказчиком в пользу туриста договор добровольного страхования имущественных интересов туриста в соответствии с требованиями законодательства Российской Федерации и с учетом положений статьи 17 настоящего Федерального закона (далее - договор добровольного страхования). (Дополнение частью - Федеральный закон от 29.06.2015 № 155-ФЗ)\nТуроператор, турагент обязаны размещать информацию о страховщиках, от имени которых туроператор, турагент заключают договоры добровольного страхования, на своих официальных сайтах в информационно-телекоммуникационной сети \"Интернет\". (Дополнение частью - Федеральный закон от 29.06.2015 № 155-ФЗ)\nОсуществление турагентской деятельности лицом, сведения о котором отсутствуют в реестре турагентов, влечет за собой административную ответственность в соответствии с законодательством Российской Федерации. (Дополнение частью - Федеральный закон от 24.03.2021 № 48-ФЗ)\nОсуществление турагентом деятельности по продвижению и реализации туристского продукта при отсутствии в реестре турагентов сведений о заключении между турагентом и туроператором, сформировавшим туристский продукт, договора на продвижение и реализацию туристского продукта, сформированного туроператором, влечет за собой административную ответственность в соответствии с законодательством Российской Федерации. (Дополнение частью - Федеральный закон от 24.03.2021 № 48-ФЗ)\nПередача турагентом исполнения поручения туроператора на продвижение и реализацию туристского продукта при отсутствии у турагента права на такую передачу влечет за собой административную ответственность в соответствии с законодательством Российской Федерации. (Дополнение частью - Федеральный закон от 24.03.2021 № 48-ФЗ)\nОсуществление субагентом деятельности по продвижению и реализации туристского продукта при отсутствии в реестре турагентов сведений о заключении между субагентом и турагентом договора, предусматривающего передачу исполнения поручения туроператора на продвижение и реализацию туристского продукта, сформированного туроператором, влечет за собой административную ответственность в соответствии с законодательством Российской Федерации. (Дополнение частью - Федеральный закон от 24.03.2021 № 48-ФЗ)\nПравила настоящего Федерального закона о продвижении и реализации туристского продукта турагентом применяются к продвижению и реализации туристского продукта субагентом. (Дополнение частью - Федеральный закон от 24.03.2021 № 48-ФЗ)\nЗапрещается реализация туристского продукта туроператором или турагентом, действующим по поручению туроператора (за исключением организаций, указанных в абзацах втором и третьем части пятой статьи 4.1 настоящего Федерального закона), без передачи туроператором сведений, содержащихся в договоре о реализации туристского продукта, в единую информационную систему электронных путевок в соответствии со статьей 10.4 настоящего Федерального закона, а также без направления турагентом туроператору, сформировавшему туристский продукт, уведомления о заключении договора о реализации туристского продукта в порядке и срок, которые установлены правилами функционирования единой электронной системы электронных путевок, установленными Правительством Российской Федерации. (Дополнение частью - Федеральный закон от 28.05.2022 № 148-ФЗ)\n(Статья в редакции Федерального закона от 05.02.2007 № 12-ФЗ)"],
["9.1","Особенности формирования туристского продукта","Глава IV. Особенности формирования, продвижения и реализации туристского продукта","2025-12-29","Статья 9.1. Особенности формирования туристского продукта\nТуристский продукт в сфере выездного туризма считается сформированным туроператором при условии, если в состав такого туристского продукта включены услуги по перевозке туриста из Российской Федерации в страну (страны) временного пребывания и (или) обратно в Российскую Федерацию из страны (стран) временного пребывания и услуги по размещению в стране (странах) временного пребывания.\nТуристский продукт в сфере внутреннего туризма и въездного туризма считается сформированным туроператором при условии, если в состав такого туристского продукта включены услуга по размещению в средстве размещения на территории Российской Федерации и хотя бы одна дополнительная услуга, предусмотренная частью третьей настоящей статьи.\nПри формировании туристского продукта в сфере внутреннего туризма и въездного туризма в состав такого туристского продукта могут быть включены следующие дополнительные услуги:\nперевозка туриста любым видом транспорта;\nуслуги экскурсовода (гида), в том числе оказываемые экскурсоводами (гидами), указанными в части двадцать седьмой статьи 4.4 настоящего Федерального закона;\nуслуги гида-переводчика, в том числе оказываемые гидами-переводчиками, указанными в части двадцать седьмой статьи 4.4 настоящего Федерального закона;\nуслуги инструктора-проводника.\nВ случае, если реализация туристского продукта в сфере внутреннего туризма и въездного туризма предполагает прохождение туристом (экскурсантом) туристского маршрута (части туристского маршрута), отнесенного к видам и категориям сложности в соответствии с перечнем видов туристских маршрутов (частей туристских маршрутов), требующих специального сопровождения, в состав такого туристского продукта в обязательном порядке включаются услуги инструктора-проводника.\nПри формировании туристского продукта в соответствии с настоящей статьей в состав такого туристского продукта также могут включаться иные услуги, оказываемые за общую цену по договору о реализации туристского продукта.\n(Дополнение статьей - Федеральный закон от 29.12.2025 № 553-ФЗ)"],
["10","Особенности реализации туристского продукта","Глава IV. Особенности формирования, продвижения и реализации туристского продукта","2025-12-29","Статья 10. Особенности реализации туристского продукта\nРеализация туристского продукта осуществляется на основании договора, заключаемого в письменной форме, в том числе в форме электронного документа, между туроператором и туристом и (или) иным заказчиком, а в случаях, предусмотренных настоящим Федеральным законом, между турагентом и туристом и (или) иным заказчиком. Указанный договор должен соответствовать законодательству Российской Федерации, в том числе законодательству о защите прав потребителей. Типовые формы договора о реализации туристского продукта, заключаемого между туроператором и туристом и (или) иным заказчиком, и договора о реализации туристского продукта, заключаемого между турагентом и туристом и (или) иным заказчиком, утверждаются уполномоченным федеральным органом исполнительной власти. Сведения, содержащиеся в договоре о реализации туристского продукта, передаются туроператором (за исключением организаций, указанных в абзацах втором и третьем части пятой статьи 4.1 настоящего Федерального закона) в единую информационную систему электронных путевок в соответствии со статьей 10.4 настоящего Федерального закона. (В редакции федеральных законов от 02.03.2016 № 49-ФЗ, от 28.05.2022 № 148-ФЗ)\nК существенным условиям договора о реализации туристского продукта относятся:\nполное и сокращенное наименования, адрес (место нахождения), почтовый адрес и реестровый номер туроператора;\nразмер финансового обеспечения ответственности туроператора, номер, дата и срок действия договора или договоров страхования ответственности туроператора и (или) банковской гарантии или банковских гарантий, наименование, адрес, место нахождения организации, предоставившей финансовое обеспечение ответственности туроператора, в случае, если фонд персональной ответственности туроператора не достиг максимального размера (за исключением туроператоров, указанных в абзацах втором и третьем части пятой статьи 4.1 настоящего Федерального закона); (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nсведения о туристе, а также об ином заказчике и его полномочиях (если турист не является заказчиком) в объеме, необходимом для реализации туристского продукта;\nобщая цена туристского продукта в рублях;\nинформация о потребительских свойствах туристского продукта - о программе пребывания, маршруте и об условиях путешествия, включая информацию о средствах размещения, об условиях проживания (месте нахождения средства размещения, категории гостиницы) и питания, услугах по перевозке туриста в стране (месте) временного пребывания, о наличии экскурсовода (гида), гида-переводчика, инструктора-проводника, а также о дополнительных услугах; (В редакции Федерального закона от 05.02.2018 № 16-ФЗ)\nправа, обязанности и ответственность сторон;\nусловия изменения и расторжения договора;\nсведения о порядке и сроках предъявления туристом и (или) иным заказчиком претензий к туроператору в случае нарушения туроператором условий договора;\nинформация о порядке и сроках предъявления туристом и (или) иным заказчиком требований о выплате страхового возмещения по договору страхования ответственности туроператора либо требований об уплате денежной суммы по банковской гарантии, а также требований о возмещении реального ущерба туристу и (или) иному заказчику за счет средств фонда персональной ответственности туроператора при условии, что денежных средств страховщика или гаранта для выплаты страхового возмещения по договору страхования ответственности туроператора или уплаты денежной суммы по банковской гарантии оказалось недостаточно в случае, если фонд персональной ответственности туроператора не достиг максимального размера (за исключением туроператоров, указанных в абзацах втором и третьем части пятой статьи 4.1 настоящего Федерального закона); (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nинформация о порядке и сроках предъявления туристом и (или) иным заказчиком требований о возмещении реального ущерба туристу и (или) иному заказчику за счет средств фонда персональной ответственности туроператора в случае, если фонд персональной ответственности туроператора достиг максимального размера; (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ)\nусловие выдачи туристу и (или) иному заказчику, приобретающим услугу по перевозке, оказываемую туроператором отдельно либо в составе туристского продукта, электронного перевозочного документа (билета), подтверждающего право туриста на перевозку до пункта назначения и обратно либо по иному согласованному в договоре о реализации туристского продукта маршруту и оформленного на основании данных документа, удостоверяющего личность пассажира. Если договор о реализации туристского продукта заключен ранее чем за 24 часа до начала путешествия, такой документ (билет) должен быть выдан туристу и (или) иному заказчику не позднее чем за 24 часа до начала путешествия; (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ)\nусловие выдачи туристу и (или) иному заказчику, приобретающим у туроператора услугу по размещению в гостинице или ином средстве размещения отдельно либо в составе туристского продукта, документа о бронировании и получении места в гостинице или ином средстве размещения (ваучера) на условиях, согласованных с туристом и (или) иным заказчиком в договоре о реализации туристского продукта. (Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ)\nИные условия указанного договора определяются по соглашению сторон.\nЧасть. (Утратила силу - Федеральный закон от 03.05.2012 № 47-ФЗ)\nДоговор о реализации туристского продукта должен содержать сведения о заключении в пользу туриста договора добровольного страхования, условиями которого предусмотрена обязанность страховщика осуществить оплату и (или) возместить расходы на оплату медицинской помощи в экстренной и неотложной формах, оказанной туристу на территории страны временного пребывания при наступлении страхового случая в связи с получением травмы, отравлением, внезапным острым заболеванием или обострением хронического заболевания, включая медицинскую эвакуацию туриста в стране временного пребывания и из страны временного пребывания в страну постоянного проживания (далее - медицинская помощь в экстренной и неотложной формах в стране временного пребывания), и (или) возвращения тела (останков) туриста из страны временного пребывания в страну постоянного проживания (далее - возвращение тела (останков) в соответствии с требованиями законодательства Российской Федерации и страны временного пребывания, или сведения об отсутствии договора добровольного страхования. (Дополнение частью - Федеральный закон от 29.06.2015 № 155-ФЗ)\nКаждая из сторон вправе потребовать изменения или расторжения договора о реализации туристского продукта в связи с существенным изменением обстоятельств, из которых исходили стороны при заключении договора.\nК существенным изменениям обстоятельств относятся:\nухудшение условий путешествия, указанных в договоре; (В редакции Федерального закона от 03.05.2012 № 47-ФЗ)\nизменение сроков совершения путешествия;\nнепредвиденный рост транспортных тарифов;\nневозможность совершения туристом поездки по независящим от него обстоятельствам (болезнь туриста, отказ в выдаче визы и другие обстоятельства);\nпризыв гражданина на военную службу по мобилизации в Вооруженные Силы Российской Федерации, либо поступление на военную службу по контракту в период с 24 февраля 2022 года, либо заключение контракта о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, в период с 24 февраля 2022 года. (Дополнение абзацем - Федеральный закон от 13.06.2023 № 252-ФЗ) (В редакции Федерального закона от 25.12.2023 № 639-ФЗ)\nПретензии к качеству туристского продукта предъявляются туристом и (или) иным заказчиком туроператору в письменной форме в течение 20 дней со дня окончания действия договора и подлежат рассмотрению в течение 10 дней со дня получения претензий.\nПри заключении договора о реализации туристского продукта в сфере выездного туризма турист и (или) иной заказчик должны быть проинформированы в письменной форме:\nо возможности туриста обратиться за оказанием экстренной помощи с указанием сведений об объединении туроператоров в сфере выездного туризма и о способах связи с ним (номеров телефонов, факсов, адреса электронной почты) и других сведений;\nо возможности туриста и (или) иного заказчика обратиться с письменным требованием о возмещении реального ущерба, понесенного туристом в результате неисполнения туроператором обязательств по договору о реализации туристского продукта, за счет средств фонда персональной ответственности туроператора (в случае, установленном частью десятой статьи 11.6 настоящего Федерального закона).\n(Дополнение частью - Федеральный закон от 03.05.2012 № 47-ФЗ) (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nПри заключении договора о реализации туристского продукта в сфере выездного туризма турист и (или) иной заказчик должны быть проинформированы о возможности туриста добровольно застраховать риски, связанные с совершением путешествия и не покрываемые финансовым обеспечением ответственности туроператора, в том числе в связи с ненадлежащим исполнением туроператором обязательств по договору о реализации туристского продукта. (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ)\nВ случае заключения туристом и (или) иным заказчиком с одним юридическим или физическим лицом отдельных договоров на оказание услуг, включенных в состав туристского продукта, на одно и то же лицо и на один и тот же период услуги, оказываемые по таким договорам, приравниваются к услугам, оказываемым при реализации туристского продукта, за исключением случая, если дополнительные услуги, предусмотренные частью третьей статьи 9.1 настоящего Федерального закона, предоставляются указанному в таких договорах туристу непосредственно лицом, предоставляющим услугу по размещению в средстве размещения. (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 29.12.2025 № 553-ФЗ)\nВ случае, если туристский маршрут предусматривает посещение туристом объектов показа, включая места религиозного почитания (паломничества), принадлежащих на праве собственности или ином имущественном праве религиозной организации, туроператор соблюдает порядок совершения богослужений, других религиозных обрядов и церемоний и обеспечивает соблюдение представителем туроператора и туристами указанного порядка, а также требований к внешнему виду и поведению представителя туроператора и туристов в соответствии с внутренними установлениями религиозной организации. (Дополнение частью - Федеральный закон от 03.07.2019 № 170-ФЗ)\nРелигиозная организация и (или) организация, созданная религиозной организацией, вправе заключить с туроператором соглашение, определяющее условия организации посещения туристами объектов показа, принадлежащих на праве собственности или ином имущественном праве религиозной организации, включая условия размещения (проживания), питания туристов на территории религиозной организации с учетом требований, предусмотренных внутренними установлениями религиозной организации. (Дополнение частью - Федеральный закон от 03.07.2019 № 170-ФЗ)\nУслуги на объектах показа, принадлежащих на праве собственности или ином имущественном праве религиозной организации, оказывают экскурсоводы (гиды) или гиды-переводчики религиозной организации и (или) организации, созданной религиозной организацией, если иное не предусмотрено соглашением между религиозной организацией, организацией, созданной религиозной организацией, и туроператором. (Дополнение частью - Федеральный закон от 03.07.2019 № 170-ФЗ)\nЗаключивший договор о реализации туристского продукта гражданин, который был призван на военную службу по мобилизации в Вооруженные Силы Российской Федерации, либо который поступил на военную службу по контракту в период с 24 февраля 2022 года, либо который в период с 24 февраля 2022 года заключил контракт о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, или член его семьи вправе потребовать расторжения указанного договора и возврата денежной суммы, уплаченной по договору о реализации туристского продукта, в течение трех лет со дня заключения договора о реализации туристского продукта, а туроператор обязан возвратить указанную денежную сумму. (Дополнение частью - Федеральный закон от 13.06.2023 № 252-ФЗ) (В редакции Федерального закона от 25.12.2023 № 639-ФЗ)\nДенежная сумма, указанная в части пятнадцатой настоящей статьи, возвращается за счет собственных средств туроператора, которым был сформирован туристский продукт. В случае недостаточности собственных средств у туроператора денежная сумма может быть возвращена из денежных средств фонда персональной ответственности туроператора в порядке, установленном Правительством Российской Федерации в соответствии с частью первой статьи 11.8 настоящего Федерального закона. (Дополнение частью - Федеральный закон от 13.06.2023 № 252-ФЗ)\nДенежная сумма, указанная в части пятнадцатой настоящей статьи, возвращается туристу или члену его семьи в течение 10 дней со дня подачи требования о расторжении договора и возврате денежной суммы, уплаченной по договору о реализации туристского продукта, туроператору и (или) турагенту и представления необходимых подтверждающих документов, установленных Правительством Российской Федерации. (Дополнение частью - Федеральный закон от 13.06.2023 № 252-ФЗ)\nВ целях настоящей статьи под членами семьи понимаются лица, определенные в соответствии с пунктами 5 и 5.1 статьи 2 Федерального закона от 27 мая 1998 года № 76-ФЗ \"О статусе военнослужащих\". (Дополнение частью - Федеральный закон от 13.06.2023 № 252-ФЗ)\n(Статья в редакции Федерального закона от 05.02.2007 № 12-ФЗ)\n(Особенности применения статьи 10 - Федеральный закон от 13.06.2023 № 252-ФЗ)"],
["10.1","Особенности реализации туристского продукта турагентом","Глава IV. Особенности формирования, продвижения и реализации туристского продукта","2021-03-24","Статья 10.1. Особенности реализации туристского продукта турагентом\nНастоящая статья применяется к отношениям, возникающим между туристом и (или) иным заказчиком и турагентом, реализующим туристский продукт, сформированный туроператором, по договору о реализации туристского продукта. К таким отношениям применяются положения статьи 10 настоящего Федерального закона, если иное не установлено настоящей статьей.\nДоговор о реализации туристского продукта, заключаемый между туристом и (или) иным заказчиком и турагентом, наряду с существенными условиями, предусмотренными статьей 10 настоящего Федерального закона, должен также содержать следующие существенные условия:\nполное и (в случае, если имеется) сокращенное наименования, фамилия, имя, отчество (в случае, если имеется) руководителя, адрес места нахождения, основной государственный регистрационный номер юридического лица - в отношении турагента - юридического лица; (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nфамилия, имя, отчество (в случае, если имеется), адрес места жительства индивидуального предпринимателя, основной государственный регистрационный номер индивидуального предпринимателя - в отношении турагента - индивидуального предпринимателя; (Дополнение абзацем - Федеральный закон от 24.03.2021 № 48-ФЗ)\nреестровый номер турагента в реестре турагентов; (Дополнение абзацем - Федеральный закон от 24.03.2021 № 48-ФЗ)\nинформация о том, что лицом (исполнителем), оказывающим туристу и (или) иному заказчику услуги, входящие в туристский продукт, по договору о реализации туристского продукта, является туроператор, в том числе информация о способах связи с туроператором (номера телефонов, факсов, адрес сайта в информационно-телекоммуникационной сети \"Интернет\", адрес электронной почты);\nинформация о том, что турагент является исполнителем и несет предусмотренную законодательством Российской Федерации ответственность по договору о реализации туристского продукта в отношении обязанностей турагента;\nобязательство турагента о передаче денежных средств, полученных от туриста и (или) иного заказчика, туроператору, если иной порядок оплаты туристского продукта не предусмотрен договором между турагентом и туроператором;\nобязательство турагента по уведомлению туроператора, сформировавшего туристский продукт, о заключении договора о реализации туристского продукта;\nобязательство турагента по согласованию с туроператором, сформировавшим туристский продукт, условий путешествия (в том числе потребительских свойств туристского продукта) на основании запроса туриста и (или) иного заказчика, адресованного турагенту;\nсведения о порядке и сроках предъявления туристом и (или) иным заказчиком претензий к турагенту в случае нарушения турагентом обязательств по договору о реализации туристского продукта.\nЧасть. (Утратила силу - Федеральный закон от 04.06.2018 № 149-ФЗ)\nТурагент несет предусмотренную законодательством Российской Федерации ответственность перед туристом и (или) иным заказчиком за неисполнение или ненадлежащее исполнение своих обязанностей, предусмотренных договором о реализации туристского продукта.\n(Дополнение статьей - Федеральный закон от 05.02.2007 № 12-ФЗ) (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["10.2","Требования к договору фрахтования и иным договорам, заключаемым в целях организации перевозки туристов","Глава IV. Особенности формирования, продвижения и реализации туристского продукта","2016-03-02","Статья 10.2. Требования к договору фрахтования и иным договорам, заключаемым в целях организации перевозки туристов\nПри заключении между туроператором и фрахтовщиком или агентом фрахтовщика договора фрахтования воздушного судна либо части воздушного судна или иного договора в целях организации перевозки туристов для исполнения обязательств туроператора, связанных с реализацией туристского продукта, к существенным условиям такого договора относятся:\nпредоставление туроператором фрахтовщику или агенту фрахтовщика либо иному участнику договора, заключаемого в целях организации перевозки туристов, гарантий оплаты услуг по такому договору (банковской гарантии, договора счета эскроу или иного финансового документа в обеспечение оплаты услуг фрахтовщика);\nсумма банковской гарантии, сумма банковского вклада (депозита) или договора счета эскроу, обеспечивающего оплату услуг по договору фрахтования или иному договору, заключаемым в целях организации перевозки туристов;\nобязанность туроператора выдать туристу и (или) иному заказчику квитанцию (выписку из автоматизированной системы оформления воздушных перевозок), подтверждающую право туриста на перевозку по определенному маршруту, в порядке и в сроки, которые установлены настоящим Федеральным законом, с обязательным указанием фамилии туриста и других сведений на основании документа, удостоверяющего личность туриста и необходимого в соответствии с международным договором Российской Федерации или законодательством Российской Федерации для перевозки туриста;\nположения, гарантирующие осуществление фрахтовщиком перевозки туриста по маршруту, определенному договором фрахтования.\nУказанные требования в части обязанности туроператора выдать туристу и (или) иному заказчику проездной документ установленной формы распространяются также на туроператоров, заключающих договоры фрахтования других транспортных средств (морских и речных судов, железнодорожного транспорта общего пользования), иные договоры в целях организации перевозки туристов, и на туроператоров, приобретающих посадочные места на различных типах судов (воздушных, морских, речных) и на железнодорожном транспорте общего пользования.\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["10.3","Особенности обмена информацией в электронной форме между туроператором, турагентом и туристом и (или) иным заказчиком","Глава IV. Особенности формирования, продвижения и реализации туристского продукта","2022-05-28","Статья 10.3. Особенности обмена информацией в электронной форме между туроператором, турагентом и туристом и (или) иным заказчиком\n(Наименование в редакции Федерального закона от 28.05.2022 № 148-ФЗ)\nДля заключения договора о реализации туристского продукта турист и (или) иной заказчик могут передать туроператору, турагенту информацию в электронной форме (заявку о заключении договора о реализации туристского продукта и иные документы) путем ее размещения на официальном сайте туроператора, турагента в информационно-телекоммуникационной сети \"Интернет\". При этом указанный официальный сайт туроператора, турагента может использоваться в качестве информационной системы, обеспечивающей обмен информацией в электронной форме между туроператором, турагентом, являющимися операторами этой системы, и туристом и (или) иным заказчиком.\nТребования к использованию документов в электронной форме и порядок обмена информацией в электронной форме между туроператором, турагентом и туристом и (или) иным заказчиком при реализации туристского продукта устанавливаются Правительством Российской Федерации с соблюдением требований Федерального закона от 7 августа 2001 года № 115-ФЗ \"О противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма\", Федерального закона от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\" и Федерального закона от 27 июля 2006 года № 152-ФЗ \"О персональных данных\".\nДоговор о реализации туристского продукта, составленный в форме электронного документа, считается заключенным туристом и (или) иным заказчиком с момента оплаты туристом и (или) иным заказчиком туристского продукта, подтверждающей их согласие с условиями, содержащимися в предложенном туроператором, турагентом договоре о реализации туристского продукта.\nЧасть. (Утратила силу - Федеральный закон от 28.05.2022 № 148-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 28.05.2022 № 148-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 28.05.2022 № 148-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 28.05.2022 № 148-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 28.05.2022 № 148-ФЗ)\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["10.4","Единая информационная система электронных путевок. Электронная путевка","Глава IV. Особенности формирования, продвижения и реализации туристского продукта","2024-06-22","Статья 10.4. Единая информационная система электронных путевок. Электронная путевка\nЕдиная информационная система электронных путевок предназначена для обеспечения уполномоченного федерального органа исполнительной власти и федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного контроля (надзора) в области защиты прав потребителей, достоверными сведениями, содержащимися в договоре о реализации туристского продукта, и иными сведениями, подлежащими представлению туроператором в единую информационную систему электронных путевок, а также для обеспечения соответствующими сведениями заказчика, потребителей туристского продукта.\nОператор информационной системы определяется в соответствии с законодательством в области информации, информационных технологий и защиты информации.\nПравила функционирования единой информационной системы электронных путевок устанавливаются Правительством Российской Федерации. Указанными правилами определяются:\nпорядок и срок формирования электронной путевки;\nпорядок и срок направления турагентом туроператору, сформировавшему туристский продукт, уведомления о заключении договора о реализации туристского продукта;\nструктура электронной путевки;\nперечень и порядок представления туроператором сведений, содержащихся в договоре о реализации туристского продукта, и иных сведений, подлежащих представлению туроператором в единую информационную систему электронных путевок, в том числе сведений о туристе, об общей цене туристского продукта в рублях и о входящих в туристский продукт услугах по размещению туриста в стране (месте) временного пребывания, информации о средствах размещения, об условиях проживания (месте нахождения средства размещения, категории гостиницы) и питания, услугах по перевозке туриста в страну (место) временного пребывания и обратно, включая услуги по перевозке туриста в стране (месте) временного пребывания, а также об иных услугах; (В редакции Федерального закона от 22.06.2024 № 143-ФЗ)\nсостав сведений, содержащихся в единой информационной системе электронных путевок, требования к таким сведениям и к обеспечению доступа к таким сведениям, а также формы и порядок направления запросов о предоставлении таких сведений, в том числе с использованием информационно-телекоммуникационных сетей общего пользования, включая сеть \"Интернет\".\nТуроператор в порядке, установленном правилами функционирования единой информационной системы электронных путевок, передает в единую информационную систему электронных путевок сведения, содержащиеся в договоре о реализации туристского продукта, и иные сведения, подлежащие представлению туроператором в единую информационную систему электронных путевок, в срок до 15-го числа месяца, следующего за календарным месяцем, в котором был реализован туристский продукт, но не позднее даты начала путешествия в соответствии с договором о реализации туристского продукта. (В редакции Федерального закона от 22.06.2024 № 143-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 22.06.2024 № 143-ФЗ)\nВ случае заключения с туристом и (или) иным заказчиком туристского продукта договора в письменной форме, в том числе в форме электронного документа, основные данные о туристе или туристах и информация об их путешествии отражаются в виде двухмерного штрихового кода (QR-кода) в порядке, установленном уполномоченным федеральным органом исполнительной власти.\n(Дополнение статьей - Федеральный закон от 28.05.2022 № 148-ФЗ)"],
["11","Объединения туроператоров и турагентов","Глава V. Объединения туроператоров и турагентов, объединения туристов","2021-03-24","Статья 11. Объединения туроператоров и турагентов\nТуроператоры и турагенты в целях координации их предпринимательской деятельности, а также представления и защиты общих имущественных интересов могут создавать объединения в порядке, установленном законодательством Российской Федерации. Туроператоры, осуществляющие деятельность в сфере выездного туризма, обязаны быть членами объединения туроператоров в сфере выездного туризма, созданного в соответствии с настоящим Федеральным законом. Член объединения туроператоров в сфере выездного туризма до внесения сведений о нем в реестр туроператоров в соответствии с настоящим Федеральным законом не вправе осуществлять туроператорскую деятельность в сфере выездного туризма. (В редакции федеральных законов от 03.05.2012 № 47-ФЗ, от 24.03.2021 № 48-ФЗ)"],
["11.1","Объединение туроператоров в сфере выездного туризма","Глава V. Объединения туроператоров и турагентов, объединения туристов","2025-07-23","Статья 11.1. Объединение туроператоров в сфере выездного туризма\nОбъединение туроператоров в сфере выездного туризма является некоммерческой организацией, представляющей собой единое общероссийское объединение, которое основано на принципе обязательного членства юридических лиц, осуществляющих на территории Российской Федерации туроператорскую деятельность в сфере выездного туризма, и действует в целях оказания экстренной помощи туристам в соответствии с настоящим Федеральным законом.\nПорядок создания, деятельности, реорганизации и ликвидации данного объединения устанавливается в соответствии с законодательством Российской Федерации, предусмотренным в отношении ассоциаций (союзов), с учетом положений настоящего Федерального закона. Некоммерческая организация приобретает статус объединения туроператоров в сфере выездного туризма на основании решения Правительства Российской Федерации.\nОбъединение туроператоров в сфере выездного туризма является открытым для вступления новых членов.\nТребованием к членству туроператора в объединении туроператоров в сфере выездного туризма является уплата взносов в резервный фонд в сроки, установленные настоящим Федеральным законом, и в размере, определенном в соответствии с настоящим Федеральным законом. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nОснованием для прекращения членства туроператора в объединении туроператоров в сфере выездного туризма является:\nзаявление туроператора о выходе из членов данного объединения в случае прекращения туроператором деятельности в сфере выездного туризма;\nнеуплата взносов в резервный фонд в сроки, установленные настоящим Федеральным законом, и в размере, определенном в соответствии с настоящим Федеральным законом; (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nликвидация туроператора в соответствии с законодательством Российской Федерации;\nнеуплата взносов в фонд персональной ответственности туроператора в сроки, установленные настоящим Федеральным законом, и в размере, определенном в соответствии с настоящим Федеральным законом, а также непредставление сведений об общей цене туристского продукта в сфере выездного туризма за предыдущий календарный квартал и об общей цене туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий календарный квартал в сроки, установленные частью третьей статьи 11.6 настоящего Федерального закона.(Дополнение абзацем - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nУстановление иных требований к членству туроператора в объединении туроператоров в сфере выездного туризма, равно как и иных оснований для прекращения членства туроператора в данном объединении, не допускается. При прекращении членства туроператора взносы, уплаченные в резервный фонд, не возвращаются. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nВ случае прекращения членства туроператора в объединении туроператоров в сфере выездного туризма оно уведомляет об этом уполномоченный федеральный орган исполнительной власти в форме электронного документа, представляемого в порядке, установленном уполномоченным федеральным органом исполнительной власти.\nУказанная в статье 4.1 настоящего Федерального закона информация о туроператорах - членах объединения туроператоров в сфере выездного туризма, информация об изменении сведений о туроператоре, информация о туроператорах, исключенных из членов объединения туроператоров в сфере выездного туризма, об основаниях их исключения подлежит размещению на официальном сайте данного объединения в информационно-телекоммуникационной сети \"Интернет\" не позднее чем в течение одного дня после дня изменения соответствующих сведений о туроператоре либо дня принятия решения о приеме туроператора в члены объединения туроператоров в сфере выездного туризма или прекращении членства в данном объединении.\nОбъединение туроператоров в сфере выездного туризма для оказания экстренной помощи туристам при неисполнении обязательств по договору о реализации туристского продукта, формируемого туроператорами - членами данного объединения, формирует резервный фонд в соответствии с требованиями настоящего Федерального закона. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nГодовая бухгалтерская (финансовая) отчетность объединения туроператоров в сфере выездного туризма подлежит обязательному аудиту. Аудиторская организация и условия договора на проведение обязательного аудита годовой бухгалтерской (финансовой) отчетности объединения туроператоров в сфере выездного туризма утверждаются общим собранием членов объединения туроператоров в сфере выездного туризма или постоянно действующим коллегиальным органом управления, если учредительными документами данного объединения такое утверждение отнесено к его компетенции. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nГодовой отчет и годовая бухгалтерская (финансовая) отчетность объединения туроператоров в сфере выездного туризма вместе с аудиторским заключением о ней после их утверждения общим собранием членов данного объединения или постоянно действующим коллегиальным органом управления, если учредительными документами данного объединения такое утверждение отнесено к его компетенции, подлежат размещению на его официальном сайте в информационно-телекоммуникационной сети \"Интернет\". (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nОбъединением туроператоров в сфере выездного туризма разрабатываются правила профессиональной деятельности, обязательные для данного объединения и его членов и регулирующие в том числе порядок осуществления им и его членами функций, связанных с формированием и использованием резервного фонда в соответствии с настоящим Федеральным законом. Указанные правила профессиональной деятельности утверждаются уполномоченным федеральным органом исполнительной власти. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\n(Дополнение статьей - Федеральный закон от 03.05.2012 № 47-ФЗ)"],
["11.2","Полномочия объединения туроператоров в сфере выездного туризма","Глава V. Объединения туроператоров и турагентов, объединения туристов","2021-03-24","Статья 11.2. Полномочия объединения туроператоров в сфере выездного туризма\nПолномочиями объединения туроператоров в сфере выездного туризма являются:\nобеспечение в порядке, установленном Правительством Российской Федерации, оказания экстренной помощи туристам в случае неисполнения туроператором обязательств по договору о реализации туристского продукта в части неоказания туристу услуг по перевозке и (или) размещению полностью или частично;\nучет взносов в резервный фонд на основании содержащейся в реестре туроператоров информации о количестве туристов в сфере выездного туризма за предыдущий год; (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nучет взносов в фонд персональной ответственности туроператора на основании содержащейся в реестре туроператоров информации об общей цене туристского продукта в сфере выездного туризма за предыдущий год. (В редакции Федерального закона от 24.03.2021 № 48-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 24.03.2021 № 48-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 24.03.2021 № 48-ФЗ)\nОбъединение туроператоров в сфере выездного туризма обязано реализовывать в соответствии со статьей 11.5 настоящего Федерального закона право требования страховой выплаты или выплаты по банковской гарантии, а также право требования к туроператорам.\n(Дополнение статьей - Федеральный закон от 03.05.2012 № 47-ФЗ) (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["11.3","Имущество объединения туроператоров в сфере выездного туризма","Глава V. Объединения туроператоров и турагентов, объединения туристов","2024-12-13","Статья 11.3. Имущество объединения туроператоров в сфере выездного туризма\nИмущество объединения туроператоров в сфере выездного туризма образуется за счет:\nимущества, передаваемого данному объединению его учредителями в соответствии с учредительным договором объединения;\nвзносов, уплачиваемых в резервный фонд; (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nвзносов на финансирование расходов, связанных с текущей деятельностью данного объединения;\nдоходов, полученных от размещения средств резервного фонда; (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nденежных средств, полученных от реализации установленного статьей 11.5 настоящего Федерального закона права требования страховой выплаты или выплаты по банковской гарантии;\nдобровольных взносов.\nИмущество данного объединения может использоваться исключительно в целях, ради достижения которых оно создано.\nСредства резервного фонда размещаются на его отдельном банковском счете, и по ним ведется отдельный учет. На средства резервного фонда не может быть обращено взыскание по обязательствам объединения туроператоров в сфере выездного туризма, если такие обязательства не связаны с финансированием расходов на оказание экстренной помощи туристам в соответствии с настоящим Федеральным законом. Допускается расходование средств резервного фонда на уплату обязательных платежей, связанных с получением дохода от размещения средств резервного фонда, и плату за ведение банковского счета, на котором размещаются средства резервного фонда. (В редакции федеральных законов от 02.03.2016 № 49-ФЗ; от 04.06.2018 № 149-ФЗ)\nДля финансирования расходов, связанных с текущей деятельностью объединения туроператоров в сфере выездного туризма, члены указанного объединения уплачивают взносы в размере, пропорциональном объему общей цены туристского продукта в сфере выездного туризма за предыдущий год, но не более чем 0,05 процента общей цены туристского продукта в сфере выездного туризма по данным отчетности, указанной в статье 17.7 настоящего Федерального закона, за предыдущий год. Размер взносов и порядок их уплаты определяются общим собранием членов указанного объединения при утверждении или изменении бюджета на очередной финансовый год. Средства, предназначенные для финансирования расходов, связанных с деятельностью объединения туроператоров в сфере выездного туризма, обособляются от средств резервного фонда и перечисляются на иные банковские счета указанного объединения. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nРазмещение средств резервного фонда объединения туроператоров в сфере выездного туризма допускается в рублях и (или) иностранной валюте на счетах или депозитах в кредитных организациях. Кредитные организации, в которых допускается размещение средств резервного фонда, должны соответствовать требованиям к уровню кредитного рейтинга по национальной рейтинговой шкале, установленным Правительством Российской Федерации. Правительство Российской Федерации вправе устанавливать дифференцированные требования к уровню кредитного рейтинга и определять случаи, при которых требования к уровню кредитного рейтинга не применяются. Правительством Российской Федерации могут быть определены дополнительные объекты инвестирования средств резервного фонда, а также установлены требования к инвестированию денежных средств в соответствующие объекты и условия их инвестирования. (В редакции Федерального закона от 13.12.2024 № 475-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 02.03.2016 № 49-ФЗ)\n(Дополнение статьей - Федеральный закон от 03.05.2012 № 47-ФЗ)"],
["11.4","Резервный фонд объединения туроператоров в сфере выездного туризма","Глава V. Объединения туроператоров и турагентов, объединения туристов","2021-07-02","Статья 11.4. Резервный фонд объединения туроператоров в сфере выездного туризма\n(Наименование в редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nДля финансирования расходов на оказание экстренной помощи туристам объединение туроператоров в сфере выездного туризма формирует резервный фонд в соответствии с требованиями настоящего Федерального закона. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nРезервный фонд является обособленным имуществом, принадлежащим объединению туроператоров в сфере выездного туризма на праве собственности. Резервный фонд формируется за счет взносов туроператоров, осуществляющих деятельность в сфере выездного туризма. Указанные взносы перечисляются в денежной форме в следующих размерах:\n50 тысяч рублей - для туроператоров, у которых показатель количества туристов в сфере выездного туризма за предыдущий год составил не более чем 10 тысяч туристов включительно, а общая цена туристского продукта в сфере выездного туризма за предыдущий год составила не более чем 40 миллионов рублей; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n100 тысяч рублей - для туроператоров, у которых показатель количества туристов в сфере выездного туризма за предыдущий год составляет не более чем 100 тысяч туристов включительно, за исключением туроператоров, указанных в абзаце втором настоящей части; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n300 тысяч рублей - для туроператоров, у которых показатель количества туристов в сфере выездного туризма за предыдущий год составляет более чем 100 тысяч туристов, но не более чем 500 тысяч туристов включительно; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n500 тысяч рублей - для туроператоров, у которых показатель количества туристов в сфере выездного туризма за предыдущий год составляет более чем 500 тысяч туристов. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n(Часть в редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nСоответствующий взнос должен перечисляться в резервный фонд ежегодно в течение 15 дней с даты опубликования бухгалтерской (финансовой) отчетности, или с даты ее представления в целях формирования государственного информационного ресурса бухгалтерской (финансовой) отчетности, предусмотренного статьей 18 Федерального закона от 6 декабря 2011 года № 402-ФЗ \"О бухгалтерском учете\" (далее - государственный информационный ресурс бухгалтерской (финансовой) отчетности), или с даты ее представления в уполномоченный федеральный орган исполнительной власти, но не позднее чем 15 апреля текущего года. (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 02.07.2021 № 352-ФЗ)\nЗачислению в резервный фонд подлежат также доходы, полученные от размещения средств резервного фонда. (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ)\nПравительство Российской Федерации вправе уменьшить размер взноса в резервный фонд объединения туроператоров в сфере выездного туризма на очередной финансовый год в случае отсутствия выплат из резервного фонда за предшествующий год. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nНе допускается освобождение члена объединения туроператоров в сфере выездного туризма от обязанности внесения взносов в резервный фонд, в том числе путем зачета его требований к объединению туроператоров в сфере выездного туризма. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nТуроператор, осуществляющий деятельность в сфере выездного туризма, а также туроператор или юридическое лицо, ранее не осуществлявшие туроператорской деятельности в сфере выездного туризма, при вступлении в члены объединения туроператоров в сфере выездного туризма уплачивают вступительный взнос в резервный фонд в размере 100 тысяч рублей. Туроператор вправе отнести затраты, связанные с уплатой взносов в резервный фонд, на себестоимость туристского продукта. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nПорядок и условия финансирования расходов на оказание экстренной помощи туристам из резервного фонда определяются Правительством Российской Федерации. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nРазмер выплаты из резервного фонда определяется исходя из фактических расходов на оказание экстренной помощи туристам в соответствии с настоящим Федеральным законом. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nСредства резервного фонда предназначены исключительно для оказания экстренной помощи туристам, находящимся за пределами территории Российской Федерации. Расходование средств резервного фонда на цели, не предусмотренные настоящей статьей, в том числе на выплату или возврат взносов членам объединения туроператоров в сфере выездного туризма, не допускается, за исключением уплаты обязательных платежей, связанных с получением дохода от размещения средств резервного фонда, и платы за ведение банковского счета, на котором размещаются средства резервного фонда. Прекращение членства туроператора в объединении туроператоров в сфере выездного туризма не является основанием для прекращения расходования средств резервного фонда на цели, предусмотренные настоящей статьей. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n(Дополнение статьей - Федеральный закон от 03.05.2012 № 47-ФЗ)"],
["11.5","Возмещение расходов резервного фонда объединения туроператоров в сфере выездного туризма","Глава V. Объединения туроператоров и турагентов, объединения туристов","2016-03-02","Статья 11.5. Возмещение расходов резервного фонда объединения туроператоров в сфере выездного туризма\nВ пределах суммы расходов, понесенных объединением туроператоров в сфере выездного туризма в соответствии с настоящим Федеральным законом на оказание экстренной помощи туристу, к объединению туроператоров в сфере выездного туризма переходит принадлежащее туристу право требования о выплате страхового возмещения по договору страхования ответственности туроператора к страховщику либо об уплате денежной суммы по банковской гарантии. К отношениям между данным объединением и указанными в статье 17.4 настоящего Федерального закона страховщиком или гарантом по поводу возмещения расходов резервного фонда по аналогии применяются правила, установленные настоящим Федеральным законом для отношений между туристом и (или) иным заказчиком и страховщиком или гарантом по договору страхования ответственности туроператора либо по банковской гарантии. Соответствующие положения применяются постольку, поскольку иное не предусмотрено федеральным законом и не вытекает из существа таких отношений.\nСумма расходов, понесенных объединением туроператоров в сфере выездного туризма в соответствии с настоящим Федеральным законом на оказание экстренной помощи туристу, подлежит взысканию с туроператора в порядке регресса по иску объединения туроператоров в сфере выездного туризма.\nОбъединение туроператоров в сфере выездного туризма предъявляет регрессное требование к учредителям, участникам туроператора, руководителю туроператора и (или) членам органов управления туроператора в размере расходов, понесенных данным объединением в соответствии с настоящим Федеральным законом на оказание экстренной помощи туристу, в случае, если неисполнение таким туроператором обязательств по договору о реализации туристского продукта вызвано умышленными противоправными действиями (бездействием) соответственно учредителей, участников туроператора, руководителя туроператора, членов указанных органов управления.\n(Дополнение статьей - Федеральный закон от 03.05.2012 № 47-ФЗ) (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["11.6","Фонд персональной ответственности туроператора в сфере выездного туризма","Глава V. Объединения туроператоров и турагентов, объединения туристов","2025-07-23","Статья 11.6. Фонд персональной ответственности туроператора в сфере выездного туризма\nДля выплаты денежных средств, причитающихся туристам и (или) иным заказчикам в целях возмещения реального ущерба, возникшего в результате неисполнения туроператором своих обязательств по договору о реализации туристского продукта в сфере выездного туризма в связи с прекращением туроператорской деятельности по причине невозможности исполнения всех обязательств по договорам о реализации туристского продукта, объединение туроператоров в сфере выездного туризма формирует для каждого члена объединения туроператоров в сфере выездного туризма фонд персональной ответственности туроператора в соответствии с требованиями настоящего Федерального закона. Особенности формирования и использования фонда персональной ответственности туроператора устанавливаются статьей 11.8 настоящего Федерального закона. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 01.04.2020 № 98-ФЗ, от 13.06.2023 № 252-ФЗ)\nФонд персональной ответственности туроператора формируется за счет ежегодного взноса туроператора в сфере выездного туризма.\nРазмер ежегодного взноса туроператора в фонд персональной ответственности туроператора равен одному проценту общей цены туристского продукта в сфере выездного туризма за предыдущий год, рассчитанной без учета общей цены туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за исключением случаев, предусмотренных частью четвертой настоящей статьи. Перечисление ежегодного взноса туроператора в фонд персональной ответственности туроператора производится равными долями не позднее 15-го числа каждого месяца, следующего за истекшим календарным кварталом, за исключением случаев, предусмотренных частью четвертой настоящей статьи. По окончании каждого календарного квартала не позднее 15-го числа месяца, следующего за истекшим календарным кварталом, туроператор направляет в объединение туроператоров в сфере выездного туризма сведения об общей цене туристского продукта в сфере выездного туризма за предыдущий календарный квартал, об общей цене туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий календарный квартал. (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nЕсли общая цена туристского продукта в сфере выездного туризма за первый квартал календарного года превышает 25 процентов общей цены туристского продукта в сфере выездного туризма за предыдущий год, размер ежегодного взноса туроператора в фонд персональной ответственности туроператора равен одному проценту общей цены туристского продукта в сфере выездного туризма в текущем году, рассчитанной без учета общей цены туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, в текущем году. Туроператор по окончании каждого календарного квартала текущего года перечисляет квартальный взнос в фонд персональной ответственности туроператора не позднее 15-го числа месяца, следующего за истекшим календарным кварталом, в размере одного процента общей цены туристского продукта в сфере выездного туризма за предыдущий календарный квартал, рассчитанной без учета общей цены туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий календарный квартал, до конца текущего года. (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nТуроператор вправе увеличивать размер ежегодного взноса в фонд персональной ответственности туроператора, а также сразу сформировать фонд персональной ответственности туроператора максимального размера, который составляет не менее семи процентов от общей цены туристского продукта в сфере выездного туризма за предыдущий год, рассчитанной без учета общей цены туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий год. (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nЕсли размер фонда персональной ответственности туроператора становится максимальным, финансовое обеспечение ответственности туроператора в сфере выездного туризма не требуется и перечисление взносов в фонд персональной ответственности туроператора прекращается. Решение об освобождении туроператора от финансового обеспечения ответственности туроператора в сфере выездного туризма и уплаты взносов в фонд персональной ответственности туроператора принимается объединением туроператоров в сфере выездного туризма по согласованию с уполномоченным федеральным органом исполнительной власти на основании заявления туроператора в порядке, установленном уполномоченным федеральным органом исполнительной власти. Освобождение туроператора, осуществляющего деятельность в сфере выездного туризма, от финансового обеспечения ответственности туроператора в сфере выездного туризма и уплаты взносов в фонд персональной ответственности туроператора осуществляется на срок, предусмотренный статьей 11.7 настоящего Федерального закона. Такое освобождение туроператора, осуществляющего деятельность в сфере выездного туризма, не влечет за собой прекращение имеющихся у него договора или договоров страхования ответственности туроператора и (или) договора или договоров о предоставлении банковской гарантии, заключенных до достижения максимального размера фонда персональной ответственности туроператора с организацией или организациями, предоставившими финансовое обеспечение ответственности туроператора в сфере выездного туризма. В этом случае возмещение реального ущерба туристам и (или) иным заказчикам из денежных средств фонда персональной ответственности туроператора осуществляется в соответствии с частью одиннадцатой настоящей статьи при условии, что имеющегося финансового обеспечения ответственности туроператора в сфере выездного туризма недостаточно для возмещения такого ущерба. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nТуроператоры, которые не осуществляли в предыдущем году деятельность в сфере выездного туризма, и юридические лица, которые намерены осуществлять туроператорскую деятельность в сфере выездного туризма и в текущем году не осуществляли такую деятельность, должны перечислить взнос в фонд персональной ответственности туроператора до начала осуществления деятельности в сфере выездного туризма в размере 100 тысяч рублей.\nТуроператоры, указанные в части седьмой настоящей статьи, по окончании каждого календарного квартала первого календарного года перечисляют квартальный взнос в фонд персональной ответственности туроператора не позднее 15-го числа месяца, следующего за истекшим календарным кварталом, в размере одного процента от общей цены туристского продукта в сфере выездного туризма, реализованного туроператором в прошедшем календарном квартале, рассчитанной без учета общей цены туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, реализованного туроператором за предыдущий календарный квартал. (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nДо достижения максимального размера фонда персональной ответственности туроператора денежные средства фонда персональной ответственности туроператора расходуются объединением туроператоров в сфере выездного туризма на возмещение реального ущерба туристам и (или) иным заказчикам, если денежных средств страховщика или гаранта для выплаты страхового возмещения по договору страхования ответственности туроператора или уплаты денежной суммы по банковской гарантии оказалось недостаточно.\nПри достижении максимального размера фонда персональной ответственности туроператора денежные средства фонда персональной ответственности туроператора расходуются объединением туроператоров в сфере выездного туризма на возмещение реального ущерба туристам и (или) иным заказчикам, возникшего в результате неисполнения туроператором своих обязательств по договору о реализации туристского продукта в сфере выездного туризма в связи с прекращением туроператорской деятельности по причине невозможности исполнения всех обязательств по договорам о реализации туристского продукта. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nПорядок и условия возмещения реального ущерба туристам и (или) иным заказчикам из денежных средств фонда персональной ответственности туроператора устанавливаются Правительством Российской Федерации.\nРасходование денежных средств фонда персональной ответственности туроператора на цели, не предусмотренные настоящей статьей, не допускается, за исключением уплаты обязательных платежей, связанных с получением дохода от размещения денежных средств фонда персональной ответственности туроператора, платы за ведение банковских счетов, на которых размещаются денежные средства фондов персональной ответственности туроператоров, и административно-управленческих расходов, связанных с ведением отдельного учета средств фондов персональной ответственности туроператоров. Такими административно-управленческими расходами являются, в частности, оплата аренды помещений, выплата заработной платы работникам объединения туроператоров в сфере выездного туризма, расходы на услуги связи. Использование объединением туроператоров в сфере выездного туризма в текущем календарном году денежных средств фонда персональной ответственности туроператора на административно-управленческие расходы, связанные с ведением отдельного учета денежных средств фондов персональной ответственности туроператоров, допускается в пределах доходов, получаемых от размещения таких средств, но не более одного процента ежегодного взноса туроператора в фонд персональной ответственности туроператора в сфере выездного туризма, подлежащего уплате в текущем календарном году и перечисляемого туроператором до достижения максимального размера фонда персональной ответственности туроператора в сфере выездного туризма. После достижения максимального размера фонда персональной ответственности туроператора в указанных целях учитывается последний ежегодный взнос туроператора, перечисленный туроператором до достижения максимального размера фонда персональной ответственности туроператора в сфере выездного туризма. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nТуроператор вправе относить затраты, связанные с уплатой взносов в фонд персональной ответственности туроператора, на себестоимость туристского продукта.\nДенежные средства фондов персональной ответственности туроператоров размещаются на отдельных банковских счетах объединения туроператоров в сфере выездного туризма, и по ним объединением туроператоров в сфере выездного туризма ведется отдельный учет.\nРазмещение денежных средств фонда персональной ответственности туроператора допускается в рублях и (или) иностранной валюте на счетах или депозитах кредитных организаций. Кредитные организации, в которых допускается размещение средств фонда персональной ответственности туроператора, должны соответствовать требованиям к уровню кредитного рейтинга по национальной рейтинговой шкале, установленным Правительством Российской Федерации. Правительство Российской Федерации вправе устанавливать дифференцированные требования к уровню кредитного рейтинга и определять случаи, при которых требования к уровню кредитного рейтинга не применяются. (В редакции Федерального закона от 13.12.2024 № 475-ФЗ)\nДоходы, полученные от размещения денежных средств фонда персональной ответственности конкретного туроператора, подлежат зачислению в фонд персональной ответственности такого туроператора.\nПри прекращении туроператором деятельности в сфере выездного туризма денежные средства фонда персональной ответственности такого туроператора подлежат возврату туроператору при условии выполнения им всех обязательств перед туристами по заключенным договорам о реализации туристского продукта в сфере выездного туризма.\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["11.7","Срок освобождения туроператора, осуществляющего деятельность в сфере выездного туризма, от финансового обеспечения ответственности туроператора в сфере выездного туризма и уплаты взносов в фонд персональной ответственности туроператора и порядок его продления","Глава V. Объединения туроператоров и турагентов, объединения туристов","2025-07-23","Статья 11.7. Срок освобождения туроператора, осуществляющего деятельность в сфере выездного туризма, от финансового обеспечения ответственности туроператора в сфере выездного туризма и уплаты взносов в фонд персональной ответственности туроператора и порядок его продления\nВ случае принятия решения, предусмотренного частью шестой статьи 11.6 настоящего Федерального закона, туроператор, осуществляющий деятельность в сфере выездного туризма, освобождается от финансового обеспечения ответственности туроператора в сфере выездного туризма и уплаты взносов в фонд персональной ответственности туроператора до 1 апреля следующего календарного года.\nДля продления срока, предусмотренного частью первой настоящей статьи, туроператор, осуществляющий деятельность в сфере выездного туризма, обязан за один месяц до истечения этого срока (до 1 марта) представить в уполномоченный федеральный орган исполнительной власти сведения об общей цене туристского продукта в сфере выездного туризма за предыдущий календарный год, об общей цене туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий календарный год и о размере фонда персональной ответственности туроператора на дату представления таких сведений, а в объединение туроператоров в сфере выездного туризма заявление о продлении этого срока. (В редакции Федерального закона от 23.07.2025 № 238-ФЗ)\nЗаявление о продлении срока, предусмотренного частью первой настоящей статьи, составляется в письменной форме, удостоверяется подписью руководителя туроператора, осуществляющего деятельность в сфере выездного туризма, или уполномоченного им лица и печатью данного туроператора (при ее наличии). В заявлении указываются следующие сведения:\nполное наименование туроператора в соответствии с учредительным документом;\nреестровый номер туроператора в едином федеральном реестре туроператоров;\nразмер фонда персональной ответственности туроператора на дату подачи заявления;\nобщая цена туристского продукта в сфере выездного туризма за предыдущий календарный год;\nобщая цена туристского продукта, предусмотренного частью десятой статьи 17.2-1 настоящего Федерального закона, за предыдущий календарный год. (Дополнение абзацем - Федеральный закон от 23.07.2025 № 238-ФЗ)\nОбъединение туроператоров в сфере выездного туризма по согласованию с уполномоченным федеральным органом исполнительной власти принимает решение о продлении срока, предусмотренного частью первой настоящей статьи, до 1 апреля следующего года либо об отказе в таком продлении.\nОснованиями для отказа в продлении срока, предусмотренного частью первой настоящей статьи, являются:\nнесоответствие размера фонда персональной ответственности туроператора максимальному размеру этого фонда, предусмотренному частью пятой статьи 11.6 настоящего Федерального закона;\nотсутствие в заявлении туроператора о продлении срока каких-либо сведений, указанных в части третьей настоящей статьи.\nВ случае отказа в продлении срока, предусмотренного частью первой настоящей статьи, либо в случае, если не подано заявление о его продлении, туроператор, осуществляющий деятельность в сфере выездного туризма, обязан до истечения этого срока (до 1 апреля) получить финансовое обеспечение ответственности туроператора в сфере выездного туризма в соответствии с настоящим Федеральным законом, представить сведения об этом в уполномоченный федеральный орган исполнительной власти и возобновить уплату взносов в фонд персональной ответственности туроператора в соответствии с частями третьей, четвертой и пятой статьи 11.6 настоящего Федерального закона.\nЕсли отказ в продлении срока, предусмотренного частью первой настоящей статьи, связан с недостижением максимального размера фонда персональной ответственности туроператора, вместо получения финансового обеспечения ответственности туроператора в сфере выездного туризма и уплаты взносов в фонд персональной ответственности туроператора туроператор в течение пяти рабочих дней со дня получения решения об отказе в продлении этого срока может перечислить в фонд персональной ответственности туроператора денежные средства в размере, необходимом для достижения его максимального размера, и повторно подать заявление о продлении срока.\nЕсли отказ в продлении срока, предусмотренного частью первой настоящей статьи, связан с отсутствием в заявлении о продлении этого срока каких-либо сведений, указанных в части третьей настоящей статьи, туроператор в течение пяти рабочих дней со дня получения решения об отказе в продлении срока может повторно подать заявление о продлении срока с указанием всех необходимых сведений.\n(Дополнение статьей - Федеральный закон от 04.06.2018 № 149-ФЗ)"],
["11.8","Особенности формирования и использования фонда персональной ответственности туроператора","Глава V. Объединения туроператоров и турагентов, объединения туристов","2023-06-13","Статья 11.8. Особенности формирования и использования фонда персональной ответственности туроператора\n(Наименование в редакции Федерального закона от 13.06.2023 № 252-ФЗ)\nВ случае принятия иностранным государством решения об ограничении въезда туристов в страну (место) временного пребывания или возникновения обстоятельств, свидетельствующих о возникновении в стране (месте) временного пребывания туристов угрозы безопасности их жизни и здоровья, а равно опасности причинения вреда их имуществу, указанных в статье 14 настоящего Федерального закона, а также в случаях, предусмотренных частями пятнадцатой - восемнадцатой статьи 10 настоящего Федерального закона, Правительством Российской Федерации может быть принято решение о возврате туристам и (или) иным заказчикам уплаченных ими за туристский продукт денежных сумм из средств фонда персональной ответственности туроператора. При этом в случае принятия Правительством Российской Федерации такого решения при расторжении договора о реализации туристского продукта, заключенного туроператором или турагентом с туристом и (или) иным заказчиком, до начала путешествия туристу и (или) иному заказчику возвращается денежная сумма, равная общей цене туристского продукта, а после начала путешествия - часть указанной общей цены в размере, пропорциональном стоимости не оказанных туристу услуг. (В редакции федеральных законов от 08.06.2020 № 166-ФЗ, от 13.06.2023 № 252-ФЗ)\nВ случае, если Правительством Российской Федерации принято решение, указанное в части первой настоящей статьи, до достижения максимального размера фонда персональной ответственности туроператора денежные средства фонда персональной ответственности туроператора расходуются объединением туроператоров в сфере выездного туризма на возврат туристам и (или) иным заказчикам уплаченных ими за туристский продукт денежных сумм.\nВ случае, если Правительством Российской Федерации принято решение, указанное в части первой настоящей статьи, при достижении максимального размера фонда персональной ответственности туроператора денежные средства фонда персональной ответственности туроператора расходуются объединением туроператоров в сфере выездного туризма на возврат туристам и (или) иным заказчикам уплаченных ими за туристский продукт денежных сумм.\nВ случае возникновения обстоятельств или принятия иностранным государством решения, указанных в части первой настоящей статьи, Правительство Российской Федерации вправе принять решения:\nоб изменении сроков перечисления ежегодного взноса туроператора, осуществляющего деятельность в сфере выездного туризма, в фонд персональной ответственности туроператора;\nоб уменьшении размера ежегодного взноса туроператора, осуществляющего деятельность в сфере выездного туризма, в фонд персональной ответственности туроператора.\n(Часть в редакции Федерального закона от 08.06.2020 № 166-ФЗ)\nПорядок и условия возврата туристам и (или) иным заказчикам уплаченных ими за туристский продукт денежных сумм из денежных средств фонда персональной ответственности туроператора устанавливаются Правительством Российской Федерации.\n(Дополнение статьей - Федеральный закон от 01.04.2020 № 98-ФЗ)"],
["12","Объединения туристов","Глава V. Объединения туроператоров и турагентов, объединения туристов","","Статья 12. Объединения туристов\nТуристы в целях реализации права на отдых, свободу передвижения и иных прав при совершении путешествий на основе общности интересов могут создавать общественные объединения в порядке, установленном законодательством Российской Федерации.\nДеятельность объединения туристов может быть направлена на организацию и содействие развитию самодеятельного туризма, просвещение населения в сфере туризма, защиту прав и интересов туристов, формирование общественного мнения о деятельности организаций туристской индустрии и решение иных задач."],
["13","Туристские ресурсы Российской Федерации","Глава VI. Туристские ресурсы Российской Федерации","2008-12-30","Статья 13. Туристские ресурсы Российской Федерации\nКлассификация и оценка туристских ресурсов Российской Федерации, режим их охраны, порядок сохранения целостности туристских ресурсов Российской Федерации и меры по их восстановлению, порядок использования туристских ресурсов Российской Федерации с учетом предельно допустимых нагрузок на окружающую среду определяются в соответствии с законодательством Российской Федерации. (В редакции Федерального закона от 30.12.2008 № 309-ФЗ)"],
["14","Обеспечение безопасности туризма","Глава VII. Безопасность туризма","2025-07-23","Статья 14. Обеспечение безопасности туризма\nПод безопасностью туризма понимаются безопасность туристов (экскурсантов), сохранность их имущества, а также ненанесение ущерба при совершении путешествий окружающей среде, материальным и духовным ценностям общества, безопасности государства.\nУполномоченный федеральный орган исполнительной власти:\nинформирует туроператоров, турагентов и туристов (экскурсантов) об угрозе безопасности туристов (экскурсантов) в стране (месте) временного пребывания, в том числе путем опубликования соответствующих сообщений в государственных средствах массовой информации. Указанное опубликование осуществляется в порядке, предусмотренном законодательством Российской Федерации о средствах массовой информации для опубликования обязательных сообщений;\nустанавливает совместно с федеральным органом исполнительной власти, уполномоченным Правительством Российской Федерации в сфере организации отдыха и оздоровления детей, общие требования к организации и проведению в природной среде следующих мероприятий с участием детей, являющихся членами организованной группы несовершеннолетних туристов: прохождения туристских маршрутов, других маршрутов передвижения, походов, экспедиций, слетов и иных аналогичных мероприятий, а также указанных мероприятий с участием организованных групп детей, проводимых организациями, осуществляющими образовательную деятельность, и организациями отдыха детей и их оздоровления, и к порядку уведомления уполномоченных органов государственной власти о месте, сроках и длительности проведения таких мероприятий. (В редакции Федерального закона от 16.10.2019 № 336-ФЗ)\n(Часть в редакции Федерального закона от 28.12.2016 № 465-ФЗ)\nВ случае возникновения обстоятельств, свидетельствующих о возникновении в стране (месте) временного пребывания туристов (экскурсантов) угрозы безопасности их жизни и здоровья, а равно опасности причинения вреда их имуществу, турист (экскурсант) и (или) туроператор (турагент) вправе потребовать в судебном порядке расторжения договора о реализации туристского продукта или его изменения.\nНаличие указанных обстоятельств подтверждается соответствующими решениями (рекомендациями) федеральных органов государственной власти, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, принимаемыми в соответствии с федеральными законами. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nПри расторжении до начала путешествия договора о реализации туристского продукта в связи с наступлением обстоятельств, указанных в настоящей статье, туристу и (или) иному заказчику возвращается денежная сумма, равная общей цене туристского продукта, а после начала путешествия - ее часть в размере, пропорциональном стоимости не оказанных туристу услуг.\nПри заключении договора о реализации туристского продукта туроператор, турагент обязаны представить туристу и (или) иному заказчику достоверную информацию:\nо правилах въезда в страну (место) временного пребывания и выезда из страны (места) временного пребывания, включая сведения о необходимости наличия визы для въезда в страну и (или) выезда из страны временного пребывания;\nоб основных документах, необходимых для въезда в страну (место) временного пребывания и выезда из страны (места) временного пребывания;\nо необходимости самостоятельной оплаты туристом медицинской помощи в экстренной и неотложной формах в стране временного пребывания, о возвращении тела (останков) за счет лиц, заинтересованных в возвращении тела (останков), в случае отсутствия у туриста договора добровольного страхования (страхового полиса), о требованиях законодательства страны временного пребывания к условиям страхования в случае наличия таких требований; (Дополнение абзацем - Федеральный закон от 29.06.2015 № 155-ФЗ)\nоб условиях договора добровольного страхования, о страховщике, об организациях, осуществляющих в соответствии с договором, заключенным со страховщиком, организацию оказания медицинской помощи в экстренной и неотложной формах в стране временного пребывания и ее оплату, возвращения тела (останков), а также о порядке обращения туриста в связи с наступлением страхового случая (о месте нахождения, номерах контактных телефонов страховщика, иных организаций), если договор добровольного страхования заключается с туристом туроператором, турагентом от имени страховщика; (Дополнение абзацем - Федеральный закон от 29.06.2015 № 155-ФЗ)\nоб опасностях, с которыми турист (экскурсант) может встретиться при совершении путешествия;\nо таможенных, пограничных, медицинских, санитарно-эпидемиологических и иных правилах (в объеме, необходимом для совершения путешествия);\nо месте нахождения, почтовых адресах и номерах контактных телефонов органов государственной власти Российской Федерации, дипломатических представительств и консульских учреждений Российской Федерации, находящихся в стране (месте) временного пребывания, в которые турист (экскурсант) может обратиться в случае возникновения в стране (месте) временного пребывания чрезвычайных ситуаций или иных обстоятельств, угрожающих безопасности его жизни и здоровья, а также в случаях возникновения опасности причинения вреда имуществу туриста (экскурсанта);\nоб адресе (месте пребывания) и номере контактного телефона в стране (месте) временного пребывания руководителя группы несовершеннолетних туристов (экскурсантов) в случае, если туристский продукт включает в себя организованный выезд группы несовершеннолетних туристов (экскурсантов) без сопровождения родителей, усыновителей, опекунов или попечителей;\nо национальных и религиозных особенностях страны (места) временного пребывания;\nо порядке обращения в объединение туроператоров в сфере выездного туризма для получения экстренной помощи; (Дополнение абзацем - Федеральный закон от 03.05.2012 № 47-ФЗ)\nоб иных особенностях путешествия.\nТуристы (экскурсанты), предполагающие совершить путешествие в страну (место) временного пребывания, в которой они могут подвергнуться повышенному риску инфекционных заболеваний, обязаны проходить профилактику в соответствии с международными медицинскими требованиями.\nТуроператоры, турагенты, организации, индивидуальные предприниматели, физические лица, применяющие специальный налоговый режим \"Налог на профессиональный доход\" в соответствии с Федеральным законом от 27 ноября 2018 года № 422-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Налог на профессиональный доход\" (далее - физические лица, применяющие специальный налоговый режим), которые осуществляют экскурсионное обслуживание, обязаны пользоваться услугами инструкторов-проводников, если организуемые ими путешествия связаны с прохождением туристами (экскурсантами) маршрутов, относящихся к видам туристских маршрутов, требующих специального сопровождения, установленным в соответствии с настоящим Федеральным законом. (В редакции федеральных законов от 20.04.2021 № 93-ФЗ, от 23.03.2024 № 63-ФЗ, от 23.07.2025 № 260-ФЗ)\nТуроператоры, турагенты, организации, индивидуальные предприниматели, физические лица, применяющие специальный налоговый режим, которые осуществляют экскурсионное обслуживание, незамедлительно обязаны информировать уполномоченный федеральный орган исполнительной власти, органы исполнительной власти субъектов Российской Федерации, органы местного самоуправления, специализированные службы по обеспечению безопасности туризма и заинтересованных лиц о чрезвычайных происшествиях, произошедших с туристами (экскурсантами) при прохождении маршрутов, относящихся к видам туристских маршрутов, требующих специального сопровождения, установленным в соответствии с настоящим Федеральным законом. (В редакции федеральных законов от 20.04.2021 № 93-ФЗ, от 23.03.2024 № 63-ФЗ)\nТуроператоры, турагенты, организации, индивидуальные предприниматели, физические лица, применяющие специальный налоговый режим, которые осуществляют экскурсионное обслуживание, в случаях и порядке, которые определены частью второй настоящей статьи, обязаны соблюдать установленные требования к туристским маршрутам и порядку организации их прохождения несовершеннолетними туристами, являющимися членами организованной группы несовершеннолетних туристов, а также порядок уведомления уполномоченных органов государственной власти о месте, сроках и длительности прохождения таких маршрутов. (Дополнение частью - Федеральный закон от 28.12.2016 № 465-ФЗ) (В редакции Федерального закона от 20.04.2021 № 93-ФЗ)\n(Статья в редакции Федерального закона от 05.02.2007 № 12-ФЗ)"],
["15","Специализированные службы по обеспечению безопасности туристов","Глава VII. Безопасность туризма","","Статья 15. Специализированные службы по обеспечению безопасности туристов\nОказание необходимой помощи туристам, терпящим бедствие в пределах территории Российской Федерации, осуществляется специализированными службами, определяемыми Правительством Российской Федерации."],
["16","Защита интересов российских туристов за пределами Российской Федерации в случаях возникновения чрезвычайных ситуаций","Глава VII. Безопасность туризма","","Статья 16. Защита интересов российских туристов за пределами Российской Федерации в случаях возникновения чрезвычайных ситуаций\nВ случаях возникновения чрезвычайных ситуаций государство принимает меры по защите интересов российских туристов за пределами Российской Федерации, в том числе меры по их эвакуации из страны временного пребывания."],
["17","Добровольное страхование имущественных интересов туристов","Глава VII. Безопасность туризма","2015-06-29","Статья 17. Добровольное страхование имущественных интересов туристов\nДоговор добровольного страхования (страховой полис) обеспечивает оплату и (или) возмещение расходов на оплату медицинской помощи в экстренной и неотложной формах в стране временного пребывания и (или) возвращения тела (останков).\nТуроператор (турагент) обязан разъяснить туристу под личную подпись, что в случае отказа от заключения договора добровольного страхования расходы на оказание медицинской помощи в экстренной и неотложной формах в стране временного пребывания несет сам турист, а расходы на возвращение тела (останков) несут лица, заинтересованные в возвращении тела (останков).\nУсловия и порядок осуществления добровольного страхования определяются правилами страхования, разрабатываемыми страховщиком или объединением страховщиков с учетом требований международных договоров Российской Федерации и законодательства Российской Федерации о страховании.\nПравила страхования должны предусматривать:\nобязанность страховщика осуществить оплату и (или) возместить расходы на оплату медицинской помощи в экстренной и неотложной формах в стране временного пребывания и (или) возвращения тела (останков);\nисполнение страховщиком обязанности, указанной в абзаце втором настоящей части, независимо от даты окончания действия договора добровольного страхования, если страховой случай наступил в период действия этого договора;\nзаключение договора добровольного страхования на срок не менее указанного туристом периода его временного пребывания за пределами страны постоянного проживания;\nусловие о вступлении договора добровольного страхования в силу не позднее даты пересечения туристом Государственной границы Российской Федерации;\nустановление страховой суммы в размере, определенном исходя из требований к размеру страховой суммы, предъявляемых страной временного пребывания туриста, но не менее суммы, эквивалентной двум миллионам рублей по официальному курсу Центрального банка Российской Федерации, установленному на дату заключения договора добровольного страхования.\nСтраховщик вправе устанавливать в правилах страхования дополнительные события, при наступлении которых у него возникает обязанность произвести страховую выплату страхователю, застрахованному лицу, выгодоприобретателю или иным третьим лицам, а также вправе увеличивать установленную настоящей статьей минимальную страховую сумму по договору добровольного страхования.\nВ случае необходимости получения туристом медицинской помощи в экстренной и неотложной формах в стране временного пребывания при наступлении страхового случая в медицинскую организацию или врачу предъявляется договор добровольного страхования (страховой полис) на русском и английском языках или сообщаются его номер, наименование страховщика и номер телефона, по которому следует обращаться при наступлении страхового случая.\n(Статья в редакции Федерального закона от 29.06.2015 № 155-ФЗ)"],
["17.1","Требования к предоставляемому финансовому обеспечению ответственности туроператора","Глава VII.1. Финансовое обеспечение ответственности туроператора","2024-08-08","Статья 17.1. Требования к предоставляемому финансовому обеспечению ответственности туроператора\n(Наименование в редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nДоговор страхования ответственности туроператора либо банковская гарантия должны обеспечивать надлежащее исполнение туроператором обязательств по всем договорам о реализации туристского продукта, заключаемым с туристами и (или) иными заказчиками непосредственно туроператором либо по его поручению турагентами.\nВ случае возникновения обстоятельств, указанных в статье 17.4 настоящего Федерального закона, финансовое обеспечение ответственности туроператора должно гарантировать каждому туристу или иному заказчику, заключившему договор о реализации туристского продукта: (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nвозврат денежных средств, внесенных в счет договора о реализации туристского продукта, за услуги, оплаченные, но не оказанные туроператором или третьими лицами, на которых туроператором было возложено исполнение обязательств по договору о реализации туристского продукта;\nвыплату денежных средств, причитающихся туристу или иному заказчику в возмещение реального ущерба, возникшего в результате неисполнения туроператором обязательств по договору о реализации туристского продукта, в том числе денежных средств, необходимых для компенсации расходов, понесенных туристом или иным заказчиком в связи с непредвиденным выездом (эвакуацией) из страны (места) временного пребывания (далее - расходы по эвакуации). (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nДля целей настоящего Федерального закона под расходами по эвакуации понимаются не включенные в общую цену туристского продукта расходы по перевозке, размещению, а равно иные расходы по эвакуации.\nВ состав реального ущерба, понесенного туристом и (или) иным заказчиком в результате неисполнения туроператором обязательств по договору о реализации туристского продукта, не включаются расходы, произведенные туристом в стране (месте) временного пребывания по собственному усмотрению и не обусловленные договором о реализации туристского продукта. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nЛюбые суммы, предоставление которых туристу и (или) иному заказчику гарантируется финансовым обеспечением ответственности туроператора, должны использоваться исключительно для удовлетворения требований туриста и (или) иного заказчика, предъявляемых на основании правил, установленных настоящей главой. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nСтраховщиками по договору страхования ответственности туроператора могут быть страховая организация, иностранная страховая организация, общество взаимного страхования, имеющие право осуществлять страхование гражданской ответственности за неисполнение или ненадлежащее исполнение обязательств по договору в соответствии со страховым законодательством (далее - страховщики). (В редакции федеральных законов от 02.07.2021 № 343-ФЗ, от 08.08.2024 № 256-ФЗ)\nГарантом по банковской гарантии может быть банк, иная кредитная организация, зарегистрированные в соответствии с Федеральным законом \"О государственной регистрации юридических лиц и индивидуальных предпринимателей\" (далее - гарант). (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nДосрочное расторжение договора страхования ответственности туроператора осуществляется в соответствии с Гражданским кодексом Российской Федерации. Туроператор не позднее 45 календарных дней со дня досрочного расторжения договора страхования ответственности туроператора либо отзыва банковской гарантии обязан представить в уполномоченный федеральный орган исполнительной власти документ, подтверждающий наличие у него финансового обеспечения ответственности туроператора. (В редакции федеральных законов от 02.03.2016 № 49-ФЗ; от 04.06.2018 № 149-ФЗ)\nВ договоре страхования ответственности туроператора или в банковской гарантии должно содержаться условие, предусматривающее право туриста и (или) иного заказчика, заключивших договор о реализации туристского продукта с турагентом, при наступлении обстоятельств, предусмотренных статьей 17.4 настоящего Федерального закона, обратиться к страховщику или гаранту с письменным требованием о выплате страхового возмещения по договору страхования ответственности туроператора либо об уплате денежной суммы по банковской гарантии. (В редакции Федерального закона от 02.03.2016 № 49-ФЗ)\nПри этом банковская гарантия должна предусматривать положение о возможности передачи без согласия гаранта права требования об уплате денежной суммы, принадлежащего туристу и (или) иному заказчику, объединению туроператоров в сфере выездного туризма в пределах суммы расходов, понесенных объединением туроператоров в сфере выездного туризма в соответствии с настоящим Федеральным законом на оказание экстренной помощи туристу. (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ)\nПравила применения договора страхования ответственности туроператора и банковской гарантии для финансового обеспечения ответственности туроператора определяются в соответствии с гражданским законодательством с учетом особенностей, предусмотренных настоящим Федеральным законом.\nВ случае отзыва у организации, предоставившей туроператору финансовое обеспечение ответственности туроператора, лицензии на осуществление добровольного имущественного страхования или лицензии на осуществление банковских операций либо признания такой организации несостоятельной (банкротом) в соответствии с законодательством Российской Федерации туроператор не позднее 45 календарных дней со дня получения соответствующего уведомления от уполномоченного федерального органа исполнительной власти обязан представить в уполномоченный федеральный орган исполнительной власти документ, подтверждающий наличие у туроператора финансового обеспечения ответственности туроператора. В случае, если указанный документ не представлен, уполномоченный федеральный орган исполнительной власти исключает сведения о туроператоре из реестра не позднее 10 календарных дней со дня, следующего за днем, когда истек срок представления туроператором указанного документа (за исключением туроператоров, указанных в части пятой статьи 4.1 настоящего Федерального закона). (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nВ целях своевременного получения информации об отзыве у организации, предоставившей туроператору финансовое обеспечение ответственности туроператора, лицензии на осуществление добровольного имущественного страхования или лицензии на осуществление банковских операций либо о признании такой организации несостоятельной (банкротом) в соответствии с законодательством Российской Федерации уполномоченный федеральный орган исполнительной власти осуществляет взаимодействие с органом, осуществляющим функции по надзору в сфере страховой деятельности и за деятельностью кредитных организаций, на основании соглашения между ними. (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ) (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nТуроператор вправе относить затраты, связанные с финансовым обеспечением ответственности туроператора, на себестоимость туристского продукта. (Дополнение частью - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["17.2","Размер финансового обеспечения ответственности туроператора","Глава VII.1. Финансовое обеспечение ответственности туроператора","2022-03-12","Статья 17.2. Размер финансового обеспечения ответственности туроператора\nРазмер финансового обеспечения ответственности туроператора определяется договором или договорами страхования ответственности туроператора и (или) банковской гарантией или банковскими гарантиями и не может быть меньше:\n500 тысяч рублей - для туроператоров, осуществляющих деятельность в сфере внутреннего туризма или въездного туризма;\nтрех процентов (на 2016 год), с 2017 года пяти процентов общей цены туристского продукта в сфере выездного туризма за предыдущий год, но не менее чем 50 миллионов рублей - для туроператоров, осуществляющих деятельность в сфере выездного туризма, за исключением туроператоров, указанных в абзаце втором части второй статьи 11.4 настоящего Федерального закона; (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n(Особенности применения абзаца - Постановление Правительства Российской Федерации от 12.03.2022 № 353)\n10 миллионов рублей - для туроператоров, указанных в абзаце втором части второй статьи 11.4 настоящего Федерального закона.\nТуроператоры, не осуществлявшие в предыдущем году деятельности в сфере выездного туризма, юридические лица, намеренные осуществлять туроператорскую деятельность в сфере выездного туризма и ранее не осуществлявшие такой деятельности, а также туроператоры, которые ранее осуществляли деятельность в сфере выездного туризма, но сведения о которых были исключены из реестра туроператоров в соответствии с частью шестнадцатой статьи 4.2 настоящего Федерального закона и которые намерены осуществлять туроператорскую деятельность в сфере выездного туризма, должны иметь финансовое обеспечение ответственности туроператора в сфере выездного туризма в размере не менее чем 50 миллионов рублей. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 24.03.2021 № 48-ФЗ)\n(Особенности применения части - Постановление Правительства Российской Федерации от 12.03.2022 № 353)\nВ случае, если туроператор осуществляет туроператорскую деятельность в нескольких сферах туризма, применяется наибольший размер финансового обеспечения ответственности туроператора. Туроператор, осуществляющий деятельность одновременно в сфере выездного туризма и в сфере въездного туризма и (или) внутреннего туризма, сформировавший фонд персональной ответственности туроператора в максимальном размере и получивший освобождение от финансового обеспечения ответственности туроператора в сфере выездного туризма и уплаты взносов в фонд персональной ответственности туроператора, должен иметь финансовое обеспечение ответственности туроператора, предусмотренное абзацем вторым части первой настоящей статьи. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n(Статья в редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["17.2-1","Особенности определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, формирующего туристский продукт, предусматривающий выезд туристов в сопредельные государства","Глава VII.1. Финансовое обеспечение ответственности туроператора","2025-07-23","Статья 17.2-1. Особенности определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, формирующего туристский продукт, предусматривающий выезд туристов в сопредельные государства\nТуроператор, осуществляющий деятельность в сфере выездного туризма, вправе не учитывать общую цену реализованного им туристского продукта, предусмотренного частью десятой настоящей статьи, при определении размера финансового обеспечения ответственности туроператора на новый срок, соответствующий положениям частей первой и четвертой статьи 17.3 настоящего Федерального закона.\nТуроператор, осуществляющий деятельность в сфере выездного туризма и формирующий только туристский продукт, предусматривающий выезд туристов в сопредельные государства, которые включены в перечень, предусмотренный частью двенадцатой настоящей статьи, определяет размер финансового обеспечения ответственности туроператора в соответствии с абзацем вторым части первой статьи 17.2 настоящего Федерального закона.\nЮридическое лицо, намеревающееся осуществлять туроператорскую деятельность в сфере выездного туризма и ранее не осуществлявшее такую деятельность, в целях применения особенности определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, предусмотренной частью первой или второй настоящей статьи, представляет в уполномоченный федеральный орган исполнительной власти заявление, указанное в части четвертой статьи 4.2 настоящего Федерального закона, с информацией о намерении применять указанную особенность определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма.\nТуроператор, осуществляющий деятельность в сфере выездного туризма, в целях применения особенности определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, предусмотренной частью первой или второй настоящей статьи, представляет в уполномоченный федеральный орган исполнительной власти уведомление, указанное в части двенадцатой статьи 4.2 настоящего Федерального закона, с информацией о намерении применять указанную особенность определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма и отчетность, указанную в статье 17.7 настоящего Федерального закона, содержащую информацию о реализованных таким туроператором в течение четырех последовательных кварталов, предшествующих дате подачи указанного уведомления, туристских продуктах, предусматривающих выезд туристов в сопредельные государства, которые включены в перечень, предусмотренный частью двенадцатой настоящей статьи.\nВ случае, если туроператором, осуществляющим деятельность в сфере выездного туризма, не применяется особенность определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, предусмотренная частью первой или второй настоящей статьи, такой туроператор определяет размер финансового обеспечения ответственности туроператора в сфере выездного туризма в соответствии с абзацем третьим или четвертым части первой статьи 17.2 настоящего Федерального закона.\nРешение о применении (об отказе в применении) особенностей определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, формирующего туристский продукт, предусмотренный частью десятой настоящей статьи, принимается уполномоченным федеральным органом исполнительной власти на основании заявления или уведомления, указанных соответственно в частях третьей и четвертой настоящей статьи, на срок действия финансового обеспечения ответственности туроператора, предусмотренный частью первой статьи 17.3 настоящего Федерального закона.\nОснованием для отказа в применении особенностей определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, формирующего туристский продукт, предусмотренный частью десятой настоящей статьи, является:\nнарушение предусмотренного частями четвертой и одиннадцатой статьи 4.2 настоящего Федерального закона порядка представления заявления или уведомления, указанных соответственно в частях третьей и четвертой настоящей статьи;\nнесоответствие сведений, представленных в отчетности, указанной в статье 17.7 настоящего Федерального закона, сведениям, представленным туроператором в единую информационную систему электронных путевок.\nИнформация, предусмотренная абзацами вторым и шестым части второй статьи 4.2 настоящего Федерального закона, подтверждающая исполнение туроператором, осуществляющим деятельность в сфере выездного туризма, условий для применения особенности определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, предусмотренной частью первой или второй настоящей статьи, представляется в уполномоченный федеральный орган исполнительной власти в соответствии с требованиями к отчетности, установленными частью четвертой статьи 17.7 настоящего Федерального закона.\nПорядок принятия решения о применении (об отказе в применении) особенности определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, формирующего туристский продукт, предусмотренный частью десятой настоящей статьи, устанавливается Правительством Российской Федерации.\nПод туристским продуктом, предусматривающим выезд туристов в сопредельные государства, понимается туристский продукт, предусматривающий выезд туристов исключительно в сопредельные государства, которые включены в перечень, предусмотренный частью двенадцатой настоящей статьи, и не предусматривающий посещения иных иностранных государств.\nВ случае, если туроператором, осуществляющим деятельность в сфере выездного туризма и применяющим особенность определения размера финансового обеспечения ответственности туроператора в сфере выездного туризма, предусмотренную частью второй настоящей статьи, формируется туристский продукт, предусматривающий посещение туристами иностранных государств, которые не включены в перечень сопредельных государств, предусмотренный частью двенадцатой настоящей статьи, сведения о таком туроператоре подлежат исключению из реестра туроператоров на основании абзаца шестого части пятнадцатой статьи 4.2 настоящего Федерального закона.\nПеречень сопредельных государств с благоприятными условиями для пребывания российских туристов устанавливается Правительством Российской Федерации. В указанный перечень не включаются иностранные государства, включенные в перечень иностранных государств и территорий, совершающих в отношении Российской Федерации, российских юридических и физических лиц недружественные действия.\n(Дополнение статьей - Федеральный закон от 23.07.2025 № 238-ФЗ)"],
["17.3","Срок действия финансового обеспечения ответственности туроператора","Глава VII.1. Финансовое обеспечение ответственности туроператора","2018-06-04","Статья 17.3. Срок действия финансового обеспечения ответственности туроператора\nСрок действия финансового обеспечения ответственности туроператора указывается в договоре или договорах страхования ответственности туроператора и (или) банковской гарантии либо банковских гарантиях и не может быть менее чем один год.\nВ случае заключения нескольких договоров страхования ответственности туроператора и (или) получения нескольких банковских гарантий соответствующие договоры и банковские гарантии должны вступать в силу и прекращать свое действие одновременно.\nФинансовое обеспечение ответственности туроператора на новый срок должно быть получено туроператором не позднее сорока пяти дней до дня истечения срока действия имеющегося у туроператора договора страхования ответственности туроператора или договора о предоставлении банковской гарантии, если иное не предусмотрено настоящим Федеральным законом. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nЗаключенный на новый срок договор страхования ответственности туроператора или договор о предоставлении банковской гарантии должен начинать действовать со дня, следующего за днем истечения срока действия имеющихся у туроператора договора страхования ответственности туроператора или договора о предоставлении банковской гарантии, если иное не предусмотрено настоящим Федеральным законом. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nСведения о наличии у туроператора финансового обеспечения ответственности туроператора на новый срок представляются в уполномоченный федеральный орган исполнительной власти не позднее сорока пяти дней до дня истечения срока действия имеющихся у туроператора договора страхования ответственности туроператора или договора о предоставлении банковской гарантии, если иное не предусмотрено настоящим Федеральным законом. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n(Статья в редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["17.4","Основание для выплаты страхового возмещения по договору страхования ответственности туроператора либо уплаты денежной суммы по банковской гарантии","Глава VII.1. Финансовое обеспечение ответственности туроператора","2021-03-24","Статья 17.4. Основание для выплаты страхового возмещения по договору страхования ответственности туроператора либо уплаты денежной суммы по банковской гарантии\nСтраховщик обязан выплатить страховое возмещение по договору страхования ответственности туроператора по письменному требованию туриста и (или) иного заказчика, заключивших договор о реализации туристского продукта, при наступлении страхового случая.\nГарант обязан уплатить денежную сумму по банковской гарантии по письменному требованию туриста и (или) иного заказчика, заключивших договор о реализации туристского продукта, в случае отказа туроператора возместить реальный ущерб, возникший в результате неисполнения туроператором обязательств по договору о реализации туристского продукта.\nОснованием для выплаты страхового возмещения по договору страхования ответственности туроператора либо уплаты денежной суммы по банковской гарантии является факт причинения туристу и (или) иному заказчику реального ущерба по причине неисполнения туроператором своих обязательств по договору о реализации туристского продукта в связи с прекращением туроператорской деятельности по причине невозможности исполнения туроператором всех обязательств по договорам о реализации туристского продукта. При этом датой страхового случая считается день, когда туроператор публично заявил о прекращении туроператорской деятельности по причине невозможности исполнения туроператором всех обязательств по договорам о реализации туристского продукта. В случае, если туроператор не сделал такого заявления, но прекратил туроператорскую деятельность по указанной причине, о чем уполномоченному федеральному органу исполнительной власти стало известно, датой страхового случая считается день принятия уполномоченным федеральным органом исполнительной власти решения об исключении туроператора из реестра туроператоров на основании абзаца шестнадцатого части пятнадцатой статьи 4.2 настоящего Федерального закона. (В редакции федеральных законов от 04.06.2018 № 149-ФЗ, от 24.03.2021 № 48-ФЗ)\nПод реальным ущербом, подлежащим возмещению в рамках страхового возмещения по договору страхования ответственности туроператора или банковской гарантии, понимаются расходы туриста и (или) иного заказчика на оплату услуг по перевозке и (или) размещению по договору о реализации туристского продукта.\nВыплата страхового возмещения по договору страхования ответственности туроператора или уплата денежной суммы по банковской гарантии не лишает туриста и (или) иного заказчика права требовать от туроператора выплаты штрафов, пеней, возмещения упущенной выгоды и (или) морального вреда в порядке и на условиях, которые предусмотрены законодательством Российской Федерации.\nЧасть. (Утратила силу - Федеральный закон от 04.06.2018 № 149-ФЗ)\n(Статья в редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["17.5","Порядок выплаты страхового возмещения по договору или договорам страхования ответственности туроператора либо уплаты денежной суммы по банковской гарантии или банковским гарантиям","Глава VII.1. Финансовое обеспечение ответственности туроператора","2018-06-04","Статья 17.5. Порядок выплаты страхового возмещения по договору или договорам страхования ответственности туроператора либо уплаты денежной суммы по банковской гарантии или банковским гарантиям\nВ случаях неисполнения туроператором обязательств по договору о реализации туристского продукта перед туристом и (или) иным заказчиком и наличия основания для выплаты страхового возмещения по договору страхования ответственности туроператора либо уплаты денежной суммы по банковской гарантии турист или его законный представитель и (или) иной заказчик вправе в пределах размера финансового обеспечения ответственности туроператора предъявить письменное требование о выплате страхового возмещения либо об уплате денежной суммы непосредственно организации, предоставившей финансовое обеспечение.\nВ требовании туриста и (или) иного заказчика о выплате страхового возмещения либо об уплате денежной суммы по банковской гарантии к организации, предоставившей финансовое обеспечение ответственности туроператора, указываются:\nфамилия, имя и отчество туриста, а также сведения об ином заказчике, если договор о реализации туристского продукта заключался заказчиком;\nдата выдачи, срок действия и иные реквизиты документа, представленного в качестве финансового обеспечения ответственности туроператора;\nномер договора о реализации туристского продукта и дата его заключения;\nнаименование туроператора, которому предоставлено финансовое обеспечение ответственности туроператора;\nинформация об обстоятельствах (фактах), свидетельствующих о неисполнении туроператором обязательств по договору о реализации туристского продукта;\nразмер реального ущерба, причиненного туристу и (или) иному заказчику в связи с неисполнением туроператором обязательств по договору о реализации туристского продукта;\nв случае, если требование об уплате денежной суммы предъявляется по банковской гарантии гаранту, реквизиты документа, свидетельствующего об отказе туроператора в добровольном порядке удовлетворить требование о возмещении реального ущерба, понесенного туристом и (или) иным заказчиком в результате неисполнения туроператором обязательств по договору о реализации туристского продукта, и (или) номер и дата вступившего в законную силу судебного решения о возмещении туроператором указанного реального ущерба.\nК требованию о выплате страхового возмещения либо об уплате денежной суммы по банковской гарантии турист и (или) иной заказчик прилагают:\nкопию паспорта или иного документа, удостоверяющего личность в соответствии с законодательством Российской Федерации, с предъявлением оригинала указанных документов;\nкопию договора о реализации туристского продукта с предъявлением его оригинала в случае заключения договора о реализации туристского продукта на бумажном носителе;\nдокументы, подтверждающие реальный ущерб, возникший у туриста и (или) иного заказчика в результате неисполнения туроператором обязательств по договору о реализации туристского продукта;\nдоговор о реализации туристского продукта в форме электронного документа на электронном носителе информации в случае заключения договора о реализации туристского продукта в форме электронного документа.\nНе подлежат возмещению страховщиком или гарантом расходы, произведенные туристом и (или) иным заказчиком и не обусловленные неисполнением туроператором своих обязательств по договору о реализации туристского продукта в связи с прекращением туроператорской деятельности по причине невозможности исполнения туроператором всех обязательств по договорам о реализации туристского продукта.\nДля исполнения своих обязательств по финансовому обеспечению ответственности туроператора страховщик или гарант не вправе требовать представления иных документов, за исключением документов, предусмотренных настоящей статьей.\nПисьменное требование о выплате страхового возмещения по договору страхования ответственности туроператора либо об уплате денежной суммы по банковской гарантии может быть предъявлено туристом и (или) иным заказчиком страховщику либо гаранту, предоставившим финансовое обеспечение ответственности туроператора, в течение срока исковой давности по основанию, возникшему в период срока действия финансового обеспечения ответственности туроператора.\nПорядок выплаты туристу и (или) иному заказчику страхового возмещения по договору страхования ответственности туроператора или уплаты денежной суммы по банковской гарантии в случаях заключения туроператором более одного договора страхования либо более одного договора о предоставлении банковской гарантии или заключения туроператором договора либо договоров страхования и договора либо договоров о предоставлении банковской гарантии устанавливается Правительством Российской Федерации с учетом требований настоящей статьи.\nСтраховщик или гарант обязан удовлетворить требование туриста и (или) иного заказчика о выплате страхового возмещения по договору страхования ответственности туроператора или об уплате денежной суммы по банковской гарантии не позднее тридцати календарных дней после дня получения указанного требования с приложением всех необходимых и предусмотренных настоящей статьей документов.\nВ случаях, если с требованиями о выплате страхового возмещения по договору страхования ответственности туроператора или об уплате денежной суммы по банковской гарантии к страховщику или гаранту обратились более одного туриста и (или) иного заказчика и общая сумма денежных средств, подлежащих выплате, превышает размер финансового обеспечения ответственности туроператора, удовлетворение таких требований осуществляется пропорционально суммам денежных средств, указанным в требованиях, к размеру финансового обеспечения ответственности туроператора. Правила страхования ответственности туроператора, утвержденные страховщиком или объединением страховщиков, должны содержать положения о порядке выплаты страхового возмещения в указанных случаях. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nСтраховщик или гарант обязан в течение трех рабочих дней проинформировать уполномоченный федеральный орган исполнительной власти о получении первого требования туриста и (или) иного заказчика о выплате страхового возмещения по договору страхования ответственности туроператора или об уплате денежной суммы по банковской гарантии в отношении конкретного туроператора. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\n(Статья в редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["17.6","Договор страхования ответственности туроператора","Глава VII.1. Финансовое обеспечение ответственности туроператора","2018-06-04","Статья 17.6. Договор страхования ответственности туроператора\nТуроператор в порядке и на условиях, которые установлены настоящим Федеральным законом, за свой счет осуществляет страхование риска своей ответственности, которая может наступить вследствие неисполнения им обязательств по договору о реализации туристского продукта по причине прекращения своей деятельности.\nОбъектом страхования ответственности туроператора являются имущественные интересы туроператора, связанные с риском возникновения обязанности возместить туристам и (или) иным заказчикам реальный ущерб, возникший в результате неисполнения туроператором своих обязательств по договору о реализации туристского продукта в связи с прекращением туроператорской деятельности по причине невозможности исполнения туроператором всех обязательств по договорам о реализации туристского продукта. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nСтраховым случаем по договору страхования ответственности туроператора является неисполнение туроператором своих обязательств по договору о реализации туристского продукта в связи с прекращением туроператорской деятельности по причине невозможности исполнения туроператором всех обязательств по договорам о реализации туристского продукта. (В редакции Федерального закона от 04.06.2018 № 149-ФЗ)\nСтраховщик освобождается от выплаты страхового возмещения туристу и (или) иному заказчику, если турист и (или) иной заказчик обратились к страховщику с требованием о выплате штрафов, пеней, возмещении упущенной выгоды и (или) морального вреда, возникших в результате неисполнения туроператором обязательств по договору о реализации туристского продукта.\nВ договоре страхования ответственности туроператора не может быть предусмотрено условие о франшизе при наступлении страхового случая.\nСтраховая сумма по договору страхования ответственности туроператора определяется по соглашению туроператора и страховщика, но не может быть менее размера финансового обеспечения ответственности туроператора, предусмотренного настоящим Федеральным законом. В случае заключения туроператором более одного договора страхования или более одного договора о предоставлении банковской гарантии либо заключения туроператором договора или договоров страхования и договора или договоров о предоставлении банковской гарантии страховые суммы и размеры банковской гарантии по этим договорам определяются с таким расчетом, чтобы в совокупности они были не менее размера финансового обеспечения ответственности туроператора, предусмотренного настоящим Федеральным законом.\nСтраховой тариф по договору страхования ответственности туроператора определяется страховщиком исходя из сроков действия договора страхования и с учетом факторов, влияющих на степень страхового риска.\nДоговор страхования ответственности туроператора заключается на срок не менее чем один год.\nДоговор страхования ответственности туроператора должен включать в себя:\nопределение объекта страхования;\nопределение страхового случая;\nразмер страховой суммы;\nсрок действия договора страхования;\nпорядок и сроки уплаты страховой премии;\nпорядок и сроки уведомления туристом и (или) иным заказчиком страховщика о наступлении страхового случая;\nпорядок и сроки предъявления туристом или его законными представителями и (или) иным заказчиком требования о выплате страхового возмещения по договору страхования ответственности туроператора непосредственно страховщику;\nперечень документов, которые обязаны представить турист и (или) иной заказчик в обоснование своих требований к страхователю о возмещении реального ущерба;\nответственность за неисполнение или ненадлежащее исполнение обязательств субъектами страхования.\nВ договоре страхования ответственности туроператора по соглашению сторон могут определяться иные права и обязанности.\nТуроператор вправе для защиты своих имущественных интересов по отдельному договору страхования, заключаемому со страховщиком, страховать свою ответственность за неисполнение обязательств по договору о реализации туристского продукта с учетом выплаты страхового возмещения туристам и (или) иным заказчикам по дополнительным основаниям, за исключением основания, предусмотренного статьей 17.4 настоящего Федерального закона.\nК отношениям по договору страхования ответственности туроператора применяются положения настоящего Федерального закона о финансовом обеспечении ответственности туроператора, если иное не установлено настоящей статьей.\n(Статья в редакции Федерального закона от 02.03.2016 № 49-ФЗ)"],
["17.7","Учет и отчетность","Глава VII.1. Финансовое обеспечение ответственности туроператора","2021-07-02","Статья 17.7. Учет и отчетность\nТуроператор, осуществляющий деятельность в сфере выездного туризма, обязан соблюдать требования финансовой устойчивости и платежеспособности, нормативного соотношения собственных средств (капитала) и принятых обязательств, а также иные требования, установленные настоящим Федеральным законом и нормативными правовыми актами уполномоченного федерального органа исполнительной власти.\nЧасть. (Утратила силу - Федеральный закон от 04.06.2018 № 149-ФЗ)\nУсловия и форматы представления туроператором, осуществляющим деятельность в сфере выездного туризма, отчетности (за исключением бухгалтерской (финансовой) отчетности), в том числе в виде электронных документов, контрольные соотношения ее показателей устанавливаются и доводятся до сведения туроператоров, осуществляющих деятельность в сфере выездного туризма, уполномоченным федеральным органом исполнительной власти не позднее последнего дня соответствующего отчетного периода путем размещения указанной информации на официальном сайте этого органа в информационно-телекоммуникационной сети \"Интернет\".\nТребования к отчетности, ее составу и форме утверждаются уполномоченным федеральным органом исполнительной власти.\nГодовая бухгалтерская (финансовая) отчетность туроператора, осуществляющего деятельность в сфере выездного туризма, подлежит обязательному аудиту, если общая цена туристского продукта в сфере выездного туризма за предыдущий год составила более 400 миллионов рублей. Аудит указанной отчетности должен быть проведен не позднее 15 апреля года, следующего за отчетным годом. Аудиторское заключение представляется туроператором, осуществляющим деятельность в сфере выездного туризма, в уполномоченный федеральный орган исполнительной власти вместе с копией бухгалтерской (финансовой) отчетности в случае, установленном частью шестой настоящей статьи. (В редакции Федерального закона от 02.07.2021 № 352-ФЗ)\nТуроператоры, в отношении которых законодательством Российской Федерации не предусмотрено обязательное опубликование данных бухгалтерской (финансовой) отчетности на конец отчетного года и которые освобождены от обязанности представлять годовую бухгалтерскую (финансовую) отчетность в целях формирования государственного информационного ресурса бухгалтерской (финансовой) отчетности, представляют копию указанной отчетности в уполномоченный федеральный орган исполнительной власти в установленном им порядке. (В редакции Федерального закона от 02.07.2021 № 352-ФЗ)\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 49-ФЗ)"],
["18","Международные договоры Российской Федерации в сфере туризма","Глава VIII. Международное сотрудничество","","Статья 18. Международные договоры Российской Федерации в сфере туризма\nПравовую основу международного сотрудничества в сфере туризма составляют международные договоры Российской Федерации, заключаемые в соответствии с Федеральным законом \"О международных договорах Российской Федерации\"."],
["19","Представительство федерального органа исполнительной власти, осуществляющего функции по оказанию государственных услуг в сфере туризма, за пределами Российской Федерации","Глава VIII. Международное сотрудничество","2012-05-03","Статья 19. Представительство федерального органа исполнительной власти, осуществляющего функции по оказанию государственных услуг в сфере туризма, за пределами Российской Федерации\n(Наименование в редакции Федерального закона от 03.05.2012 № 47-ФЗ)\nВ целях продвижения туристского продукта на мировом туристском рынке федеральный орган исполнительной власти, осуществляющий функции по оказанию государственных услуг в сфере туризма, создает представительства за пределами Российской Федерации. Порядок создания, деятельности и ликвидации указанных представительств определяется Правительством Российской Федерации в соответствии с международными договорами Российской Федерации. (В редакции Федерального закона от 03.05.2012 № 47-ФЗ)"],
["19.1","Федеральный государственный контроль (надзор) за деятельностью туроператоров и объединения туроператоров в сфере выездного туризма","Глава VIII.1. Государственный контроль (надзор) в сфере туристской деятельности","2024-03-23","Статья 19.1. Федеральный государственный контроль (надзор) за деятельностью туроператоров и объединения туроператоров в сфере выездного туризма\nФедеральный государственный контроль (надзор) за деятельностью туроператоров и объединения туроператоров в сфере выездного туризма осуществляется федеральным органом исполнительной власти, уполномоченным Правительством Российской Федерации.\nПредметом федерального государственного контроля (надзора) за деятельностью туроператоров и объединения туроператоров в сфере выездного туризма является соблюдение туроператорами и объединением туроператоров в сфере выездного туризма обязательных требований в сфере туристской деятельности, установленных настоящим Федеральным законом и принимаемыми в соответствии с ним иными нормативными правовыми актами, за исключением обязательных требований, установленных в области защиты прав потребителей.\nОрганизация и осуществление федерального государственного контроля (надзора) за деятельностью туроператоров и объединения туроператоров в сфере выездного туризма регулируются Федеральным законом от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\".\nПоложение о федеральном государственном контроле (надзоре) за деятельностью туроператоров и объединения туроператоров в сфере выездного туризма утверждается Правительством Российской Федерации.\nПри осуществлении федерального государственного контроля (надзора) за деятельностью туроператоров и объединения туроператоров в сфере выездного туризма плановые контрольные (надзорные) мероприятия не проводятся.\nЧасть. (Дополнение частью - Федеральный закон от 20.04.2021 № 93-ФЗ) (Утратила силу - Федеральный закон от 23.03.2024 № 63-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 20.04.2021 № 93-ФЗ) (Утратила силу - Федеральный закон от 23.03.2024 № 63-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 20.04.2021 № 93-ФЗ) (Утратила силу - Федеральный закон от 23.03.2024 № 63-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 20.04.2021 № 93-ФЗ) (Утратила силу - Федеральный закон от 23.03.2024 № 63-ФЗ)\nЧасть. (Дополнение частью - Федеральный закон от 20.04.2021 № 93-ФЗ) (Утратила силу - Федеральный закон от 23.03.2024 № 63-ФЗ)\n(Статья в редакции Федерального закона от 11.06.2021 № 170-ФЗ)"],
["19.2","Федеральный государственный контроль (надзор) за деятельностью организаций, осуществляющих классификацию в сфере туристской индустрии","Глава VIII.1. Государственный контроль (надзор) в сфере туристской деятельности","2024-11-30","Статья 19.2. Федеральный государственный контроль (надзор) за деятельностью организаций, осуществляющих классификацию в сфере туристской индустрии\nФедеральный государственный контроль (надзор) за деятельностью организаций, осуществляющих классификацию в сфере туристской индустрии (далее - федеральный контроль (надзор) за деятельностью организаций), осуществляется органом по аккредитации.\nПредметом федерального контроля (надзора) за деятельностью организаций является соблюдение организациями, осуществляющими классификацию в сфере туристской индустрии, аккредитованными в соответствии со статьей 5.3 настоящего Федерального закона, установленных настоящим Федеральным законом и принимаемыми в соответствии с ним нормативными правовыми актами обязательных требований:\nк организациям, осуществляющим классификацию в сфере туристской индустрии, в том числе к экспертам по классификации;\nк порядку присвоения средству размещения определенной категории организациями, осуществляющими классификацию в сфере туристской индустрии;\nк порядку классификации горнолыжных трасс, классификации пляжей;\nк результатам деятельности организаций, осуществляющих классификацию в сфере туристской индустрии (результаты присвоения средству размещения определенной категории, присвоения категории горнолыжной трассе, пляжу).\nОбъектами федерального контроля (надзора) за деятельностью организаций являются:\nдеятельность организаций, осуществляющих классификацию в сфере туристской индустрии;\nрезультаты деятельности организаций, осуществляющих классификацию в сфере туристской индустрии (результаты присвоения средству размещения определенной категории, присвоения категории горнолыжной трассе, пляжу).\nОрганизация и осуществление федерального контроля (надзора) за деятельностью организаций регулируются Федеральным законом от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\".\nПоложение о федеральном контроле (надзоре) за деятельностью организаций, осуществляющих классификацию в сфере туристской индустрии, утверждается Правительством Российской Федерации.\nПри осуществлении федерального контроля (надзора) за деятельностью организаций плановые контрольные (надзорные) мероприятия не проводятся.\nКонтрольные (надзорные) мероприятия в рамках федерального контроля (надзора) за деятельностью организаций проводятся в том числе в случае поступления в орган по аккредитации информации об устранении нарушений обязательных требований, выявленных в рамках процедуры подтверждения компетентности организаций, осуществляющих классификацию в сфере туристской индустрии.\nНаблюдение за соблюдением обязательных требований осуществляется органом по аккредитации или подведомственным органу по аккредитации федеральным государственным учреждением на основании задания должностного лица органа по аккредитации.\nВ ходе осуществления федерального контроля (надзора) за деятельностью организаций орган по аккредитации в случаях и порядке, которые предусмотрены положением о федеральном контроле (надзоре) за деятельностью организаций, осуществляющих классификацию в сфере туристской индустрии, вправе привлекать для совершения отдельных контрольных (надзорных) действий специалистов, являющихся работниками подведомственного органу по аккредитации федерального государственного учреждения.\nОрган по аккредитации по результатам проведения контрольных (надзорных) мероприятий наряду с решениями, принимаемыми по результатам контрольных (надзорных) мероприятий в соответствии с Федеральным законом от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\", вправе:\nпринимать решения о приостановлении действия, возобновлении действия или прекращении действия аккредитации организаций, осуществляющих классификацию в сфере туристской индустрии;\nвыдавать организации, осуществляющей классификацию в сфере туристской индустрии, предписание о необходимости приостановления или прекращения действия присвоенной средству размещения категории;\nвыдавать организации, осуществляющей классификацию в сфере туристской индустрии, предписание о необходимости приостановления или прекращения действия классификации горнолыжной трассы, классификации пляжа;\nпринимать решение о приостановлении или прекращении действия присвоенной средству размещения категории с учетом рекомендаций совета по классификации средств размещения;\nвыдавать организации, осуществляющей классификацию в сфере туристской индустрии, предписание о необходимости осуществления внепланового подтверждения соответствия средства размещения требованиям к присвоенной категории средства размещения;\nвыдавать предписание об устранении нарушений обязательных требований, выявленных в ходе наблюдения за соблюдением обязательных требований.\n(Дополнение статьей - Федеральный закон от 11.06.2021 № 170-ФЗ) (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)"],
["19.3","Государственный контроль (надзор), муниципальный контроль за соблюдением требований к деятельности экскурсоводов (гидов), гидов-переводчиков и инструкторов-проводников","Глава VIII.1. Государственный контроль (надзор) в сфере туристской деятельности","2024-11-30","Статья 19.3. Государственный контроль (надзор), муниципальный контроль за соблюдением требований к деятельности экскурсоводов (гидов), гидов-переводчиков и инструкторов-проводников\nОценка соблюдения требований к деятельности экскурсоводов (гидов), гидов-переводчиков и инструкторов-проводников, установленных настоящим Федеральным законом и принимаемыми в соответствии с ним нормативными правовыми актами, в части наличия соответствующей аттестации у экскурсоводов (гидов), гидов-переводчиков и инструкторов-проводников при сопровождении ими туристов (экскурсантов), соблюдения правил оказания услуг экскурсовода (гида), гида-переводчика, правил оказания услуг инструктора-проводника, сопровождения туристов (экскурсантов) инструктором-проводником при посещении (прохождении) туристских маршрутов, требующих специального сопровождения, осуществляется в рамках следующих видов государственного контроля (надзора), муниципального контроля: (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nрегиональный государственный контроль (надзор) в сфере туристской индустрии (за исключением случаев оказания услуг экскурсоводом (гидом) и гидом-переводчиком, услуг инструктора-проводника на особо охраняемых природных территориях); (В редакции Федерального закона от 30.11.2024 № 436-ФЗ)\nфедеральный государственный контроль (надзор) в области охраны и использования особо охраняемых природных территорий (в случае оказания услуг экскурсоводом (гидом) и гидом-переводчиком, услуг инструктора-проводника на особо охраняемых природных территориях федерального значения);\nрегиональный государственный контроль (надзор) в области охраны и использования особо охраняемых природных территорий (в случае оказания услуг экскурсоводом (гидом) и гидом-переводчиком, услуг инструктора-проводника на особо охраняемых природных территориях регионального значения);\nмуниципальный контроль в области охраны и использования особо охраняемых природных территорий (в случае оказания услуг экскурсоводом (гидом) и гидом-переводчиком, услуг инструктора-проводника на особо охраняемых природных территориях местного значения);\nфедеральный государственный контроль (надзор) в области защиты прав потребителей (в части соблюдения правил оказания услуг экскурсовода (гида), гида-переводчика, инструктора-проводника в отношении содержания договора об оказании соответствующих услуг, соблюдения обязательных требований по доведению до сведения потребителей необходимой информации об оказываемых услугах экскурсовода (гида), гида-переводчика, инструктора-проводника, исполнения договора об оказании соответствующих услуг, рассмотрения требований потребителя, связанных с нарушением его прав). (Дополнение абзацем - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 30.11.2024 № 436-ФЗ)\n(Дополнение статьей - Федеральный закон от 11.06.2021 № 170-ФЗ) (В редакции Федерального закона от 23.03.2024 № 63-ФЗ)"],
["19.4","Государственный контроль (надзор) за соблюдением требований к объектам классификации в сфере туристской индустрии","Глава VIII.1. Государственный контроль (надзор) в сфере туристской деятельности","2024-11-30","Статья 19.4. Государственный контроль (надзор) за соблюдением требований к объектам классификации в сфере туристской индустрии\nОценка соблюдения требований к объектам классификации в сфере туристской индустрии, установленных настоящим Федеральным законом и принимаемыми в соответствии с ним нормативными правовыми актами, в части соблюдения правил предоставления услуг средств размещения (при наличии), правил предоставления гостиничных услуг, наличия сведений о средстве размещения в реестре классифицированных средств размещения, соответствия средства размещения требованиям к соответствующему типу средств размещения, установленным положением о классификации средств размещения, соответствия средства размещения типу и (или) типу и категории, указанным в реестре классифицированных средств размещения, соответствия типа и (или) категории средства размещения, используемых в рекламе, названии средства размещения, а также в деятельности, связанной с использованием средства размещения, типу и (или) категории средства размещения, указанным в реестре классифицированных средств размещения, наличия ссылки в информационно-телекоммуникационной сети \"Интернет\" на запись в реестре классифицированных средств размещения, содержащую сведения о средстве размещения, соответствия сведений о средстве размещения, представленных в информации о предоставлении услуг средства размещения, гостиничных услуг на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\", аналогичным сведениям о средстве размещения, указанным в реестре классифицированных средств размещения, соответствия категории горнолыжной трассы или пляжа, используемых в рекламе, названии горнолыжной трассы или пляжа и деятельности, связанной с использованием горнолыжной трассы или пляжа, категории горнолыжной трассы или пляжа, указанным в реестре классифицированных горнолыжных трасс, реестре классифицированных пляжей, осуществляется в рамках следующих видов контроля (надзора):\nрегиональный государственный контроль (надзор) в сфере туристской индустрии (за исключением требований, относящихся к предмету федерального государственного контроля (надзора) в области защиты прав потребителей);\nфедеральный государственный контроль (надзор) в области защиты прав потребителей (в части соблюдения правил предоставления гостиничных услуг, правил предоставления услуг средств размещения в отношении содержания договора о предоставлении услуг средства размещения, договора о предоставлении гостиничных услуг, соблюдения обязательных требований по доведению до сведения потребителей необходимой информации о предоставляемых услугах средств размещения, гостиничных услуг, исполнения договора о предоставлении услуг средств размещения, договора о предоставлении гостиничных услуг, рассмотрения требований потребителя, связанных с нарушением его прав).\n(Дополнение статьей - Федеральный закон от 30.11.2024 № 436-ФЗ)"],
["19.5","Региональный государственный контроль (надзор) в сфере туристской индустрии","Глава VIII.1. Государственный контроль (надзор) в сфере туристской деятельности","2026-07-04","Статья 19.5. Региональный государственный контроль (надзор) в сфере туристской индустрии\nРегиональный государственный контроль (надзор) в сфере туристской индустрии (далее - региональный государственный контроль (надзор) осуществляется органом государственной власти субъекта Российской Федерации, уполномоченным высшим исполнительным органом субъекта Российской Федерации (далее - контрольный (надзорный) орган). Осуществление регионального государственного контроля (надзора) может быть возложено на государственные учреждения, подведомственные контрольному (надзорному) органу, в пределах полномочий этого органа. (В редакции Федерального закона от 24.06.2025 № 184-ФЗ)\nПредметом регионального государственного контроля (надзора) является соблюдение юридическими лицами, индивидуальными предпринимателями, физическими лицами обязательных требований, установленных настоящим Федеральным законом и принимаемыми в соответствии с настоящим Федеральным законом нормативными правовыми актами и указанных в частях третьей - шестой настоящей статьи.\nВ отношении деятельности, связанной с использованием средств размещения, в отношении которых распространяется действие статьи 5.1 настоящего Федерального закона, за исключением санаторно-курортных организаций, подведомственных федеральным органам исполнительной власти, к предмету регионального государственного контроля (надзора) относится соблюдение следующих обязательных требований:\nналичие сведений о средстве размещения в реестре классифицированных средств размещения;\nсоответствие средства размещения требованиям к соответствующему типу средств размещения, установленным положением о классификации средств размещения;\nсоответствие средства размещения типу и (или) типу и категории, указанным в реестре классифицированных средств размещения;\nсоответствие типа и (или) категории средства размещения, используемых в рекламе, названии средства размещения, а также в деятельности, связанной с использованием средства размещения, типу и (или) категории, указанным в реестре классифицированных средств размещения;\nналичие ссылки в информационно-телекоммуникационной сети \"Интернет\" на запись в реестре классифицированных средств размещения, содержащую сведения о средстве размещения, а также соответствие сведений о средстве размещения, представленных в информации о предоставлении услуг средства размещения, гостиничных услуг на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\", аналогичным сведениям о средстве размещения, указанным в реестре классифицированных средств размещения;\nсоблюдение правил оказания гостиничных услуг, услуг средств размещения (при наличии) (за исключением требований, относящихся к предмету федерального государственного контроля (надзора) в области защиты прав потребителей);\nсоблюдение порядка обеспечения условий доступности для инвалидов объектов туристской индустрии, подлежащих классификации в соответствии с законодательством Российской Федерации о туристской деятельности (за исключением объектов, относящихся к средствам размещения в соответствии с Федеральным законом от 7 июня 2025 года № 127-ФЗ \"О проведении эксперимента по предоставлению услуг гостевых домов\", и предоставляемых в них услуг), объема и содержания мер по обеспечению условий доступности для инвалидов указанных объектов и предоставляемых в них услуг; (Дополнение абзацем - Федеральный закон от 29.12.2025 № 552-ФЗ)\nналичие средства размещения по адресу (месту нахождения) объекта недвижимости (здания, сооружения, помещения, земельного участка), в котором в соответствии со сведениями, содержащимися в реестре классифицированных средств размещения, осуществляется деятельность по предоставлению услуг средства размещения, гостиничных услуг. (Дополнение абзацем - Федеральный закон от 04.07.2026 № 235-ФЗ)\nВ отношении деятельности, связанной с использованием горнолыжных трасс или пляжей, к предмету регионального государственного контроля (надзора) относится соблюдение обязательных требований в части соответствия категории горнолыжной трассы или категории пляжа, используемых в рекламе, названии горнолыжной трассы или пляжа и деятельности, связанной с использованием горнолыжной трассы или пляжа, категории горнолыжной трассы или пляжа, указанным в реестре классифицированных горнолыжных трасс или реестре классифицированных пляжей, а также соблюдение порядка обеспечения условий доступности для инвалидов объектов туристской индустрии, подлежащих классификации в соответствии с законодательством Российской Федерации о туристской деятельности, и предоставляемых в них услуг, объема и содержания мер по обеспечению условий доступности для инвалидов указанных объектов и предоставляемых в них услуг. (В редакции Федерального закона от 29.12.2025 № 552-ФЗ)\nВ отношении деятельности экскурсоводов (гидов), гидов-переводчиков к предмету регионального государственного контроля (надзора) относится соблюдение следующих обязательных требований:\nналичие действующей аттестации и нагрудной идентификационной карточки экскурсоводов (гидов) и гидов-переводчиков при оказании ими услуг;\nсоблюдение правил оказания услуг экскурсоводом (гидом) и гидом-переводчиком (за исключением требований, относящихся к предмету федерального государственного контроля (надзора) в области защиты прав потребителей).\n(Абзац. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\n(Абзац. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\nВ отношении деятельности инструкторов-проводников к предмету регионального государственного контроля (надзора) относится соблюдение следующих обязательных требований:\nналичие действующей аттестации и нагрудной идентификационной карточки у инструктора-проводника при оказании им услуг;\nнаправление инструктором-проводником уведомления о сопровождении туристов (экскурсантов) на туристском маршруте, требующем специального сопровождения;\nсопровождение туристов (экскурсантов) инструктором-проводником при посещении (прохождении) туристских маршрутов, требующих специального сопровождения;\nсоблюдение правил оказания услуг инструктора-проводника (за исключением требований, относящихся к предмету федерального государственного контроля (надзора) в области защиты прав потребителей).\n(Абзац. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\n(Абзац. Дополнение с 01.03.2027 - Федеральный закон от 04.07.2026 № 235-ФЗ)\nОрганизация и осуществление регионального государственного контроля (надзора) регулируются Федеральным законом от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\".\nПоложение о региональном государственном контроле (надзоре) в сфере туристской индустрии утверждается высшим исполнительным органом субъекта Российской Федерации.\nПри осуществлении регионального государственного контроля (надзора) плановые контрольные (надзорные) мероприятия не проводятся.\nВ рамках регионального государственного контроля (надзора) может осуществляться постоянный рейд в соответствии с положениями Федерального закона от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\" (в части соблюдения требований, указанных в частях пятой и шестой настоящей статьи).\nПорядок осуществления постоянного рейда устанавливается положением о региональном государственном контроле (надзоре) в сфере туристской индустрии, утверждаемым высшим исполнительным органом субъекта Российской Федерации.\nВ случае, если в рамках выездного обследования выявлены признаки нарушения обязательных требований, допускается незамедлительное проведение контрольной закупки в соответствии с частью 7 статьи 75 Федерального закона от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\".\nКонтрольный (надзорный) орган в случае необходимости может привлекать для совершения отдельных контрольных (надзорных) действий специалистов, являющихся работниками подведомственного ему учреждения, в порядке, предусмотренном положением о региональном государственном контроле (надзоре) в сфере туристской индустрии.\n(Часть с 01.03.2027 в редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nКонтрольный (надзорный) орган, а также подведомственное этому органу государственное учреждение (в случае передачи ему полномочий по осуществлению регионального контроля (надзора) в сфере туристской индустрии либо отдельных полномочий по осуществлению регионального контроля (надзора) в сфере туристской индустрии) наряду с решениями, принимаемыми по результатам контрольных (надзорных) мероприятий в соответствии с Федеральным законом от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\", вправе: (В редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nвыдавать предписание об устранении нарушений обязательных требований, выявленных в ходе выездного обследования или наблюдения за соблюдением обязательных требований;\nвыдавать предписание владельцу агрегатора информации об услугах, владельцу сервиса объявлений о незамедлительном прекращении распространения информации о предоставляемых услугах средства размещения (гостиничных услугах);\n(Абзац с 01.03.2027 в редакции Федерального закона от 04.07.2026 № 235-ФЗ)\nв случае выявления несоответствия средства размещения требованиям к категории средств размещения, указанной в реестре классифицированных средств размещения, направлять в организацию, осуществляющую классификацию в сфере туристской индустрии, соответствующую информацию с запросом о предоставлении сведений о принятых мерах, направленных на устранение несоответствия средства размещения указанным требованиям, в том числе о проведении внепланового подтверждения соответствия средства размещения требованиям к присвоенной категории средства размещения;\nпринимать решения о приостановлении, возобновлении действия классификации средства размещения, а также о прекращении действия классификации средства размещения (об исключении сведений о средстве размещения из реестра классифицированных средств размещения);\nпринимать решения о прекращении аттестации экскурсовода (гида) и гида-переводчика и об исключении сведений о них из единого федерального реестра экскурсоводов (гидов) и гидов-переводчиков;\nвыдавать предписание владельцу агрегатора информации об услугах или владельцу сервиса размещения объявлений о незамедлительном приостановлении возможности приобретать услуги средства размещения, гостиничные услуги на сайте владельца агрегатора информации об услугах или владельца сервиса размещения объявлений в информационно-телекоммуникационной сети \"Интернет\". (Дополнение абзацем - Федеральный закон от 04.07.2026 № 235-ФЗ)\n(Дополнение статьей - Федеральный закон от 30.11.2024 № 436-ФЗ)"],
["20","Ответственность за нарушение законодательства Российской Федерации о туристской деятельности","Глава IX. Заключительные положения","","Статья 20. Ответственность за нарушение законодательства Российской Федерации о туристской деятельности\nНарушение законодательства Российской Федерации о туристской деятельности влечет за собой ответственность в соответствии с законодательством Российской Федерации."],
["21","О вступлении в силу настоящего Федерального закона","Глава IX. Заключительные положения","","Статья 21. О вступлении в силу настоящего Федерального закона\nНастоящий Федеральный закон вступает в силу со дня его официального опубликования."],
["22","Приведение нормативных правовых актов в соответствие с настоящим Федеральным законом","Глава IX. Заключительные положения","","Статья 22. Приведение нормативных правовых актов в соответствие с настоящим Федеральным законом\nПредложить Президенту Российской Федерации и поручить Правительству Российской Федерации привести свои нормативные правовые акты в соответствие с настоящим Федеральным законом.\nПрезидент Российской Федерации Б.Ельцин\nМосква, Кремль 24 ноября 1996 года № 132-ФЗ"]
];
